    // 2 to 100 characters after trimming: the extension name rule (ExtensionForm's own 100 maximum kept).
    private function nameFitsExtensionForm($name)
    {
        $len = mb_strlen(trim((string)$name), 'UTF-8');
        return $len >= 2 && $len <= 100;
    }

