// AI update open 16-04-2026
    // Every signed-in user's app reads accounts/ai (the dashboard uses it for the AI
    // Transcribe flag), so the shared payload carried the OpenAI and messaging API keys
    // to plain users. The cache holds the full payload for admins; plain users get it
    // with the keys blanked.
    private const AI_SECRET_FIELDS = [
        "token", "aiAgentChatgptToken", "transcribeToken",
        "facebookAccessToken", "facebookVerificationToken", "whatsappAccessToken", "whatsappVerificationToken",
    ];

    private function aiPayloadFor($session, string $json): string
    {
        if (!$this->isPlainUser($session)) {
            return $json;
        }
        $payload = json_decode($json, true);
        if (!is_array($payload) || !isset($payload["content"]) || !is_array($payload["content"])) {
            return $json;
        }
        foreach (self::AI_SECRET_FIELDS as $field) {
            if (array_key_exists($field, $payload["content"])) {
                $payload["content"][$field] = "";
            }
        }
        return json_encode($payload);
    }

