	public function phonetempAction($type = 1) {
		$this->view->setRenderLevel(View::LEVEL_NO_RENDER);
		$session = $this->session->get("auth");
        if (!$session) {
            return $this->response->setJsonContent([
                "result" => "error",
                "message" => "Unathorized. (Code AI1001)",
            ]);
        }
		if ($this->request->isPost()) { 
			$this->redis->del("allDialplans-" . $session["subdomain"]);
			$parameters = []; 
			$parameters["brand"] = $this->request->getPost("brand");
			$parameters["model"] = $this->request->getPost("model");
			$parameters["name"] = $this->request->getPost("name");
			$parameters["value"] = $this->request->getPost("value");
			$parameters["template_id"] = $this->request->getPost("template_id");
			$parameters["codec"] = $this->request->getPost("codec");
			$parameters["transcoding"] = intval($this->request->getPost("transcoding"));
			$parameters["negotiation"] = intval($this->request->getPost("negotiation"));

			if (!empty($parameters)) {
				$contents = file_get_contents("php://input");
				$parameters = json_decode($contents, true);
			}

			$listCacheKey = "api_cache:accounts:phonetemp:" . $session["domain_uuid"] . ":all";

			if ($type == 1) { // Create
				try {
					$phoneTemplates = new PhoneTemplates();
					$phoneTemplates->domain_uuid = $session['domain_uuid'];
					$phoneTemplates->brand = $parameters["brand"];
					$phoneTemplates->model = $parameters["model"];
					$phoneTemplates->template = $parameters["value"];
					$phoneTemplates->custom_name = $parameters["name"];
					$phoneTemplates->custom = true;

					$saveTemplate = $phoneTemplates->save();
					if (!$saveTemplate) {
						return $this->response->setJsonContent([
							"result" => "error",
							"message" => "Something went wrong.",
							"debug"   => [
								"error" => $phoneTemplates->getMessages(),
							],
						]);
					}

					$this->redis->del($listCacheKey);

					return $this->response->setJsonContent([
						"result" => "success",
						"message" => "Template successfully created.",
					]);
				} catch (\Throwable $e) {
					return $this->response->setJsonContent([
						"result" => "error",
						"message" => "Something went wrong.",
						"debug"   => [
							"error"   => ControllerBase::safeErrorMessage($e),
							"file"    => $e->getFile(),
							"line"    => $e->getLine(),
						],
					]);
				}
			}
			elseif ($type == 2) { // Delete  
				try {
                    $template = PhoneTemplates::findFirstById($parameters["template_id"]);

					if (!$template) {
						return $this->response->setJsonContent([
							"result" => "error",
							"message" => "Template not found."
						]);
					}
 
					$deleteResult = $template->delete();

					if (!$deleteResult) {
						return $this->response->setJsonContent([
							"result" => "error",
							"message" => "Failed to delete template.",
							"debug"   => $template->getMessages()
						]);
					}

					$this->redis->del($listCacheKey);

					return $this->response->setJsonContent([
						"result" => "success",
						"message" => "Template deleted successfully."
					]);
				} catch (\Throwable $e) {
					return $this->response->setJsonContent([
						"result" => "error",
						"message" => "Something went wrong.",
						"debug"   => [
							"error" => ControllerBase::safeErrorMessage($e),
							"file"  => $e->getFile(),
							"line"  => $e->getLine(),
						],
					]);
				}
			}
			elseif ($type == 3) { // Update
				try { 
					$template = PhoneTemplates::findFirstById($parameters["template_id"]);

					if (!$template) {
						return $this->response->setJsonContent([
							"result" => "error",
							"message" => "Template not found."
						]);
					}

					if (isset($parameters["brand"])) {
						$template->brand = $parameters["brand"];
					}
					if (isset($parameters["model"])) {
						$template->model = $parameters["model"];
					}
					if (isset($parameters["value"])) {
						$template->template = $parameters["value"];
					}
					if (isset($parameters["name"])) {
                        $template->custom_name = $parameters["name"];
					}

					$template->custom = true;
					$template->updated_at = date('Y-m-d H:i:s');

					$saveResult = $template->save();

					if (!$saveResult) {
						return $this->response->setJsonContent([
							"result" => "error",
							"message" => "Failed to update template.",
							"debug"   => $template->getMessages()
						]);
					}

					$this->redis->del($listCacheKey);

					return $this->response->setJsonContent([
						"result" => "success",
						"message" => "Template updated successfully.",
						"data" => $template
					]);
				} catch (\Throwable $e) {
					return $this->response->setJsonContent([
						"result" => "error",
						"message" => "Something went wrong.",
						"debug"   => [
							"error" => ControllerBase::safeErrorMessage($e),
							"file"  => $e->getFile(),
							"line"  => $e->getLine(),
						],
					]);
				}
			}
			elseif ($type == 4) { // Get all
				$cached = $this->redis->get($listCacheKey);
				if ($cached) {
					$decoded = json_decode($cached, true);
					return $this->response->setJsonContent($decoded);
				}

				$allTemplates = PhoneTemplates::find([
                    'conditions' => "domain_uuid = :domain_uuid:",
                    'bind' => [
                        'domain_uuid' => $session['domain_uuid']
                    ]
                ]);

				$responseData = [
					"result" => "success",
					"data" => $allTemplates,
				];

				$this->redis->set($listCacheKey, json_encode($responseData));
				$this->redis->expire($listCacheKey, 300);

				return $this->response->setJsonContent($responseData);
			}
			elseif ($type == 5) { // Get one
				$findTemplate = PhoneTemplates::findFirstById($parameters["template_id"]);

				if (!$findTemplate) {
					return $this->response->setJsonContent([
						"result" => "error",
						"message" => "Template not found."
					]);
				}

				return $this->response->setJsonContent([
					"result" => "success",
					"data" => $findTemplate
				]);
			}
			elseif ($type == 6) {
