                }
				$vVars2 = VSipProfileSettings::find([
                    "conditions" => "sip_profile_setting_name =:sip_profile_setting_name: OR sip_profile_setting_name =:sip_profile_setting_name2: OR sip_profile_setting_name =:sip_profile_setting_name3: OR sip_profile_setting_name =:sip_profile_setting_name4: OR sip_profile_setting_name =:sip_profile_setting_name5: ",
