    /**
     * [desk-phone-actions] Auto Provisioning > IP Phones row buttons, sent to accounts/autoprov
     * (admin-only, see ControllerBase::ADMIN_ACTIONS) as JSON {op, extension, mac_address}:
     *  - op "reboot": SIP NOTIFY check-sync to that phone's registration; refused when it isn't registered.
     *  - op "webpassword": the phone's web login (admin / generated password, see PhoneAdmin).
     *  - op "setwebpassword" {password}: the admin's own password for it, sent on the next provisioning fetch.
     * Both are written to the audit log. Returns null when the body carries no op (old autoprov use).
     */
    private function deskPhoneAction($session)
    {
        $body = json_decode((string) $this->request->getRawBody(), true);
        $op = is_array($body) ? (string) ($body["op"] ?? "") : "";
        if ($op !== "reboot" && $op !== "webpassword" && $op !== "setwebpassword") {
            return null;
        }
        if ($this->isPlainUser($session)) {
            return $this->forbiddenForUser();
        }
        $extension = trim((string) ($body["extension"] ?? ""));
        $mac = PhoneAdmin::cleanMac($body["mac_address"] ?? "");
        if (!preg_match('/^[0-9]{1,10}$/', $extension) || !preg_match('/^[0-9a-f]{12}$/', $mac)) {
            return $this->response->setJsonContent(["result" => "error", "message" => "Give the extension and the phone's MAC address."]);
        }
        $tenant = (string) $session["subdomain"];
        $macLabel = implode(":", str_split($mac, 2));

        // Only phones saved on this extension (the IP Phones list: brand@model@mac@stun@tz@host...).
        $brand = null;
        foreach ((array) $this->redis->lrange($extension . "@" . $tenant . "-macAddresses", 0, -1) as $entry) {
            $parts = explode("@", (string) $entry);
            if (count($parts) > 2 && PhoneAdmin::cleanMac($parts[2]) === $mac) {
                $brand = strtolower(trim($parts[0]));
                break;
            }
        }
        if ($brand === null) {
            return $this->response->setJsonContent(["result" => "error", "message" => "This phone isn't saved on extension {$extension} yet. Press Update first."]);
        }
        $audit = ["entity" => "{$extension} ({$macLabel})", "skipPayload" => true, "metadata" => ["extension" => $extension, "mac_address" => $macLabel, "brand" => $brand]];

        if ($op === "setwebpassword") {
            $password = (string) ($body["password"] ?? "");
            if (!PhoneAdmin::validPassword($password)) {
                return $this->response->setJsonContent(["result" => "error", "message" => "Use 6-32 letters, digits or . _ - ! @ # % * + ="]);
            }
            PhoneAdmin::setWebPassword($this->redis, $tenant, $mac, $password);
            $this->audit("ip-phone", "change-web-password", array_replace($audit, ["result" => "success"]));
            return $this->response->setJsonContent([
                "result" => "success",
                "username" => PhoneAdmin::WEB_USER,
                "password" => $password,
                "message" => "Saved. The phone gets it the next time it downloads its provisioning file.",
            ]);
        }

        if ($op === "webpassword") {
            $password = PhoneAdmin::webPassword($this->redis, $tenant, $mac, true);
            if ($password === null) {
                return $this->response->setJsonContent(["result" => "error", "message" => "Sorry, the web password couldn't be made."]);
            }
            $this->audit("ip-phone", "view-web-password", array_replace($audit, ["result" => "success"]));
            return $this->response->setJsonContent([
                "result" => "success",
                "username" => PhoneAdmin::WEB_USER,
                "password" => $password,
            ]);
        }

        $vExtension = VExtensions::findFirst([
            "conditions" => "domain_uuid = :domain_uuid: AND extension = :extension:",
            "bind" => ["domain_uuid" => $session["domain_uuid"], "extension" => intval($extension)],
            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_INT],
        ]);
        $vExtensionUsers = $vExtension ? VExtensionUsers::findFirst([
            "conditions" => "domain_uuid = :domain_uuid: AND extension_uuid = :extension_uuid:",
            "bind" => ["domain_uuid" => $session["domain_uuid"], "extension_uuid" => $vExtension->extension_uuid],
            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
        ]) : null;
        $vUser = $vExtensionUsers ? VUsers::findFirst([
            "conditions" => "domain_uuid = :domain_uuid: AND user_uuid = :user_uuid:",
            "bind" => ["domain_uuid" => $session["domain_uuid"], "user_uuid" => $vExtensionUsers->user_uuid],
            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
        ]) : null;
        if (!$vUser) {
            return $this->response->setJsonContent(["result" => "error", "message" => "Extension {$extension} not found."]);
        }

        // Provisioned phones register as the extension's SIP username (account.1.user_name etc.).
        $registrations = PhoneAdmin::registrations((string) $vUser->username, $tenant, $mac, $brand);
        if (!$registrations) {
            $registrations = PhoneAdmin::registrations($extension, $tenant, $mac, $brand);
        }
        if (!$registrations) {
            $this->audit("ip-phone", "reboot", array_replace($audit, ["result" => "failed", "metadata" => $audit["metadata"] + ["reason" => "not registered"]]));
            return $this->response->setJsonContent([
                "result" => "error",
                "code" => "offline",
                "message" => "Phone is offline / not registered",
            ]);
        }
        $sent = 0;
        foreach ($registrations as $registration) {
            if (PhoneAdmin::sendReboot($registration)) {
                $sent++;
            }
        }
        $this->audit("ip-phone", "reboot", array_replace($audit, [
            "result" => $sent > 0 ? "success" : "failed",
            "metadata" => $audit["metadata"] + ["registrations" => count($registrations), "sent" => $sent],
        ]));
        if ($sent === 0) {
            return $this->response->setJsonContent(["result" => "error", "message" => "RingQ Call Services did not accept the reboot command. Please try again."]);
        }
        return $this->response->setJsonContent([
            "result" => "success",
            "message" => "Reboot command sent",
        ]);
    }

    public function autoprovAction() {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $session = $this->session->get("auth");
        if (!$session) {
            return $this->response->setJsonContent([
                "result" => "error",
                "message" => "Unathorized. (Code AI1001)",
            ]);
        }
        if ($this->request->isPost()) {
            $rps = $this->rpsAction($session); // [sraps]
            if ($rps !== null) {
                return $rps;
            }
            $deskPhone = $this->deskPhoneAction($session);
            if ($deskPhone !== null) {
                return $deskPhone;
            }
            try {
                $parameters = [];
                $parameters["mac_address"] = $this->request->getPost("mac_address");    // Ex. 4a:93:e0:22:c8:f4
                $parameters["device"] = $this->request->getPost("device");              // Ex. Fanvil or yealink  
                $parameters["extension"] = $this->request->getPost("extension");        // Ex. 1001 
                $parameters["timezone"] = $this->request->getPost("timezone");          // Ex. Asia/Singapore
                $parameters["textConfig"] = $this->request->getPost("textConfig");        // xml content or cfg content
                $parameters["stun"] = $this->request->getPost("stun");                  // Ex. stun.l.google.com:19302
                $parameters["model"] = $this->request->getPost("model");              // Ex. X3U_Pro

				if (!empty($parameters)) {
                    $contents = file_get_contents("php://input");
                    $parameters = json_decode($contents, true);
                }

				$vExtension = VExtensions::findFirst([
					"conditions" => "domain_uuid = :domain_uuid: AND extension = :extension:",
					"bind" => [
						"domain_uuid" => $session["domain_uuid"],
						"extension" => intval($parameters["extension"]),
					],
					"bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_INT],
				]);
				if (!$vExtension) {
					return $this->response->setJsonContent([
						"result" => "error",
						"message" => "Not found in vExtension",
					]);
				}

				$parameters["caller_id"] = $vExtension->effective_caller_id_name;

				$vExtensionUsers = VExtensionUsers::findFirst([
					"conditions" => "domain_uuid = :domain_uuid: AND extension_uuid = :extension_uuid:",
					"bind" => [
						"domain_uuid" => $session["domain_uuid"],
						"extension_uuid" => $vExtension->extension_uuid
					],
					"bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
				]);
				if (!$vExtensionUsers) {
					return $this->response->setJsonContent([
						"result" => "error",
						"message" => "Not found in vExtensionUsers",
					]);
				}

				$macAddress = strtolower($parameters["mac_address"]);
				$cleanMac = str_replace(":", "", $macAddress);

				$existingUser = VUsers::findFirst([
					"conditions" => "domain_uuid = :domain_uuid: AND add_user = :mac_address: OR add_date = :mac_address:",
					"bind" => [
						"domain_uuid" => $session["domain_uuid"],
						"mac_address" => $macAddress,
					],
					"bindTypes" => [Column::BIND_PARAM_STR],
				]);

				if ($existingUser) { 
					$existingUser->add_user = null;
					$existingUser->add_date = null;

					if (!$existingUser->update()) {
						return $this->response->setJsonContent([
							"result"  => "error",
							"message" => "Failed to update existing MAC address in vUsers.",
							"debug"   => $existingUser->getMessages(),
						]);
					}
				}

				$vUser = VUsers::findFirst([
					"conditions" => "domain_uuid = :domain_uuid: AND user_uuid = :user_uuid:",
					"bind" => [
						"domain_uuid" => $session["domain_uuid"],
						"user_uuid" => $vExtensionUsers->user_uuid,
					],
					"bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
				]);

				if (!$vUser) {
					return $this->response->setJsonContent([
						"result" => "error",
						"message" => "Not found in vUser",
					]);
				}

				$vUser->add_user = $cleanMac;
				$vUser->add_date = $macAddress;

				if (!$vUser->update()) {
					return $this->response->setJsonContent([
						"result"  => "error",
						"message" => "Failed to save MAC address in vUsers.",
						"debug"   => $vUser->getMessages(),
					]);
				} 

				$parameters["username"] = $vUser->username;          // Ex. alskdjfalsdkf
				$parameters["password"] = $vUser->password;			 // Ex. $2y$10$dktiMFQwUzcrbGF1TktPWO1b1u5AbWTr0H7xkF9aD13XZxQki1ZwW
				$parameters["domain_name"] = $session['subdomain'];  // foleycochranco.ringq.ai

                $timezone = $parameters["timezone"] ?? 'UTC';
                $offsetHours = (new DateTimeZone($timezone))
                    ->getOffset(new DateTime("now", new DateTimeZone($timezone))) / 3600;

                $formattedOffset = sprintf("%+d", $offsetHours);
                $timezoneCode = $this->getTimeZoneCode($formattedOffset, $parameters["device"]);

                if ($parameters["device"] == 'fanvil') { 
					$xmlContent = $parameters["textConfig"] ?? '<?xml version="1.0" encoding="UTF-8"?><sysConf></sysConf>';

					libxml_use_internal_errors(true);
					$xmlObject = simplexml_load_string($xmlContent);
					if ($xmlObject === false) {
						return $this->response->setJsonContent([
							"result" => "error",
							"message" => "Invalid XML format in textConfig",
							"debug" => libxml_get_errors()
						]);
					}

					$xmlUpdates = [
						'TimeZone'        => $timezoneCode,
						'TimeZoneName'    => $formattedOffset,
						'STUNServerAddr'  => $parameters["stun"],
						'STUNServer'      => $parameters["stun"],
						'PhoneNumber'     => $parameters["username"],
						'DisplayName'     => $parameters["extension"] . " | " . ($parameters["caller_id"] ?? "User"),
						'SipName'         => $parameters["domain_name"],
						'RegisterAddr'    => $parameters["domain_name"],
						'RegisterUser'    => $parameters["username"],
						'RegisterPswd'    => $parameters["password"],
                        'DHCPHostname'    => $parameters["model"]
					];

					$this->updateXmlValues($xmlObject, $xmlUpdates);
					$finalXml = $xmlObject->asXML();
					$provisionKey = "provision:xml:" . $parameters["username"];
					$this->redis->set($provisionKey, $finalXml);

					return $this->response->setJsonContent([
						"result" => "success",
						"message" => "Provisioning file generated successfully.",
					]); 
				} 
				elseif ($parameters["device"] == 'yealink') {
					$macAddress = str_replace(":", "", $parameters["mac_address"]);

					$cfg = $parameters["textConfig"] ?? '';

					$cfgUpdates = [
						"account.1.label" => $parameters["extension"] . " | " . ($parameters["caller_id"] ?? "User"),
						"account.1.display_name" => $parameters["caller_id"],
						"account.1.user_name" => $parameters["username"],
						"account.1.auth_name" => $parameters["username"],
						"account.1.password" => $parameters["password"],
						"account.1.stun_server" => $parameters["stun"],
						"network.stun_server" => $parameters["stun"],
						"static.sip.nat_stun.server" => $parameters["stun"],
						"account.1.sip_server.1.address" => $parameters["domain_name"],
						"account.1.sip_server_host.legacy" => $parameters["domain_name"],
						"account.1.voice_mail.number" => '*99' . $parameters["extension"], 
						"local_time.time_zone" => $formattedOffset,
						"local_time.time_zone_name" => $timezoneCode,
						"static.auto_provision.server_url" => 'https://'. $parameters["domain_name"] . ':8443/index/' . $macAddress . '.cfg',
					];

					foreach ($cfgUpdates as $key => $value) {
						$pattern = '/^(' . preg_quote($key, '/') . ')\s*=\s*(.*)$/m';
						$cfg = preg_replace($pattern, "$1=" . $value, $cfg);
					}

					$provisionKey = "provision:cfg:" . $parameters["username"];
					$this->redis->set($provisionKey, $cfg);

					return $this->response->setJsonContent([
						"result" => "success",
						"message" => "Provisioning file generated successfully.",
					]); 
                } 
                return $this->response->setJsonContent([
                    "result" => "error",
                    "message" => "Device not available", 
                    "parameters" => $parameters
                ]);
            } catch (\Throwable $e) {
                return $this->response->setJsonContent([
                    "result" => "error",
                    "message" => "Something went wrong.",
					"debug"   => [
						"error"   => ControllerBase::safeErrorMessage($e),
						"file"    => $e->getFile(),
						"line"    => $e->getLine(),
					],
                ]);
            }
        }
    }

    public function provisionhostsAction() {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $session = $this->session->get("auth");
        if (!$session) {
            return $this->response->setJsonContent([
                "status" => "error",
                "message" => "Unauthorized. (Code AI1001)",
            ]);
        }

        try {
            // [snom-hosts] LAN IP of every live tunnel: typed on the Tunnels page for a router phone, reported by
            // the tunnel device otherwise; router_phone tells the two apart in the Host URL picker.
            $rows = $this->db->fetchAll(
                "SELECT tunnel_name,
                        device_local_ip,
                        router_phone,
                        (EXTRACT(EPOCH FROM (NOW() - last_seen)) <= :window) AS online
                   FROM tunnel_config
                  WHERE device_local_ip IS NOT NULL
                    AND device_local_ip <> ''
                    AND device_local_ip <> '0.0.0.0'
                    AND deleted_at IS NULL
                  ORDER BY tunnel_name ASC, id ASC",
                \Phalcon\Db\Enum::FETCH_ASSOC,
                ["window" => self::PROVISION_HOST_ONLINE_WINDOW]
            );
        } catch (\Throwable $e) {
            error_log("provisionhostsAction: " . $e->getMessage());
            return $this->response->setJsonContent([
                "status" => "error",
                "message" => "Tunnel list unavailable.",
            ]);
        }

        $data = [];
        foreach ($rows as $row) {
            $data[] = [
                "tunnel_name" => (string) $row["tunnel_name"],
                "device_local_ip" => (string) $row["device_local_ip"],
                "router_phone" => ($row["router_phone"] === true || $row["router_phone"] === "t" || $row["router_phone"] === 1 || $row["router_phone"] === "1"),
                "online" => ($row["online"] === true || $row["online"] === "t" || $row["online"] === 1 || $row["online"] === "1"),
            ];
        }

        // [snom-router-phone] tunnels flagged "Snom router phone", for Auto Provisioning's
        // Tunnel Router Phone picker (no LAN IP needed -- the phone is the tunnel device).
        $routerTunnels = [];
        try {
            $routerRows = $this->db->fetchAll(
                "SELECT id, tunnel_name,
                        (EXTRACT(EPOCH FROM (NOW() - last_seen)) <= :window) AS online
                   FROM tunnel_config
                  WHERE router_phone = true
                    AND deleted_at IS NULL
                  ORDER BY tunnel_name ASC, id ASC",
                \Phalcon\Db\Enum::FETCH_ASSOC,
                ["window" => self::PROVISION_HOST_ONLINE_WINDOW]
            );
            foreach ($routerRows as $row) {
                $routerTunnels[] = [
                    "id" => (string) $row["id"],
                    "tunnel_name" => (string) $row["tunnel_name"],
                    "online" => ($row["online"] === true || $row["online"] === "t" || $row["online"] === 1 || $row["online"] === "1"),
                ];
            }
        } catch (\Throwable $e) {
            error_log("provisionhostsAction router tunnels: " . $e->getMessage());
        }

        return $this->response->setJsonContent([
            "status" => "success",
            "data" => $data,
            "router_tunnels" => $routerTunnels,
        ]);
    }

    const PROVISION_HOST_ONLINE_WINDOW = 180;

    /**
     * Private (LAN) IPv4 addresses of this server's own interfaces -- loopback, Docker bridges and
     * veth pairs excluded. Lets customers provision desk phones on the same LAN as an on-premise
     * RingQ server using its local IP (registrar + config download over http on port 80).
     */
    private function serverLocalIps() {
        static $ips = null;
        if ($ips !== null) {
            return $ips;
        }
        $ips = [];
        $out = (string) @shell_exec("ip -4 -o addr show 2>/dev/null");
        foreach (explode("\n", trim($out)) as $line) {
            if (!preg_match('/^\d+:\s+(\S+)\s+inet\s+([0-9.]+)\//', trim($line), $m)) {
                continue;
            }
            $iface = $m[1];
            $ip = $m[2];
            if ($iface === "lo" || preg_match('/^(docker|br-|veth|virbr)/', $iface)) {
                continue;
            }
            // private ranges only (RFC 1918) -- public addresses are served by the FQDN
            if (filter_var($ip, FILTER_VALIDATE_IP, FILTER_FLAG_IPV4 | FILTER_FLAG_NO_PRIV_RANGE) === false
                && filter_var($ip, FILTER_VALIDATE_IP, FILTER_FLAG_IPV4) !== false) {
                $ips[] = $ip;
            }
        }
        return $ips;
    }

    private function isServerLocalIp($candidate) {
        return in_array(trim((string) $candidate), $this->serverLocalIps(), true);
    }

    /**
     * Base URL a provisioned phone uses to re-fetch its config. The server's own LAN IP -> plain
     * http on port 80 (the certificate is for the FQDN, so https to an IP fails on most phones);
     * otherwise the FQDN over https as before.
     */
    private function provisionBaseUrl($macHostUrl, $fqdn) {
        if ($macHostUrl !== "" && $this->isServerLocalIp($macHostUrl)) {
            return "http://{$macHostUrl}/provision/2db3f557e1d6";
        }
        return "https://{$fqdn}:8443/provision/2db3f557e1d6";
    }

    private function resolveProvisionHostUrl($candidate, $fqdn) {
        $candidate = trim((string) $candidate);
        if ($candidate === "" || $candidate === "null" || $candidate === $fqdn) {
            return "";
        }
        if ($this->isServerLocalIp($candidate)) {
            return $candidate;
        }
        try {
            $row = $this->db->fetchOne(
                "SELECT device_local_ip FROM tunnel_config WHERE device_local_ip = :ip LIMIT 1",
                \Phalcon\Db\Enum::FETCH_ASSOC,
                ["ip" => $candidate]
            );
        } catch (\Throwable $e) {
            error_log("resolveProvisionHostUrl: " . $e->getMessage());
            return "";
        }
        return $row ? $candidate : "";
    }

    /**
     * [snom-router-phone] Tunnel Router Phone choice per MAC from the saved device list
     * ("brand@model@mac@stun@tz@host@routerTunnelId"), so a save that does not send
     * mac_router_tunnel (My Profile, older apps) keeps it.
     */
    private function savedRouterTunnels($listKey) {
        $map = [];
        try {
            foreach ((array) $this->redis->lrange($listKey, 0, -1) as $entry) {
                $parts = explode("@", (string) $entry);
                if (count($parts) > 6 && $parts[2] !== "") {
                    $map[strtolower(str_replace([':', '-'], '', $parts[2]))] = $parts[6];
                }
            }
        } catch (\Throwable $e) {
            error_log("savedRouterTunnels: " . $e->getMessage());
        }
        return $map;
    }

    /**
     * Tunnel id this device uses as a Snom router phone, or "" for No. Only a live tunnel
     * flagged "Snom router phone" is accepted.
     */
    private function resolveRouterTunnel($macRouterTunnels, $x, $mac, $prevRouterTunnels) {
        $cleanMac = strtolower(str_replace([':', '-'], '', (string) $mac));
        $candidate = $macRouterTunnels === null
            ? ($prevRouterTunnels[$cleanMac] ?? "")
            : trim((string) ($macRouterTunnels[$x] ?? ""));
        if ($candidate === "" || !ctype_digit($candidate)) {
            return "";
        }
        try {
            $row = $this->db->fetchOne(
                "SELECT id FROM tunnel_config WHERE id = :id AND router_phone = true AND deleted_at IS NULL",
                \Phalcon\Db\Enum::FETCH_ASSOC,
                ["id" => (int) $candidate]
            );
        } catch (\Throwable $e) {
            error_log("resolveRouterTunnel: " . $e->getMessage());
            return "";
        }
        return $row ? (string) $row["id"] : "";
    }

    /**
     * Snom settings.xml: Tunnel Router Phone = Yes turns the built-in RingQ proxy on and points it
     * at this phone's generated sip-proxy.yaml; No turns it off with an empty URL.
     */
    private function applyRouterPhoneXml(&$xmlObject, $routerTunnelId, $provisionBase, $cleanMac) {
        $on = ($routerTunnelId ?? "") !== "";
        $values = [
            "ringqsbc_enabled" => $on ? "on" : "off",
            "ringqsbc_url"     => $on ? "{$provisionBase}/{$cleanMac}.yaml" : "",
        ];
        // [snom-manualip] The phone's LAN IP is typed on the Tunnels page; the phone no longer reports it.
        // Clear the IP-report URL an earlier build set (never a setup URL the template already had).
        $setupNodes = $xmlObject->xpath("//action_setup_url");
        if (count($setupNodes) > 0 && strpos((string) $setupNodes[0], ".ip?ip=") !== false) {
            $values["action_setup_url"] = "";
        }
        $this->updateXmlValues($xmlObject, $values);
        // [snom-lanip v3] Same as a hand-set router phone that works: Registrar = the phone's own LAN IP
        // plus :5060 where the RingQ proxy listens (sip-proxy.yaml), NO outbound
        // proxy, no STUN. The LAN IP is the one set on the Tunnels page; it is also filled in when the
        // settings are served (IndexController), and the phone re-reads its settings every 2 minutes, so a
        // changed IP is picked up without a reboot. No IP set yet: tenant domain.
        if ($on) {
            $this->updateXmlValues($xmlObject, ["stun_server" => ""]);
            $refresh = $xmlObject->xpath("//settings_refresh_timer");
            if (count($refresh) === 0) {
                $parent = isset($xmlObject->{"phone-settings"}) ? $xmlObject->{"phone-settings"} : $xmlObject;
                $child = $parent->addChild("settings_refresh_timer", "");
                $child->addAttribute("perm", "");
                $refresh = [$child];
            }
            $refresh[0][0] = "120";
            $lanIp = $this->routerTunnelLanIp($routerTunnelId);
            foreach ($xmlObject->xpath('//user_host[@idx="1"]') as $node) {
                $node[0] = $lanIp !== "" ? $lanIp . ":5060" : preg_replace('/:\d+$/', '', trim((string) $node));
            }
            $outbound = $xmlObject->xpath('//user_outbound[@idx="1"]');
            if (count($outbound) === 0) {
                $parent = isset($xmlObject->{"phone-settings"}) ? $xmlObject->{"phone-settings"} : $xmlObject;
                $child = $parent->addChild("user_outbound", "");
                $child->addAttribute("idx", "1");
                $child->addAttribute("perm", "");
                $outbound = [$child];
            }
            $outbound[0][0] = "";
        }
        // Templates made before this feature have no ringqsbc tags -- add them to <phone-settings>.
        $parent = isset($xmlObject->{"phone-settings"}) ? $xmlObject->{"phone-settings"} : $xmlObject;
        foreach ($values as $tag => $value) {
            if (count($xmlObject->xpath("//{$tag}")) === 0) {
                $child = $parent->addChild($tag, htmlspecialchars($value, ENT_XML1));
                $child->addAttribute("perm", "");
            }
        }
    }

    /** LAN IP of the router phone on this tunnel, or "" when it is not known yet. */
    private function routerTunnelLanIp($routerTunnelId) {
        try {
            $row = $this->db->fetchOne(
                "SELECT device_local_ip FROM tunnel_config WHERE id = :id",
                \Phalcon\Db\Enum::FETCH_ASSOC,
                ["id" => (int) $routerTunnelId]
            );
        } catch (\Throwable $e) {
            error_log("routerTunnelLanIp: " . $e->getMessage());
            return "";
        }
        $ip = trim((string) ($row["device_local_ip"] ?? ""));
        return (filter_var($ip, FILTER_VALIDATE_IP, FILTER_FLAG_IPV4) && $ip !== "0.0.0.0") ? $ip : "";
    }

    private function updateXmlValues(&$xml, $updates) {
        foreach ($xml->children() as $child) {
            $name = $child->getName();
            if (isset($updates[$name])) {
                $child[0] = $updates[$name];
            } 
            $this->updateXmlValues($child, $updates);
        }
    }

    public function getTimeZoneCode($tzName, $device) {
        $map = [];
        if ($device == 'yealink') {
            $map = [
                '-12' => 0,  // -12 Eniwetok, Kwajalein
                '-11' => 1,  // -11 Midway Island
                '-10' => 2,  // -10 US-Hawaii-Aleutian, US-Alaska-Aleutian
                '-9'  => 3,  // -9 US-Alaska Time
                '-8'  => 4,  // -8 Canada, Mexico, US-Pacific Time ...
                '-7'  => 5,  // -7 Canada, Mexico, US, Chihuahua,La Paz ...
                '-6'  => 6,  // -6 Guatemala, El Salvador, Honduras ...
                '-5'  => 7,  // -5 Bogota, Lima, Quito, Peru, Indiana, Bahamas ...
                '-4'  => 8,  // -4 Canada, Atlantic Time, San Juan ...
                '-3'  => 9,  // -3 Greenland, Argentina, Brazil, Brasilia ...
                '-2'  => 10, // -2 Brazil(no DST), Mid-Atlantic
                '-1'  => 11, // -1 Portugal(Azores), Cape Verde Islands
                '+0'  => 12, // 0 GMT, Ireland, Portugal, Spain, London ...
                '+1'  => 13, // +1 Spain, France, Germany, Italy, Netherlands ...
                '+2'  => 14, // +2 Greece, Israel, Russia, Turkey, Ukraine ...
                '+3'  => 15, // +3 East Africa Time, Iraq, Russia ...
                '+4'  => 16, // +4 Armenia, Georgia, Russia ...
                '+5'  => 17, // +5 Kazakhstan ...
                '+6'  => 18, // +6 Kazakhstan, Kyrgyzstan, Russia, Bangladesh
                '+7'  => 19, // +7 Russia, Thailand, Vietnam, Jakarta
                '+8'  => 32, // +8 China, Singapore, Hong Kong,Urumqi, Taipei ...
                '+9'  => 33, // +9 Korea(Seoul), Japan(Tokyo), Russia
                '+10' => 34, // +10 Australia, Russia, Magadan  ...
                '+11' => 35, // +11 New Caledonia, Chokurdakh, Russia
                '+12' => 36, // +12 New Zealand(Wellington, Auckland) ...
            ];
        }
        elseif ($device == 'fanvil') {
            $map = [
                '-12'       => '-48', // (UTC-12) International Date Line West
                '-11'       => '-44', // (UTC-11) American Samoa
                '-10'       => '-40', // (UTC-10) Hawaii-Aleutian, Alaska-Aleutian
                '-9:30'     => '-38', // (UTC-9:30) French Polynesia
                '-9'        => '-36', // (UTC-9) Alaska Time
