                '-3:30'     => '-14', // (UTC-3:30) New Foundland
                '-3'        => '-12', // (UTC-3) Nuuk, Buenos Aires, no DST, DST
                '-2:30'     => '-10', // (UTC-2:30) Newfoundland and Labrador
                '-2'        => '-8',  // (UTC-2) no DST, Mid-Atlantic, Greenland
                '-1'        => '-4',  // (UTC-1) Azores, Cape Verde Is
                '0'         => '0',   // (UTC) GMT, Torshavn, Dublin, Lisboa, Porto, Funchal, Las Palmas, London, Morocco
                '+1'        => '4',   // (UTC+1) Tirane, Vienna, Brussels, Caicos, Chad, Madrid, Zagreb, Prague, Kopenhagen, Paris, Berlin, Budapest, Rome, Luxembourg, Skopje, Amsterdam, Windhoek, Warsaw, Stockholm
                '+2'        => '8',   // (UTC+2) Tallinn, Helsinki, Gaza, Athens, Tel Aviv, Amman, Riga, Beirut, Kishinev, Kaliningrad, Bucharest, Damascus, Kyiv, Odessa, South Africa
                '+3'        => '12',  // (UTC+3) East Africa Time,Baghdad,Moscow,Ankara,Istanbul
                '+3:30'     => '14',  // (UTC+3:30) Tehran
                '+4'        => '16',  // (UTC+4) Yerevan, Baku, Tbilisi, Aktau, Samara, Dubai
                '+4:30'     => '18',  // (UTC+4:30) Kabul
                '+5'        => '20',  // (UTC+5) Aqtobe, Bishkek, Islamabad, Chelyabinsk
                '+5:30'     => '22',  // (UTC+5:30) Calcutta, Sri Jayawardenepura
                '+5:45'     => '23',  // (UTC+5:45) Katmandu
                '+6'        => '24',  // (UTC+6) Astana, Almaty, Omsk
                '+6:30'     => '26',  // (UTC+6:30) Naypyitaw
                '+7'        => '28',  // (UTC+7) Krasnoyarsk, Novosibirsk, Bangkok
                '+8'        => '32',  // (UTC+8) Beijing, Taipei, Singapore, Perth, Irkutsk, Ulan-Ude
                '+8:45'     => '35',  // (UTC+8:45) Eucla
                '+9'        => '36',  // (UTC+9) Seoul, Tokyo, Yakutsk, Chita
                '+9:30'     => '38',  // (UTC+9:30) Adelaide, Darwin
                '+10'       => '40',  // (UTC+10) Sydney, Melbourne, Canberra, Brisbane, Hobart, Vladivostok
                '+10:30'    => '42',  // (UTC+10:30) Lord Howe Islands
                '+11'       => '44',  // (UTC+11) Noumea, Srednekolymsk Time
                '+11:30'    => '46',  // (UTC+11:30) Norfolk Island
                '+12'       => '48',  // (UTC+12) Wellington, Auckland, Kamchatka Time
                '+12:45'    => '51',  // (UTC+12:45) Chatham Islands
                '+13'       => '52',  // (UTC+13) Nukualofa, Apia
                '+13:30'    => '54',  // (UTC+13:30) Chatham Islands
                '+14'       => '56'   // (UTC+14) Kiribati
            ];
        } 
        return $map[$tzName] ?? "12"; 
    } 

    public function avatarAction()
    {
	    $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
	    $this->response->setHeader("Content-Type", "application/json");
	    $session = $this->session->get("auth");
	    if ($session) {
	       $parameters = [];
	       $qUser = QUsers::findFirst([
	          "conditions" => "user_uuid = :user_uuid:",
	          "bind" => [
	             "user_uuid" => $session["user_uuid"],
	          ],
	          "bindTypes" => [Column::BIND_PARAM_STR],
	       ]);
	       if (!$qUser) {
	          $response = json_encode([
	             "result" => "error",
	             "message" => "Sorry, unathorized request made. (Code AA1001)",
	          ]);
	          $this->response->setContent($response);
	          return $this->response;
	       }
	       $imageName = $this->redis->get("avatar:" . $session["subdomain"] . ":" . $session["extension"]);
	       if ($imageName) {
	          $qUser->image = $imageName;
	          if (!$qUser->update()) {
	             $messages = $qUser->getMessages();
	             $message = "";
	             foreach ($messages as $error) {
	                $message .= $error . " ";
	             }
	             $response = json_encode([
	                "result" => "error",
	                "message" => trim($message) . " (Code AA1002)",
	                "content" => [],
	             ]);
	             $this->response->setContent($response);
	             return $this->response;
	          }
	          $imageFile = new \Phalcon\Image\Adapter\Gd("/var/www/ringq/public/avr/" . $imageName);
	          $imageFile->resize(300, null, Enum::WIDTH);
	          $imageFile->save("avr/" . $imageName, 95);
	          $this->redis->set($session["extension"] . ":" . $session["subdomain"], $imageName);
	          $session["image"] = $imageName;
	          $this->session->set("auth", $session);
	          $response = json_encode([
	             "result" => "success",
	             "content" => $imageName,
	          ]);
	          $this->response->setContent($response);
	          return $this->response;
	       } else {
	          $response = json_encode([
	             "result" => "error",
	             "message" => "Sorry, unathorized request made. (Code AA1003)",
	          ]);
	          $this->response->setContent($response);
	          return $this->response;
	       }
	    }
    }

