    public function callbroadcastAction($action = 0, $uuid = "", $page = 1)
    {
    	$this->view->setRenderLevel(View::LEVEL_NO_RENDER);
	    $this->response->setHeader("Content-Type", "application/json");
	    $session = $this->session->get("auth");
	    if ($session) {
	    	if ($this->request->isGet()) {
	            if ($action == 1) {
	        		$offset = $page > 1 ? intval($page) * 20 - 20 : 0;
                    $count = QCallBroadcasts::count(
                        [
                            "conditions" => "domain_uuid = :domain_uuid:",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR]
                        ]
                    );
                    $qCallBroadcasts = QCallBroadcasts::find(
                        [
                            "conditions" => "domain_uuid = :domain_uuid:",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR],
							"order" => "insert_date ASC",
                        ]
                    );
                    $index = 0;
					$content = [];
					$broadcastContacts3 = [];
					$qCallBroadcastContacts = QCallBroadcastContacts::find(
                    	[
                            "conditions" => "domain_uuid = :domain_uuid:",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],

                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR]
                    	]
                    );
                    foreach ($qCallBroadcastContacts as $qCallBroadcastContact) {
                    	array_push($broadcastContacts3, ["id" => $qCallBroadcastContact->id, "name" => $qCallBroadcastContact->title]);
                    }
					foreach ($qCallBroadcasts as $qCallBroadcast) {
						$content[$index]["id"] = $qCallBroadcast->call_broadcast_uuid;
						$content[$index]["broadcast_avmd"] = $qCallBroadcast->broadcast_avmd;
						$content[$index]["broadcast"] = $qCallBroadcast->broadcast_name;
						$content[$index]["broadcast_destination_type"] = $qCallBroadcast->broadcast_destination_type;
						$content[$index]["description"] = $qCallBroadcast->broadcast_description;
						$content[$index]["start"] = $qCallBroadcast->broadcast_start_time;
						$content[$index]["timeout"] = $qCallBroadcast->broadcast_timeout;
						$content[$index]["concurrency"] = $qCallBroadcast->broadcast_concurrent_limit;
						$content[$index]["caller_id_name"] = $qCallBroadcast->broadcast_caller_id_name;
						$content[$index]["caller_id_number"] = $qCallBroadcast->broadcast_caller_id_number;
	                    $length = 0; 
						$broadcastContacts = [];
						$broadcastContacts2 = [];
	                    $broadcastContactValues = [];
						if ($qCallBroadcast->broadcast_contacts_uuid) {
							$qCallBroadcast->broadcast_contacts_uuid = str_replace(" ", "", $qCallBroadcast->broadcast_contacts_uuid);
							$broadcastContactValues = explode(",", $qCallBroadcast->broadcast_contacts_uuid);
						}
						foreach($broadcastContactValues as $broadcastContact) {
		                    $qCallBroadcastContacts = QCallBroadcastContacts::findFirst(
		                    	[
	                                "conditions" => "domain_uuid = :domain_uuid: AND contacts_uuid = :contacts_uuid:",
	                                "bind" =>
	                                    [
	                                        "domain_uuid" => $session["domain_uuid"],
	                                        "contacts_uuid" => $broadcastContact,

	                                    ],
	                                "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR]
		                    	]
		                    );
		                    if ($qCallBroadcastContacts) {
		                    	$length += $qCallBroadcastContacts->contacts_count;
	                    		array_push($broadcastContacts, $qCallBroadcastContacts->title);
		                    	array_push($broadcastContacts2, ["id" => $qCallBroadcastContacts->id, "name" => $qCallBroadcastContacts->title]);
		                    }
						}
	                    if (!empty($broadcastContacts)) {
	                    	$broadcastContacts = implode(", ", $broadcastContacts);
	                    }
	                    if ($length != $qCallBroadcast->length) {
	                    	$qCallBroadcast->length = $length;
	                    	$qCallBroadcast->update();
	                    }
						$content[$index]["broadcast_contacts"] = $broadcastContacts;
						$content[$index]["broadcast_contacts2"] = $broadcastContacts2;
						$content[$index]["broadcast_schedule"] = unserialize($qCallBroadcast->broadcast_schedule);
						$content[$index]["broadcast_phone_numbers"] = $qCallBroadcast->broadcast_phone_numbers;
						$content[$index]["action"] = $qCallBroadcast->broadcast_destination_data;
						$content[$index]["status"] = $qCallBroadcast->status;
						$content[$index]["enabled"] = $qCallBroadcast->enabled;
						$content[$index]["counter"] = $qCallBroadcast->counter;
						$content[$index]["length"] = $length;
						$index++;
					}
                    $response = json_encode(
                        [
                            "result" => "success",
                            "message" => "",
                            "content" => $content,
                            "content2" => $broadcastContacts3,
                            "count" => $count
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
	            }
				if (!preg_match("/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i", $uuid)) {
					return $this->sendResponse($this->response, [
						"result" => "error",
						"message" => "Sorry, invalid ID provided.",
					]);
				}
	            $qCallBroadcasts = QCallBroadcasts::findFirst(
	                [
	                    "conditions" => "call_broadcast_uuid = :call_broadcast_uuid: AND domain_uuid = :domain_uuid:",
	                    "bind" =>
	                        [
	                            "call_broadcast_uuid" => $uuid,
	                            "domain_uuid" => $session["domain_uuid"],
	                        ],
	                    "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR]
	                ]
	            );
	            if (!$qCallBroadcasts) {
	                $response = json_encode(
	                    [
	                        "result" => "error",
	                        "message" => "Sorry, broadcast call already removed or non-existing. (Code AA1003)",
	                    ]
	                );
	                $this->response->setContent($response);
	                return $this->response;
	            }
	    		// TYPE 2 & 3 START AND STOP
	            if ($action == 2 || $action == 3) {
	            	// Redis to make the automation
	            	$qCallBroadcasts->status = $action == 2 ? 1 : 2;
					if (!$qCallBroadcasts->update()) {
	                    $messages = $qCallBroadcasts->getMessages();
	                    $message = "";
	                    foreach ($messages as $error) {
	                        $message .= $error . " ";
	                    }
	                    $response = json_encode(
	                        [
	                            "result" => "error",
	                            "message" => trim($message) . " (Code AA1002)",
	                            "content" => [],
	                        ]
	                    );
	                    $this->response->setContent($response);
	                    return $this->response;
	                }
	            }
	    		// TYPE 4 & 5 ENABLE AND DISABLE
	            if ($action == 4) {
					$qCallBroadcasts->counter = 0;
					if (!$qCallBroadcasts->update()) {
	                    $messages = $qCallBroadcasts->getMessages();
	                    $message = "";
	                    foreach ($messages as $error) {
	                        $message .= $error . " ";
	                    }
	                    $response = json_encode(
	                        [
	                            "result" => "error",
	                            "message" => trim($message) . " (Code AA1002)",
	                            "content" => [],
	                        ]
	                    );
	                    $this->response->setContent($response);
	                    return $this->response;
	                }
	            }
				$offset = $page > 1 ? intval($page) * 20 - 20 : 0;
                $count = QCallBroadcasts::count(
                    [
                        "conditions" => "domain_uuid = :domain_uuid:",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                            ],
                        "bindTypes" => [Column::BIND_PARAM_STR]
                    ]
                );
                $qCallBroadcasts = QCallBroadcasts::find(
                    [
                        "conditions" => "domain_uuid = :domain_uuid:",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                            ],
                        "bindTypes" => [Column::BIND_PARAM_STR],
						"order" => "insert_date ASC",
                    ]
                );
				$broadcastContacts3 = [];
				$qCallBroadcastContacts = QCallBroadcastContacts::find(
                	[
                        "conditions" => "domain_uuid = :domain_uuid:",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],

                            ],
                        "bindTypes" => [Column::BIND_PARAM_STR]
                	]
                );
                foreach ($qCallBroadcastContacts as $qCallBroadcastContact) {
                	array_push($broadcastContacts3, ["id" => $qCallBroadcastContact->id, "name" => $qCallBroadcastContact->title]);
                }
                $index = 0;
				$content = [];
				foreach ($qCallBroadcasts as $qCallBroadcast) {
					$content[$index]["id"] = $qCallBroadcast->call_broadcast_uuid;
					$content[$index]["broadcast"] = $qCallBroadcast->broadcast_name;
