                        return $this->response;
                    }
                    $contacts = unserialize($qCallBroadcastContact->contacts);
                    $response = json_encode(
                        [
                            "result" => "success",
                            "message" => "",
                            "content" => [
                            	"contacts" => $contacts,
                            	"count" => $qCallBroadcastContact->contacts_count
                            ],
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
