	                $forward_busy_enabled2 = explode(",", $forward_busy_enabled2);
	                $vExtension->forward_busy_enabled2 = $forward_busy_enabled2[$index];
	             }
	             if ($qCallBehavior->forward_no_answer_destination) {
	                $forward_no_answer_destination = $qCallBehavior->forward_no_answer_destination;
	                $forward_no_answer_destination = explode(",", $forward_no_answer_destination);
	                $vExtension->forward_no_answer_destination = $forward_no_answer_destination[$index];
