	             }
	             if (file_exists("/var/cache/fusionpbx/directory." . $session["extension"] . "@" . $session["subdomain"])) {
	                unlink("/var/cache/fusionpbx/directory." . $session["extension"] . "@" . $session["subdomain"]);
