			    ]));
			    $client->initialize();
			    $client->emit('agentprofile', ["extension" => $session["extension"], "subdomain" => $session["subdomain"], "status" => $index, "color" => $call_profiles_colors[$index]]);
             	$response = json_encode([
	                "result" => "success",
	                "message" => "Successfully, updated call profile.",
	                "content" => [],
	             ]);
	             $this->response->setContent($response);
	             return $this->response;
	          }
	       }
	    }
    }

