    public function chatsettingAction()
    {
    	$this->view->setRenderLevel(View::LEVEL_NO_RENDER);
	    $this->response->setHeader("Content-Type", "application/json");
	    $session = $this->session->get("auth");
	    if ($session) {
			$parameters = [];
			$parameters["enableOwnerManagerAssign"] = intval($this->request->getPost("enableOwnerManagerAssign", "int"));
			$parameters["enableEveryAgentQ"] = intval($this->request->getPost("enableEveryAgentQ", "int"));
			$parameters["enableRoundRobin"] = intval($this->request->getPost("enableRoundRobin", "int"));
			$parameters["defaultChatSound"] = intval($this->request->getPost("defaultChatSound", "int"));
			if (empty($parameters["enableOwnerManagerAssign"])) {
			   $contents = file_get_contents("php://input");
			   $parameters = json_decode($contents, true);
			}
			$this->redis->set("chatsettings:" . $session["subdomain"] . "-enableOwnerManagerAssign", strval($parameters["enableOwnerManagerAssign"]));
			$this->redis->set("chatsettings:" . $session["subdomain"] . "-enableEveryAgentQ", strval($parameters["enableEveryAgentQ"]));
			$this->redis->set("chatsettings:" . $session["subdomain"] . "-enableRoundRobin", strval($parameters["enableRoundRobin"]));
			$this->redis->set("chatsettings:" . $session["subdomain"] . "-defaultChatSound", strval($parameters["defaultChatSound"]));
			$response = json_encode(
			   [
			         "result" => "success",
			         "message" => "Successfully saved chat settings.",
			         "content" => "",
			   ]
			);
			$this->response->setContent($response);
			return $this->response;
	   	}
    }

    public function credentailAction($type = 1, $extension = 0)
    {
		$this->view->setRenderLevel(View::LEVEL_NO_RENDER);
		$this->response->setHeader("Content-Type", "application/json");
		if (!$this->session->has("auth")) {
			$response = json_encode([
				"result" => "error",
				"message" => "Disallowed request.",
			]);
			$this->response->setContent($response);
			return $this->response;
		}
		$session = $this->session->get("auth");
		if ($this->request->isPost()) {
			$parameters = [];
			$parameters["email"] = $this->request->getPost("email", "string");
			if (empty($parameters["email"])) {
				$contents = file_get_contents("php://input");
				$parameters = json_decode($contents, true);
			}
			$vUser = VUsers::findFirst([
				"conditions" => "domain_uuid = :domain_uuid: AND user_email = :user_email:",
				"bind" => [
				"domain_uuid" => $session["domain_uuid"],
				"user_email" => $parameters["email"],
				],
				"bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
			]);
			if ($vUser) {
				$qUser = QUsers::findFirst([
					"conditions" => "user_uuid = :user_uuid:",
					"bind" => [
					"user_uuid" => $vUser->user_uuid,
					],
					"bindTypes" => [Column::BIND_PARAM_STR],
				]);
				$newPassword = (new \Phalcon\Security\Random())->base64(16);
				if ($qUser) {
					$qUser->password = password_hash($newPassword, PASSWORD_DEFAULT);
					$qUser->update();
				}
				$verify = random_int(100000000, 999999999);
				$qrCode = new QRCode();
				$data = "https://www." . $this->config->application->publicUrl . ":8443/register/extension/" . $verify . "/" . $parameters["email"];
				$qrCode->render($data, "/var/www/ringq/public/temp/" . $verify . ".png");
				$this->redis->lrem("register2", 0, $parameters["email"]);
				$this->redis->lpush("register2", $parameters["email"]);
				$this->redis->hmset("verify2-" . $parameters["email"], [
					"verify" => $verify,
					"username" => $qUser->first_name . " " . $qUser->last_name,
					"user_uuid" => $vUser->user_uuid,
					"domain_uuid" => $vUser->domain_uuid,
					"extension_uuid" => $vUser->vExtensionUsers->vExtensions->extension_uuid,
					"subdomain" => $session["subdomain"],
					"password" => $newPassword,
				]);
				$this->redis->expire("verify2-" . $parameters["email"], 900);
				exec('/usr/bin/php /var/www/ringq/app/cli.php main main2');
				$response = json_encode([
					"result" => "success",
					"message" => "An email has been sent with QR code to the email address.",
				]);
				$this->response->setContent($response);
				return $this->response;
			} else {
				$response = json_encode([
					"result" => "error",
					"message" => "Sorry, there is no extension associated to the email address. (Code AC1000)",
				]);
				$this->response->setContent($response);
				return $this->response;
			}
		}
		if ($this->request->isGet()) {
			$ip = $this->request->getServerAddress();
			$parameters["extension"] = intval($extension);
		    $vDomain = VDomains::findFirst([
		       "conditions" => "domain_uuid = :domain_uuid:",
