					$this->redis->del($parameters["extension"] . "@" . $session["subdomain"] . "-internalCall");
					$this->redis->del($parameters["extension"] . "@" . $session["subdomain"] . "-callerExtensionInternal");

				 $this->redis->del($session["domain_uuid"] . "-extensions-cache");
				 $this->db->commit();
				 $nextExtension = 1000;
				 $maximumExtension = VExtensions::maximum([
				    "conditions" => "domain_uuid = :domain_uuid:",
				    "column" => "extension",
