				}
				// SALESFORCE
				if ($parameters["type"] == 4) {
					$parameters["username"] = $this->request->getPost("username", "string");
					$parameters["password"] = $this->request->getPost("password", "string");
					$parameters["clientId"] = $this->request->getPost("clientId", "string");
					$parameters["clientSecret"] = $this->request->getPost("clientSecret", "string");
					$parameters["url"] = $this->request->getPost("url", "string");
					$parameters["lookupOrder"] = $this->request->getPost("lookupOrder", "string");
					$parameters["contactOrder"] = $this->request->getPost("contactOrder", "string");
