					}
					if (!is_null($parameters["firewallRate"])) {
						$this->redis->set("sip-firewall-rate", $parameters["firewallRate"]);
					}
					if (!is_null($parameters["firewallDuration"])) {
						$this->redis->set("sip-firewall-duration", $parameters["firewallDuration"]);
					}
					// Sync allowed_ips + fully_allowed_ips to fail2ban ignoreip
					$allowedIpsForF2b = !empty($parameters["allowed_ips"]) ? array_filter(array_map('trim', explode(",", $parameters["allowed_ips"]))) : [];
					$fullyAllowedForF2b = $_getFullyAllowedIps();
					$mergedIgnore = array_values(array_unique(array_merge($allowedIpsForF2b, $fullyAllowedForF2b)));
					$_setFail2banIgnoreIps($mergedIgnore);
					$client = new Client(
						Client::engine(Client::CLIENT_4X, "ws://127.0.0.1:3000", [
							"persistent" => false,
						])
					);
					$client->initialize();
					$client->emit("banIp", ["blockIps" => $blockIps, "subdomain" => $session["subdomain"]]);
					if (file_exists("/var/cache/fusionpbx/dialplan." . $session["subdomain"])) {
						unlink("/var/cache/fusionpbx/dialplan." . $session["subdomain"]);
					}
					if (file_exists("/var/cache/ringq/dialplan." . $session["subdomain"])) {
						unlink("/var/cache/ringq/dialplan." . $session["subdomain"]);
					}
					$response = json_encode([
						"result" => "success",
						"message" => "Successfully, updated security.",
					]);
					$this->response->setContent($response);
					return $this->response;
				}
			}
			if ($this->request->isGet()) {
				$_getSipBlocks = function () {
					$sipBlocks = [];
					try {
						$rows = $this->db->fetchAll("SELECT ip_address::text AS ip, category, reason, failure_count, first_seen_at, last_seen_at, blocked_at, status, jail_name FROM sip_security_blocks ORDER BY last_seen_at DESC LIMIT 500");
						foreach ($rows as $r) {
							$sipBlocks[] = [
								"ip" => $r["ip"],
								"category" => $r["category"],
								"reason" => $r["reason"],
								"failure_count" => (int) $r["failure_count"],
								"first_seen_at" => $r["first_seen_at"],
								"last_seen_at" => $r["last_seen_at"],
								"blocked_at" => $r["blocked_at"],
								"status" => $r["status"],
								"jail_name" => $r["jail_name"],
							];
						}
					} catch (\Throwable $e) { error_log('sip_blocks read: ' . $e->getMessage()); }
					return $sipBlocks;
				};
				// GET accounts/restriction/3: only the live fail2ban state, for the
				// SIP Guard tab. The default read below still returns these fields
				// unless ?fail2ban=0 is passed, so existing clients are unchanged.
				if ($type == 3) {
					$fail2banStatus = $_getFail2banJailStatus();
					$response = json_encode([
						"result" => "success",
						"message" => "",
						"content" => [
							"fail2ban_jails" => $fail2banStatus["jails"],
							"fail2ban_error" => $fail2banStatus["error"],
							"fail2ban_active" => $fail2banStatus["active"],
							"sip_blocks" => $_getSipBlocks(),
						],
					]);
					$this->response->setContent($response);
					return $this->response;
				}
				if ($type == 2) {
					$qSecurityRestrictions = QSecurityRestrictions::findFirst([
						"conditions" => "domain_uuid = :domain_uuid:",
						"bind" => [
							"domain_uuid" => $session["domain_uuid"],
						],
						"bindTypes" => [Column::BIND_PARAM_STR],
					]);
					if ($qSecurityRestrictions) {
		               $allowedIps = [];
		               $blockedIps = [];
					   $blockedCountries = !empty($qSecurityRestrictions->blocked_countries) ? explode(",", $qSecurityRestrictions->blocked_countries) : [];
		               
		               $output = [];
		               $returnCode = 0;

		               // Execute iptables command to list rules
		               exec("sudo /sbin/iptables -L -n -v --line-numbers 2>&1", $output, $returnCode);
		               // Early return on failure
		               if ($returnCode !== 0) {
		                  return $this->respondWithError(400, 'Failed to retrieve iptables rules');
		               }
		               $pattern = '/
		                   ^\s*\d+\s+\S+\s+\S+\s+               # line number, pkts, bytes (more flexible with \S+)
		                   (ACCEPT|DROP|REJECT)\s+                     # target (ACCEPT or DROP)
		                   \S+\s+\S+\s+\S+\s+                   # prot, opt, in
		                   \S+\s+                               # out
		                   (\d{1,3}(?:\.\d{1,3}){3}(?:\/\d+)?)\s+ # source IP with optional subnet
		                   (\d{1,3}(?:\.\d{1,3}){3}(?:\/\d+)?)   # destination IP with optional subnet
		                   (?:\s+\/\\s(.?)\s\*\/)?          # optional comment (more lenient)
		                   \s*$
		               /x';

		               foreach ($output as $line) {
		                  $line = str_replace('\\/', '/', $line); // Clean up escaped slashes
		                  $line = trim($line);                    // Remove extra spaces
		                  if (preg_match($pattern, $line, $matches)) {
		                     $action = $matches[1];        // ACCEPT or DROP
		                     $srcAddress = $matches[2];    // Source IP (may include subnet)
		                     $destination = $matches[3];   // Destination IP/subnet
		                     $comment = isset($matches[4]) ? trim($matches[4]) : "";
		                     // Parse source subnet
		                     if (strpos($srcAddress, '/') !== false) {
		                        list($ipOnly, $ipSubnet) = explode('/', $srcAddress);
		                     } else {
		                        $ipOnly = $srcAddress;
		                        $ipSubnet = "";
		                     }
		                     // Parse destination subnet
		                     if (strpos($destination, '/') !== false) {
		                        list($destIp, $destSubnet) = explode('/', $destination);
		                     } else {
		                        $destIp = $destination;
		                        $destSubnet = "";
		                     }
		                     if ($srcAddress !== "0.0.0.0" && $srcAddress !== "0.0.0.0/0") {
		                        $entry = $srcAddress;
		                        if ($action === 'ACCEPT') {
		                        	array_push($allowedIps, $entry);
		                        } else {
		                        	array_push($blockedIps, $entry);
		                        }
		                     }
		                  } else {
		                     // error_log("No match for line: $line");
		                  }
		               }
						$allowedIps = array_unique($allowedIps);
						$blockedIps = array_unique($blockedIps);

						$response = json_encode([
							"result" => "success",
							"message" => "",
							"content" => [
								"allowed_ips" => implode(",", $allowedIps),
								"blocked_ips" => implode(",", $blockedIps),
								"allowed_descriptions" => isset($allowedDescriptions) ? $allowedDescriptions : null,
								"blocked_descriptions" => isset($blockedDescriptions) ? $blockedDescriptions : null,
	  							"blocked_countries" => implode(",", $blockedCountries),
							],
						]);
						$this->response->setContent($response);
						return $this->response;
					} else {
						$response = json_encode([
							"result" => "error",
							"message" => "An error has occured. Please check values. (Code AE1021)",
						]);
						$this->response->setContent($response);
						return $this->response;
					}

				}
				$qSecurityRestrictions = QSecurityRestrictions::findFirst([
					"conditions" => "domain_uuid = :domain_uuid:",
					"bind" => [
						"domain_uuid" => $session["domain_uuid"],
					],
					"bindTypes" => [Column::BIND_PARAM_STR],
				]);
				if ($qSecurityRestrictions) {
					$allowedIps = !empty($qSecurityRestrictions->allowed_ips) ? explode(",", $qSecurityRestrictions->allowed_ips) : [];
					$blockedIps = !empty($qSecurityRestrictions->blocked_ips) ? explode(",", $qSecurityRestrictions->blocked_ips) : [];
					$allowedDescriptions = $qSecurityRestrictions->allowed_descriptions;
 					$blockedDescriptions = $qSecurityRestrictions->blocked_descriptions;
					$blockedCountries = !empty($qSecurityRestrictions->blocked_countries) ? explode(",", $qSecurityRestrictions->blocked_countries) : [];
				   $allowedIps2 = [];
	               $blockedIps2 = [];
	               $allowedDescriptions2 = [];
 				   $blockedDescriptions2 = [];
	               $output = [];
	               $returnCode = 0;

	               exec("sudo /sbin/iptables -L -n -v --line-numbers 2>&1", $output, $returnCode);

					if ($returnCode !== 0) {
					    return $this->respondWithError(400, 'Failed to retrieve iptables rules');
					}

               $pattern = '/
                   ^\s*\d+\s+\S+\s+\S+\s+               # line number, pkts, bytes (more flexible with \S+)
                   (ACCEPT|DROP)\s+                     # target (ACCEPT or DROP)
                   \S+\s+\S+\s+\S+\s+                   # prot, opt, in
                   \S+\s+                               # out
                   (\d{1,3}(?:\.\d{1,3}){3}(?:\/\d+)?)\s+ # source IP with optional subnet
                   (\d{1,3}(?:\.\d{1,3}){3}(?:\/\d+)?)   # destination IP with optional subnet
                   (?:\s+\/\*\s*(.*?)\s*\*\/)?          # optional comment (more lenient)
                   \s*$
               /x';

					$allowedIps2 = [];
					$blockedIps2 = [];

					foreach ($output as $line) {
					    $line = trim($line);
					    if (preg_match($pattern, $line, $matches)) {
					        $action      = $matches[1];
					        $srcAddress  = $matches[2];
					        $destination = $matches[3];
                     		$comment = isset($matches[4]) ? trim($matches[4]) : "";

					        // Skip "anywhere"
					        if ($srcAddress === "0.0.0.0/0" || $srcAddress === "0.0.0.0") {
					            continue;
					        }
					        if ($action === 'ACCEPT') {
					        	$allowedDescriptions2[$srcAddress] = $comment;
					            $allowedIps2[] = $srcAddress;
					        } else {
					        	$blockedDescriptions2[$srcAddress] = $comment;
					            $blockedIps2[] = $srcAddress;
					        }
					    }
					}
					$allowedIps2 = array_unique($allowedIps2);
					$blockedIps2 = array_unique($blockedIps2);
					$sipguardEnabled = $this->redis->get("sip-guard-enabled");
					if (is_null($sipguardEnabled)) {
						$sipguardEnabled = "2";
					}
					$firewallRate = $this->redis->get("sip-firewall-rate");
					if (is_null($firewallRate)) {
						$firewallRate = "10";
					}
					$firewallDuration = $this->redis->get("sip-firewall-duration");
					if (is_null($firewallDuration)) {
						$firewallDuration = "3600";
					}
					// ?fail2ban=0 skips the slow live fail2ban calls (one sudo exec per
					// jail) and the SIP block list; the client fetches them from
					// accounts/restriction/3 when the SIP Guard tab opens.
					$includeFail2ban = (string) $this->request->getQuery("fail2ban", "string", "1") !== "0";
					$fail2banStatus = $includeFail2ban ? $_getFail2banJailStatus() : null;

					$fullyAllowed = [];
					try {
						$rows = $this->db->fetchAll("SELECT ip_address::text AS ip, description, added_by, added_at FROM fully_allowed_ips ORDER BY added_at DESC");
						foreach ($rows as $r) {
							$fullyAllowed[] = [
								"ip" => $r["ip"],
								"description" => $r["description"],
								"added_by" => $r["added_by"],
								"added_at" => $r["added_at"],
							];
						}
					} catch (\Throwable $e) { error_log('fully_allowed_ips read: ' . $e->getMessage()); }

					$auditLog = [];
					try {
						$rows = $this->db->fetchAll("SELECT occurred_at, actor, action, ip_address::text AS ip, category, reason FROM security_audit_log ORDER BY occurred_at DESC LIMIT 200");
						foreach ($rows as $r) {
							$auditLog[] = [
								"occurred_at" => $r["occurred_at"],
								"actor" => $r["actor"],
								"action" => $r["action"],
								"ip" => $r["ip"],
								"category" => $r["category"],
								"reason" => $r["reason"],
							];
						}
					} catch (\Throwable $e) { error_log('audit_log read: ' . $e->getMessage()); }

					$content = [
							"allowed_ips" => implode(",", $allowedIps),
							"blocked_ips" => implode(",", $blockedIps),
							"allowed_ips2" => implode(",", $allowedIps2),
							"blocked_ips2" => implode(",", $blockedIps2),
							"allowed_descriptions" => isset($allowedDescriptions) ? $allowedDescriptions : null,
							"blocked_descriptions" => isset($blockedDescriptions) ? $blockedDescriptions : null,
							"allowed_descriptions2" => isset($allowedDescriptions2) ? serialize($allowedDescriptions2) : null,
							"blocked_descriptions2" => isset($blockedDescriptions2) ? serialize($blockedDescriptions2) : null,
  							"blocked_countries" => implode(",", $blockedCountries),
  							"sipguardEnabled" => $sipguardEnabled,
  							"firewallRate" => $firewallRate,
  							"firewallDuration" => $firewallDuration,
							"fully_allowed_ips" => $fullyAllowed,
							"audit_log" => $auditLog,
					];
					if ($includeFail2ban) {
						$content["fail2ban_jails"] = $fail2banStatus["jails"];
						$content["fail2ban_error"] = $fail2banStatus["error"];
						$content["fail2ban_active"] = $fail2banStatus["active"];
						$content["sip_blocks"] = $_getSipBlocks();
					}
					$response = json_encode([
						"result" => "success",
						"message" => "",
						"content" => $content,
					]);
					$this->response->setContent($response);
					return $this->response;
				} else {
					$response = json_encode([
						"result" => "error",
						"message" => "An error has occured. Please check values. (Code AE1021)",
					]);
					$this->response->setContent($response);
					return $this->response;
				}
			}
		} else {
			$this->response->setContent(json_encode([
				"result" => "error",
				"message" => "Unauthorized. (Code AI1001)",
			]));
			return $this->response;
		}
    }

    public function sipprofileAction($type = 1) {
    	$this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $session = $this->session->get("auth");
        if (!$session) {
            $response = json_encode(
                [
                    "result" => "error",
                    "message" => "Sorry, unathorized request made (Code AG1000)",
                ]
            );
            $this->response->setContent($response);
            return $this->response;
        }
        if ($this->request->isGet()) {
            $parameters = array();
            $parameters["type"] = intval($type);
            if ($parameters["type"] == 1) {
				$vSipProfiles = VSipProfiles::find(
                    [
                        "conditions" => "sip_profile_enabled = :sip_profile_enabled:",
                        "columns" => "sip_profile_uuid, sip_profile_name",
                        "bind" =>
                            [
                                "sip_profile_enabled" => "true",
                            ],
                        "bindTypes" => [Column::BIND_PARAM_STR],
                    ]
                );
                $index3 = 0;
                $vSipProfiles2 = array();
                foreach($vSipProfiles as $vSipProfile) {
                    $vSipProfiles2[$index3]["sip_profile_uuid"] = $vSipProfile->sip_profile_uuid;
                    $vSipProfiles2[$index3]["sip_profile_name"] = $vSipProfile->sip_profile_name;
                    $vSipProfileSettings = VSipProfileSettings::find(
                        [
                            "conditions" => "sip_profile_uuid = :sip_profile_uuid: AND (sip_profile_setting_name =:sip_profile_setting_name: OR sip_profile_setting_name =:sip_profile_setting_name2: OR sip_profile_setting_name =:sip_profile_setting_name3: OR sip_profile_setting_name =:sip_profile_setting_name4: OR sip_profile_setting_name =:sip_profile_setting_name5: OR sip_profile_setting_name =:sip_profile_setting_name6: OR sip_profile_setting_name = :sip_profile_setting_name7: OR sip_profile_setting_name = :sip_profile_setting_name8:)",
                            "bind" =>
                                [
                                    "sip_profile_uuid" => $vSipProfile->sip_profile_uuid,
                                    "sip_profile_setting_name" => "bind-params",
                                    "sip_profile_setting_name2" => "sip-port",
                                    "sip_profile_setting_name3" => "ext-sip-ip",
                                    "sip_profile_setting_name4" => "sip-ip",
                                    "sip_profile_setting_name5" => "inbound-codec-prefs",
                                    "sip_profile_setting_name6" => "outbound-codec-prefs",
                                    "sip_profile_setting_name7" => "inbound-codec-negotiation",
                                    "sip_profile_setting_name8" => "tls"
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR, Column::BIND_PARAM_STR, Column::BIND_PARAM_STR, Column::BIND_PARAM_STR, Column::BIND_PARAM_STR, Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                        ]
                    );
                    foreach($vSipProfileSettings as $vSipProfileSetting) {
                        if ($vSipProfileSetting->sip_profile_setting_name == "bind-params") {
                            $vSipProfiles2[$index3]["bind-params"] = $vSipProfileSetting->sip_profile_setting_value;
                        }
                        if ($vSipProfileSetting->sip_profile_setting_name == "sip-port") {
                            $vSipProfiles2[$index3]["sip-port"] = $vSipProfileSetting->sip_profile_setting_value;
                        }
                        if ($vSipProfileSetting->sip_profile_setting_name == "ext-sip-ip") {
                            $vSipProfiles2[$index3]["ext-sip-ip"] = $vSipProfileSetting->sip_profile_setting_value;
                        }
                        if ($vSipProfileSetting->sip_profile_setting_name == "sip-ip") {
                            $vSipProfiles2[$index3]["sip-ip"] = $vSipProfileSetting->sip_profile_setting_value;
                        }
                        if ($vSipProfileSetting->sip_profile_setting_name == "inbound-codec-prefs") {
                            $vSipProfiles2[$index3]["inbound-codec-prefs"] = $vSipProfileSetting->sip_profile_setting_value;
                        }
                        if ($vSipProfileSetting->sip_profile_setting_name == "outbound-codec-prefs") {
                            $vSipProfiles2[$index3]["outbound-codec-prefs"] = $vSipProfileSetting->sip_profile_setting_value;
                        }
                        if ($vSipProfileSetting->sip_profile_setting_name == "inbound-codec-negotiation") {
                            $vSipProfiles2[$index3]["inbound-codec-negotiation"] = $vSipProfileSetting->sip_profile_setting_value;
                        }
                        if ($vSipProfileSetting->sip_profile_setting_name == "tls") {
                            $vSipProfiles2[$index3]["tls"] = isset($vSipProfileSetting->sip_profile_setting_value) ? $vSipProfileSetting->sip_profile_setting_value : "transport=tcp,udp";
                        }
                    }
                    $index3++;
                } 
                $response = json_encode(
                    [
                        "result" => "success",
                        "content" => [
                            "content" => $vSipProfiles2,
                        ],
                    ]
                );
                $this->response->setContent($response);
                return $this->response;
            }
        }
        if ($this->request->isPost()) {
            $security = new \Phalcon\Security\Random();
            $parameters = array();
            $parameters["type"] = intval($this->request->getPost("type", "int"));
            $parameters["sip_profile_uuid"] = $this->request->getPost("sip_profile_uuid", "string");
            $parameters["sip_profile_name"] = $this->request->getPost("sip_profile_name", "string");
            $parameters["sip_port"] = intval($this->request->getPost("sip_port", "int"));
            $parameters["sip_ip"] = $this->request->getPost("sip_ip", "string");
            $parameters["sip_ext_ip"] = $this->request->getPost("sip_ext_ip", "string");
            $parameters["sip_transport"] = $this->request->getPost("sip_transport", "string");
            $parameters["codecs"] = $this->request->getPost("codecs", "string");
            $parameters["inbound_codec_neg"] = $this->request->getPost("inbound_codec_neg", "string");
            $parameters["tls"] = intval($this->request->getPost("tls", "int"));
            $parameters["op"] = intval($this->request->getPost("op", "int"));
            $parameters["otp"] = $this->request->getPost("otp", "string");
            if (empty($parameters["sip_profile_name"])) {
                $contents = file_get_contents("php://input");
                $parameters = json_decode($contents, true);
            }
            if (!is_array($parameters)) {
                $parameters = [];
            }
            $sipOtpSend = intval($parameters["type"] ?? 0) === 4;
            $sipOp = $sipOtpSend ? intval($parameters["op"] ?? 0) : intval($parameters["type"] ?? 0);
            if (!in_array($sipOp, [1, 2, 3], true)) {
                return $this->response->setContent(json_encode([
                    "result" => "error",
                    "message" => "Unknown SIP profile action.",
                    "content" => [],
                ]));
            }
            if ($sipOp == 1 || $sipOp == 2) {
	            $sipprofileForm = new SipprofileForm();
	            if (!$sipprofileForm->isValid($parameters)) {
	                $messages = $sipprofileForm->getMessages();
	                $message = "";
	                foreach ($messages as $error) {
	                    $message .= $error . " ";
	                }
	                $response = json_encode(
	                    [
	                        "result" => "error",
	                        "message" => trim($message) . " (Code AG1001)",
	                        "content" => [],
	                    ]
	                );
	                $this->response->setContent($response);
	                return $this->response;
	            }

            }
            $sipOtpTarget = $this->sipProfileOtpTarget(array_merge($parameters, ["op" => $sipOp]));
            if ($sipOtpSend) {
                $sipProfileLabel = $sipOtpTarget["sip_profile_name"] ?? "";
                if ($sipOp === 3) {
                    $sipProfileExisting = VSipProfiles::findFirst([
                        "conditions" => "sip_profile_uuid = :sip_profile_uuid:",
                        "bind" => ["sip_profile_uuid" => $sipOtpTarget["sip_profile_uuid"]],
                        "bindTypes" => [Column::BIND_PARAM_STR],
                    ]);
                    if (!$sipProfileExisting) {
                        return $this->response->setContent(json_encode([
                            "result" => "error",
                            "message" => "Sorry, either sip profile does not exists or already deleted (Code AG1002)",
                            "content" => [],
                        ]));
                    }
                    $sipProfileLabel = $sipProfileExisting->sip_profile_name;
                }
                return $this->sendActionOtp($session, "sipprofile", $sipOtpTarget, "sipprofile_otp", [
                    "op"          => $sipOp,
                    "profileName" => $sipProfileLabel,
                    "sipIp"       => $sipOtpTarget["sip_ip"] ?? "",
                    "sipExtIp"    => $sipOtpTarget["sip_ext_ip"] ?? "",
                    "sipPort"     => $sipOtpTarget["sip_port"] ?? "",
                ]);
            }
            $sipOtpFailure = $this->checkActionOtp(
                $session,
                "sipprofile",
                $sipOtpTarget,
                $parameters["otp"] ?? "",
                "The SIP profile changed after that code was sent. Request a new code for the new values."
            );
            if ($sipOtpFailure !== null) {
                return $this->response->setContent(json_encode($sipOtpFailure));
            }
            if ($parameters["type"] == 1) {
				$exists = VSipProfiles::findFirst(
                    [
                        "conditions" => "sip_profile_name = :sip_profile_name: AND sip_profile_enabled = :sip_profile_enabled:",
                        "bind" =>
                            [
                                "sip_profile_name" => $parameters["sip_profile_name"],
                                "sip_profile_enabled" => "true",
                            ],
                        "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                    ]
                );
                if ($exists) {
                    $response = json_encode(
                        [
                            "result" => "error",
                            "message" => "Sorry, Sip profile already exists, please choose another Sip profile name (Code AG1002)",
                            "content" => [],
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                }
                $this->db->begin();
