    public function securityAction($type = 0)
    {
	    $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
	    $this->response->setHeader("Content-Type", "application/json");
	    $session = $this->session->get("auth");
	    if ($session) {
	       if ($this->request->isPost()) {
	          if ($type == 1 || $type == 3) {
	             $otpBody = json_decode((string)file_get_contents("php://input"), true);
	             $otpSubmitted = is_array($otpBody) ? ($otpBody["otp"] ?? "") : $this->request->getPost("otp", "string");
	             $otpAction = $type == 3 ? "update" : "autoupdate-on";
	             $otpFailure = $this->checkActionOtp($session, "update", ["action" => $otpAction], $otpSubmitted, "That code was sent for a different action. Request a new one.");
	             if ($otpFailure !== null) {
	                return $this->response->setJsonContent(array_merge(["version" => null], $otpFailure));
	             }
	             return $type == 3 ? $this->auditedVersionUpdate($session) : $this->enableAutoUpdate($session);
	          }
	          $parameters = [];
	          $parameters["type"] = intval($this->request->getPost("type", "int"));
	          $parameters["prefix"] = intval($this->request->getPost("prefix", "int"));
	          if (empty($parameters["prefix"])) {
	             $contents = file_get_contents("php://input");
	             $parameters = json_decode($contents, true);
	          }
			 $outboundrulesForm = new OutboundrulesForm();
	         if (!$outboundrulesForm->isValid($parameters)) {
	            $messages = $outboundrulesForm->getMessages();
	            $message = "";
	            foreach ($messages as $error) {
	               $message .= $error . " ";
	            }
	            $response = json_encode(
	               [
	                     "result" => "error",
	                     "message" => trim($message) . " (Code AA1000)",
	                     "content" => [],
	               ]
	            );
	            $this->response->setContent($response);
	            return $this->response;
	         }
	          $qSecurityRule = QSecurityRules::findFirst([
	             "conditions" => "domain_uuid = :domain_uuid:",
	             "bind" => [
	                "domain_uuid" => $session["domain_uuid"],
	             ],
	             "bindTypes" => [Column::BIND_PARAM_STR],
	          ]);
	          if ($qSecurityRule) {
	          	$this->db->begin();
	             if (intval($parameters["type"]) == 1) {
	                $prefixes = explode(",", $qSecurityRule->prefixes);
	                if (!in_array($parameters["prefix"], $prefixes)) {
	                	array_push($prefixes, $parameters["prefix"]);
	                    $prefixes = implode(",", $prefixes);
	                  	$prefixes = str_replace(" ", "", $prefixes);
	                  	$qSecurityRule->prefixes = $prefixes;
	                }
	             } elseif (intval($parameters["type"]) == 2) {
	                $prefixes = explode(",", $qSecurityRule->prefixes);
	                $prefixes2 = [];
	                foreach ($prefixes as $prefix) {
	                   if ($prefix != $parameters["prefix"]) {
	                      array_push($prefixes2, $prefix);
	                   }
	                }
	                $qSecurityRule->prefixes = implode(",", $prefixes2);
	             }
	             if (!$qSecurityRule->update()) {
	                $this->db->rollback();
	                $response = json_encode([
	                   "result" => "error",
	                   "message" => "An error has occured. Please check values. (Code AE1021)",
	                ]);
	                $this->response->setContent($response);
	                return $this->response;
	             }
	             $vDialplan = VDialplans::findFirst([
	                "conditions" => "domain_uuid = :domain_uuid: AND dialplan_uuid = :dialplan_uuid:",
	                "bind" => [
	                   "domain_uuid" => $session["domain_uuid"],
	                   "dialplan_uuid" => $qSecurityRule->security_uuid,
	                ],
