	       } else if ($this->request->isGet()) {
				if ($type == 1 || $type == 3) {
					return $this->response->setJsonContent([
						"result" => "error",
						"version" => null,
						"message" => "A verification code is required. Update the app and try again.",
					]);
				}
				if ($type == 6 || $type == 7) {
					return $this->sendUpdateOtp($session, $type == 6 ? "update" : "autoupdate-on", (string)$this->request->getQuery("version", "string", ""));
				}
				// The post-update "Getting ready for calls" checklist: the readiness run in progress
				// (rewritten every few seconds by cli.php main updateready), else the last one.
				if ($type == 8) {
					require_once __DIR__ . "/../library/UpdateReadiness.php";
					return $this->response->setJsonContent([
