					}
					foreach ($systemMemUsagePercentageHistory as $k => $v) {
						$systemMemUsagePercentageHistory[$k] = round((float)$v, 2);
					}
					foreach ($systemDiskUsagePercentageHistory as $k => $v) {
						$systemDiskUsagePercentageHistory[$k] = round((float)$v, 2);
					}

					$systemDiskUsagePercentage = $this->redis->lrange("systemDiskUsagePercentage2", -1, -1);
					$systemMemTotal = $this->redis->lrange("systemMemTotal2", -1, -1);
					$systemMemUsed = $this->redis->lrange("systemMemUsed2", -1, -1);
					$systemMemFree = $this->redis->lrange("systemMemFree2", -1, -1);
					$systemMemAvailable = $this->redis->lrange("systemMemAvailable2", -1, -1);
					$systemCoreCount = $this->redis->get("systemCoreCount");
					$totalSpaceGB = $this->redis->get("totalSpaceGB");
					
					if (is_null($systemLoadSystem)) {
						$systemLoadSystem = $this->system->getLoad(0);
					}
					if (is_null($systemLoadPercentage)) {
						$systemLoadPercentage = $this->system->getLoadPercentage(0, 2);
					}
					if (is_null($systemDiskUsagePercentage)) {
						$systemDiskUsagePercentage = $this->system->getDiskUsagePercentage();
					}
					if (is_null($systemMemTotal)) {
						$systemMemTotal = $this->system2->memTotal();
					}
					if (is_null($systemMemUsed)) {
						$systemMemUsed = $this->system2->memUsed();
					}
					if (is_null($systemMemFree)) {
						$systemMemFree = $this->system2->memFree();
					}
					if (is_null($systemMemAvailable)) {
						$systemMemAvailable = $this->system2->memAvailable();
					}
					if (is_null($systemCoreCount)) {
						$systemCoreCount = $this->system->getCoreCount();
					}
					if (is_null($totalSpaceGB)) {
						$totalSpace = disk_total_space("/");
						$totalSpaceGB = $totalSpace / (1024 * 1024 * 1024);
					}
					
					$systemIpAdress = $this->request->getServerAddress();
					$ownerUser = VExtensions::findFirst(
						[
							"conditions" => "domain_uuid = :domain_uuid:",
							"bind" => [
								"domain_uuid" => $session["domain_uuid"],
							],
							"bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_INT],
							"order" => 'extension ASC',
						]
					);
					$response = json_encode([
						"result" => "success",
						"message" => "",
						"content" => [
							"systemLoadPercentage" => (float)current($systemLoadPercentage),
							"systemLoadPercentage2" => (object)$systemLoadPercentage2,
							"systemLoadSystem" => (float)current($systemLoadSystem),
							"systemDiskUsagePercentage" => (float)current($systemDiskUsagePercentage),
							"systemDiskTotalSpace" => (float)$totalSpaceGB,
							"systemCoreCount" => isset($systemCoreCount) ? $systemCoreCount : 0,
							"systemMemTotal" => (float)current($systemMemTotal),
							"systemMemUsed" => (float)current($systemMemUsed),
							"systemMemFree" => (float)current($systemMemFree),
							"systemMemAvailable" => (float)current($systemMemAvailable),
							"systemMemUsagePercentageHistory" => (object)$systemMemUsagePercentageHistory,
							"systemDiskUsagePercentageHistory" => (object)$systemDiskUsagePercentageHistory,
							"systemIpAdress" => $systemIpAdress,
							"serverHour" => (int)date("H"),
							"sytemOwnerParner" => $ownerUser->effective_caller_id_name,
							"sytemOwnerEmail" => $ownerUser->VExtensionUsers->VUsers->user_email,
						],
					]);
					$this->response->setContent($response);
					return $this->response;
				}
				if ($type == 5) {
					$exists = $this->redis->exists("performUpdate");
					$performUpdate = 1;
					if (!$exists) {
						$performUpdate = 0;
					}
					$response = json_encode(
						[
							"result" => "success",
							"content" => [],
							"status" => $performUpdate,
							"message" => "Update status."
						]
					);
					$this->response->setContent($response);
					return $this->response;
				}
	       }
	    }
    }

	private function enableAutoUpdate($session)
	{
			$aiCacheKey = "api_cache:accounts:ai:" . $session["domain_uuid"] . ":" . $session["subdomain"];
			$this->redis->del($aiCacheKey);
			$this->redis->set($session["subdomain"] ."-autoUpdate", 1);
			$this->redis->sadd("autoUpdate", $session["subdomain"]);
			$fullname = trim(($session["firstname"] ?? "") . " " . ($session["lastname"] ?? ""));
			$this->redis->set($session["subdomain"] ."-autoUpdate-by", json_encode([
				"user_uuid" => $session["user_uuid"] ?? null,
				"username" => $session["username"] ?? null,
				"fullname" => $fullname === "" ? null : $fullname,
				"email" => $session["email"] ?? null,
				"extension" => $session["extension"] ?? null,
				"at" => date("c"),
			]));
			$this->audit("system-update", "auto-update-on", [
				"entity" => $session["subdomain"],
				"skipPayload" => true,
				"result" => "success",
			]);
			$response = json_encode([
				"result" => "success",
				"content" => "",
				"message" => "Auto-update is enabled.",
			]);
			$this->response->setContent($response);
			return $this->response;
	}

	private function disableAutoUpdate($session)
	{
			$aiCacheKey = "api_cache:accounts:ai:" . $session["domain_uuid"] . ":" . $session["subdomain"];
			$this->redis->del($aiCacheKey);
			$this->redis->del($session["subdomain"] ."-autoUpdate");
			$this->redis->del($session["subdomain"] ."-autoUpdate-by");
			$this->redis->srem("autoUpdate", $session["subdomain"]);
			$this->audit("system-update", "auto-update-off", [
				"entity" => $session["subdomain"],
				"skipPayload" => true,
				"result" => "success",
			]);
			$response = json_encode([
				"result" => "success",
				"content" => "",
				"message" => "Auto-update is disabled.",
			]);
			$this->response->setContent($response);
			return $this->response;
	}

	private function auditedVersionUpdate($session, $trigger = "manual", $runId = null)
	{
		$runId = $runId ?: bin2hex(random_bytes(8));
		$fromVersion = (string)$this->redis->get("serverVersion");
		$this->audit("system-update", "update-started", [
			"entity" => "latest",
			"skipPayload" => true,
			"result" => "success",
			"metadata" => ["trigger" => $trigger, "runId" => $runId, "fromVersion" => $fromVersion],
		]);
		try {
			$updateResponse = $this->runVersionUpdate($session);
		} catch (\Throwable $e) {
			$this->audit("system-update", "update-failed", [
				"entity" => "latest",
				"skipPayload" => true,
				"result" => "error",
				"metadata" => ["trigger" => $trigger, "runId" => $runId, "fromVersion" => $fromVersion, "message" => ControllerBase::safeErrorMessage($e)],
			]);
			throw $e;
		}
		$outcome = json_decode((string)$updateResponse->getContent(), true);
		$succeeded = is_array($outcome) && ($outcome["result"] ?? null) === "success";
		$toVersion = is_array($outcome) && !empty($outcome["version"]) ? (string)$outcome["version"] : null;
		if ($succeeded) {
			// "Successfully updated" only means the files landed; this reports when calls work again.
			require_once __DIR__ . "/../library/UpdateReadiness.php";
			UpdateReadiness::spawn($runId, $trigger, $fromVersion, (string)$toVersion);
			// The web follows this run's checklist (GET accounts/security/8) by its id.
			$updateResponse->setJsonContent($outcome + ["runId" => $runId]);
		}
		$this->audit("system-update", $succeeded ? "update-completed" : "update-failed", [
			"entity" => $toVersion ?? "latest",
			"skipPayload" => true,
			"result" => $succeeded ? "success" : "error",
			"metadata" => array_filter([
				"trigger" => $trigger,
				"runId" => $runId,
				"fromVersion" => $fromVersion,
				"toVersion" => $toVersion,
				"message" => $succeeded ? null : (is_array($outcome) ? ($outcome["message"] ?? null) : null),
			], function ($value) { return $value !== null; }),
		]);
		return $updateResponse;
	}

	private function runVersionUpdate($session)
	{
		$security = new \Phalcon\Security\Random();
			$server = '143.198.209.102';
			$user = 'ringq-customer';
			$key = 'ringqsecurepassword@62';
			exec("sudo /var/www/ringq/app/scripts/update_version.sh 2>&1 '$server' '$user' '$key' 2>&1", $output, $result);
			sleep(2);
			error_log(json_encode($output));
			error_log(PHP_EOL);
			error_log(strval($result));
			if ($result == 0) {
                        try {
                            $fileSeverResJson = $this->redis->get('update_result');
                            $response = json_decode($fileSeverResJson, true);

                            if (!$response || !isset($response["version"])) {
                                return $this->response->setJsonContent([
                                    "result" => "error",
                                    "version" => null,
                                    "message" => "Update result not found or invalid JSON.",
                                ]);
                            }

                            $this->redis->del('update_result');

                            if (!empty($response["database"]) && is_array($response["database"])) {
                                foreach ($response["database"] as $databaseUpdate) {
                                    try {
                                        $this->db->execute($databaseUpdate);
                                    } catch (\Exception $e) {
                                        error_log("DB update failed: " . $e->getMessage());
                                    }
                                }
                            }
                            $reloadcallcenter = false;
                            $vCallCenterTiers = VCallCenterTiers::find(
	                            [
	                                "conditions" => "domain_uuid = :domain_uuid:",
	                                "bind" =>
	                                    [
	                               "domain_uuid" => $session["domain_uuid"],
	                                    ],
	                                "bindTypes" => [Column::BIND_PARAM_STR],
	                            ]
	                         );
                            foreach($vCallCenterTiers as $vCallCenterTier) {
		                $vCallCenterAgent = VCallCenterAgents::findFirst(
		                    [
		                        "conditions" => "domain_uuid = :domain_uuid: AND call_center_agent_uuid = :call_center_agent_uuid:",
		                        "bind" =>
		                            [
		                                "domain_uuid" => $session["domain_uuid"],
		                                "call_center_agent_uuid" => $vCallCenterTier->call_center_agent_uuid,
		                            ],
		                        "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
		                    ]
		                );
		                if ($vCallCenterAgent) {
