	public function mcpupdateAction($step = "")
	{
		$this->view->setRenderLevel(View::LEVEL_NO_RENDER);
		$this->response->setHeader("Content-Type", "application/json");
		$this->response->setHeader("Cache-Control", "no-store");
		$session = $this->session->get("auth");
		if (!$session || empty($session["subdomain"]) || !isset($session["extension"])) {
			return $this->mcpUpdateAnswer(401, "error", "Unauthorized. (Code AI1001)");
		}
		if ($this->isPlainUser($session)) {
			return $this->forbiddenForUser();
		}
		$step = strtolower((string)$step);
		if ($step === "status") {
			if (!$this->request->isGet()) {
				return $this->mcpUpdateAnswer(405, "error", "GET required.");
			}
			$status = $this->mcpUpdateStatus($session);
			return $this->mcpUpdateAnswer(200, "success", $status["summary"], $status);
		}
		if (!in_array($step, ["run", "auto"], true)) {
			return $this->mcpUpdateAnswer(404, "error", "Use status, run or auto.");
		}
		if (!$this->request->isPost()) {
			return $this->mcpUpdateAnswer(405, "error", "POST required.");
		}
		$refusal = $this->serverWideRefusal($session);
		if ($refusal !== null) {
			return $this->mcpUpdateAnswer(403, "error", $refusal);
		}
		$body = json_decode((string)$this->request->getRawBody(), true);
		$body = is_array($body) ? $body : [];
		if (!$this->consumeMcpCall($step === "run" ? "update.run" : "update.auto_update")) {
			return $this->mcpUpdateAnswer(403, "error", "This only runs from RingQ's MCP after the change is approved. In the app, use Update or the auto-update switch, which ask for an emailed code.");
		}
		if ($step === "auto") {
			$enabled = (string)($body["enabled"] ?? "");
			if (!in_array($enabled, ["0", "1"], true)) {
				return $this->mcpUpdateAnswer(400, "error", "Send enabled 1 to turn auto-update on or 0 to turn it off.");
			}
			return $enabled === "1" ? $this->enableAutoUpdate($session) : $this->disableAutoUpdate($session);
		}
		return $this->startMcpUpdate($session, (string)($body["even_with_calls"] ?? "0") === "1", (string)($body["force"] ?? "0") === "1");
	}

	private function mcpUpdateAnswer($status, $result, $message, $content = null)
	{
		if ($status !== 200) {
			$this->response->setStatusCode($status);
		}
		$this->response->setContent(json_encode(array_filter([
			"result" => $result,
			"message" => $message,
			"content" => $content,
		], function ($v) { return $v !== null; }), JSON_UNESCAPED_SLASHES));
		return $this->response;
	}

	private function consumeMcpCall($operationId)
	{
		$callId = (string)$this->request->getHeader("X-Ringq-Mcp-Call");
		if (!preg_match('/^[0-9a-f]{16}$/', $callId)) {
			return false;
		}
		$key = "mcp_call:" . $callId;
		if ((string)$this->redis->get($key) !== $operationId) {
			return false;
		}
		return (int)$this->redis->del($key) === 1;
	}

	private function latestServerVersion()
	{
		$raw = $this->redis->get("api_cache:latestversion");
		if (!$raw) {
			$ch = curl_init("http://143.198.209.102");
			curl_setopt_array($ch, [
				CURLOPT_RETURNTRANSFER => true,
				CURLOPT_CONNECTTIMEOUT => 5,
				CURLOPT_TIMEOUT => 10,
				CURLOPT_HTTPHEADER => ["Accept: application/json"],
			]);
			$raw = curl_exec($ch);
			$code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
			curl_close($ch);
			if ($raw === false || $code < 200 || $code >= 300 || json_decode((string)$raw, true) === null) {
				return null;
			}
			$this->redis->setex("api_cache:latestversion", 600, (string)$raw);
		}
		$decoded = json_decode((string)$raw, true);
		$version = is_array($decoded) ? trim((string)($decoded["version"] ?? "")) : "";
		return $version === "" ? null : $version;
	}

	private function mcpUpdateRun()
	{
		$run = json_decode((string)$this->redis->get("mcp_update_run"), true);
		if (!is_array($run)) {
			return null;
		}
		if (($run["state"] ?? "") === "running" && !$this->redis->exists("mcp_update_lock")) {
			$run["state"] = "interrupted";
			$run["message"] = "The update stopped reporting before it finished (the web service may have restarted during it). Check update.health and the version before running it again.";
		}
		return $run;
	}

	private function mcpUpdateStatus($session)
	{
		require_once __DIR__ . "/../library/UpdateReadiness.php";
		require_once __DIR__ . "/../library/ServiceHealth.php";
		$current = \ServiceHealth::serverVersion($this->redis);
		$latest = $this->latestServerVersion();
		$available = $latest !== null && $current !== null && UpdateReadiness::isNewerVersion($latest, $current);
		$channels = \ServiceHealth::channels();
		$by = json_decode((string)$this->redis->get($session["subdomain"] . "-autoUpdate-by"), true);
		$auto = [
			"enabled" => (string)$this->redis->get($session["subdomain"] . "-autoUpdate") === "1",
			"enabledBy" => is_array($by) ? array_filter([
				"name" => $by["fullname"] ?? null,
				"extension" => $by["extension"] ?? null,
				"at" => $by["at"] ?? null,
			], function ($v) { return $v !== null; }) : null,
		];
		$run = $this->mcpUpdateRun();
		$readiness = UpdateReadiness::progress($this->redis);
		if ($latest === null) {
			$summary = "Running " . ($current ?? "an unknown version") . "; the update server could not be reached, so whether a newer version exists is unknown.";
		} elseif ($available) {
			$summary = "Running " . $current . "; version " . $latest . " is available.";
		} else {
			$summary = "Running " . ($current ?? "an unknown version") . ", the latest version (" . $latest . ").";
		}
		if (is_array($run) && in_array($run["state"] ?? "", ["running", "interrupted", "failed"], true)) {
			$summary .= " Last update through MCP: " . $run["state"] . ".";
		}
		$summary .= " Auto-update is " . ($auto["enabled"] ? "on" : "off") . ".";
		return [
			"summary" => $summary,
			"currentVersion" => $current,
			"latestVersion" => $latest,
			"updateAvailable" => $available,
			"liveCalls" => $channels["error"] === null ? count($channels["rows"]) : null,
			"liveCallsError" => $channels["error"],
			"autoUpdate" => $auto,
			"run" => $run,
			"readiness" => $readiness,
		];
	}

	private function startMcpUpdate($session, $evenWithCalls, $force = false)
	{
		require_once __DIR__ . "/../library/UpdateReadiness.php";
		require_once __DIR__ . "/../library/ServiceHealth.php";
		$current = \ServiceHealth::serverVersion($this->redis);
		$latest = $this->latestServerVersion();
		if ($latest === null) {
			return $this->mcpUpdateAnswer(502, "error", "The update server could not be reached, so nothing was started. Try again later.");
		}
		if ($current !== null && UpdateReadiness::isNewerVersion($current, $latest)) {
			return $this->mcpUpdateAnswer(409, "error", "This server runs " . $current . " and the update server offers the older " . $latest . "; installing it would move the server back, so it is refused even with force. Nothing was changed.");
		}
		if ($current !== null && !$force && !UpdateReadiness::isNewerVersion($latest, $current)) {
			return $this->mcpUpdateAnswer(409, "error", "This server already runs " . $current . " and the update server offers " . $latest . ", so there is nothing newer to install. In an emergency, send force 1 to install " . $latest . " again. Nothing was changed.");
		}
		$channels = \ServiceHealth::channels();
		if (!$evenWithCalls && ($channels["error"] !== null || count($channels["rows"]) > 0)) {
			$why = $channels["error"] !== null
				? "The number of calls in progress could not be read (" . $channels["error"] . ")"
				: "There are " . count($channels["rows"]) . " call channel(s) up on this server";
			return $this->mcpUpdateAnswer(409, "error", $why . ". The update restarts the phone services, which drops calls; wait until they end or send even_with_calls 1 to update anyway. Nothing was changed.", ["liveCalls" => count($channels["rows"])]);
		}
		$runId = bin2hex(random_bytes(8));
		if (!$this->redis->set("mcp_update_lock", $runId, "EX", 1800, "NX")) {
			return $this->mcpUpdateAnswer(409, "error", "An update is already running on this server. Follow it with update.status.", ["run" => $this->mcpUpdateRun()]);
		}
		$run = [
			"runId" => $runId,
			"state" => "running",
			"fromVersion" => $current,
			"targetVersion" => $latest,
			"evenWithCalls" => $evenWithCalls,
			"forced" => $force && $current !== null && !UpdateReadiness::isNewerVersion($latest, $current),
			"startedAt" => date("c"),
			"by" => !empty($session["mcp_staff"]) ? "RingQ support" : trim(((string)($session["firstname"] ?? "")) . " " . ((string)($session["lastname"] ?? ""))),
		];
		$this->redis->setex("mcp_update_run", 7 * 86400, json_encode($run));
		register_shutdown_function(function () use ($session, $runId, $run) {
			@ignore_user_abort(true);
			@set_time_limit(0);
			if (session_status() === PHP_SESSION_ACTIVE) {
				session_write_close();
			}
			if (function_exists("fastcgi_finish_request")) {
				fastcgi_finish_request();
			}
			$this->finishMcpUpdate($session, $runId, $run);
		});
		return $this->mcpUpdateAnswer(200, "success", ($run["forced"] ? "Reinstalling " : "The update to ") . $latest . ($run["forced"] ? " (forced, same version)" : "") . " has started (run " . $runId . "). It takes several minutes and restarts the phone services; follow it with update.status.", ["run" => $run]);
	}

	private function finishMcpUpdate($session, $runId, array $run)
	{
		try {
			$outcome = json_decode((string)$this->auditedVersionUpdate($session, "mcp", $runId)->getContent(), true);
			$ok = is_array($outcome) && ($outcome["result"] ?? null) === "success";
			$run["state"] = $ok ? "done" : "failed";
			$run["toVersion"] = is_array($outcome) ? ($outcome["version"] ?? null) : null;
			$run["message"] = is_array($outcome) ? (string)($outcome["message"] ?? "") : "The update did not report back.";
		} catch (\Throwable $e) {
			$run["state"] = "failed";
			$run["message"] = "Update failed: " . ControllerBase::safeErrorMessage($e);
		}
		$run["finishedAt"] = date("c");
		$this->redis->setex("mcp_update_run", 7 * 86400, json_encode($run));
		if ((string)$this->redis->get("mcp_update_lock") === $runId) {
			$this->redis->del("mcp_update_lock");
		}
	}

	private function sendUpdateOtp($session, $action, $targetVersion)
	{
		return $this->sendActionOtp($session, "update", ["action" => $action], "update_otp", [
			"action"         => $action,
			"currentVersion" => (string)$this->redis->get("serverVersion"),
			"targetVersion"  => $targetVersion,
		]);
	}

	public function workhoursAction($type = 1) 
	{
		$this->view->setRenderLevel(View::LEVEL_NO_RENDER);

		if ($type == 2) {
			$bk = $this->request->get("bk");
			if (!$bk || strlen($bk) < 36) {
				 return $this->response->setJsonContent(["result" => "error", "message" => "Invalid booking identifier."]);
			}
			$domain_uuid = substr($bk, 0, 36);
			$username = substr($bk, 36);

			$extension = $username; 
			try {
				$vExtensions = VExtensions::findFirst([
					"conditions" => "domain_uuid = :domain_uuid: AND number_alias = :username:",
					"bind" => ["domain_uuid" => $domain_uuid, "username" => $username]
				]);
				
				if ($vExtensions) {
					$extension = $vExtensions->extension;
				}
			} catch (\Exception $e) {
				// Fallback
			}

            $subdomain = "";
            $vDomain = VDomains::findFirst([
               "conditions" => "domain_uuid = :domain_uuid:",
               "bind" => ["domain_uuid" => $domain_uuid]
            ]);
            if ($vDomain) { 
                $subdomain = $vDomain->domain_name;
            }

			$key = "workhours:" . $extension . ":" . $subdomain;
			$content = $this->redis->get($key);
			return $this->response->setJsonContent([
				"result" => "success",
				"content" => $content ? json_decode($content, true) : []
			]);
		}

		$session = $this->session->get("auth");
		if (!$session) {
			return $this->response->setJsonContent([
				"result"  => "error",
				"message" => "Unathorized request. (Code AL1000)", 
			]);
		}

		if ($this->request->isGet()) {
			$workhoursKey = "workhours:" . $session['extension'] . ":" . $session['subdomain'];
			if (!$this->redis->exists($workhoursKey)) {
				$defaultWorkHours = [];
				foreach (['Mon', 'Tue', 'Wed', 'Thu', 'Fri'] as $day) {
					$defaultWorkHours[] = [
						'day' => $day,
						'slots' => [
							['start' => '08:00', 'end' => '17:00', 'location' => 'Remote']
						]
					];
				}
				$this->redis->set($workhoursKey, json_encode($defaultWorkHours));
			}

			if ($type == 1) { 
				$timezone = date_default_timezone_get();
				try {
					$output = [];
					exec("timedatectl | grep 'Time zone'", $output);
					if (!empty($output)) {
						// Extract value after "Time zone:"
						$parts = explode("Time zone:", $output[0]);
						if (isset($parts[1])) {
							$timezone = trim($parts[1]);
						}
					}
				} catch (\Exception $e) {
					// Fallback to PHP timezone
				}

				$key = "workhours:" . $session['extension'] . ":" . $session['subdomain'];
				$content = $this->redis->get($key);
				return $this->response->setJsonContent([
					"result" => "success",
					"content" => $content ? json_decode($content, true) : [],
					"timezone" => $timezone
				]);
			}
		}

		if ($this->request->isPost()) {
			if ($type == 1) {
				$contents = file_get_contents("php://input");
				$key = "workhours:" . $session['extension'] . ":" . $session['subdomain'];
				$this->redis->set($key, $contents);
				return $this->response->setJsonContent([
					"result" => "success",
					"message" => "Successfully saved work hours.",
				]);
			}
		}
	}

	public function scheduleAction($type = 1) 
	{
		$this->view->setRenderLevel(View::LEVEL_NO_RENDER);

		$session = $this->session->get("auth");
		if (!$session) {
			return $this->response->setJsonContent([
				"result"  => "error",
				"message" => "Unathorized request. (Code AL1000)", 
			]);
		}

		if ($this->request->isGet()) {
			if ($type == 1) { // Get all internal extensions
				try {
					$users = [];
					
					$builder = $this->modelsManager->createBuilder()
						->columns([
							"VUsers.user_email",
							"QUsers.first_name",
							"QUsers.last_name",
							"VExtensions.extension"
						])
						->from("VUsers")
						->leftJoin("QUsers", "VUsers.user_uuid = QUsers.user_uuid")
						->leftJoin("VExtensionUsers", "VUsers.user_uuid = VExtensionUsers.user_uuid AND VUsers.domain_uuid = VExtensionUsers.domain_uuid")
						->leftJoin("VExtensions", "VExtensionUsers.extension_uuid = VExtensions.extension_uuid AND VExtensionUsers.domain_uuid = VExtensions.domain_uuid")
						->where("VUsers.domain_uuid = :domain_uuid:", ["domain_uuid" => $session["domain_uuid"]])
						->andWhere("VUsers.user_uuid != :user_uuid:", ["user_uuid" => $session["user_uuid"]])
						->andWhere("VExtensions.extension != :extension:", ["extension" => $session["extension"]])
						->andWhere("VExtensions.outbound_caller_id_number IS NOT NULL AND VExtensions.outbound_caller_id_number != ''");

					$results = $builder->getQuery()->execute();

					foreach ($results as $row) {
						$users[] = [
							"user_email" => $row->user_email,
							"first_name" => $row->first_name ?: "",
							"last_name" => $row->last_name ?: "",
							"extension" => $row->extension ?: ""
						];
					}

					return $this->response->setJsonContent([
						"result" => "success",
						"content" => [
							"users" => $users
						]
					]);
				} catch (\Exception $e) {
					return $this->response->setJsonContent([
						"result" => "error",
						"message" => "Error fetching schedule data: " . ControllerBase::safeErrorMessage($e),
					]);
				}
			}
			elseif ($type == 2) { // get all created schedules
				$key = "schedule:" . $session['extension'] . ":" . $session['domain_uuid'];
				$content = $this->redis->lrange($key, 0, -1);
				$schedules = [];
				foreach ($content as $item) {
					$schedules[] = json_decode($item, true);
				}
				return $this->response->setJsonContent([
					"result" => "success",
					"content" => $schedules
				]);
			}
		}
		if ($this->request->isPost()) { 
			$key = "schedule:" . $session['extension'] . ":" . $session['domain_uuid'];
			$contents = file_get_contents("php://input");
			$data = json_decode($contents, true); 
			if ($type == 1) { // Create
				$ringqmeet = $this->ringqmeet([
					'first_name' => $session['firstname'],
					'last_name' => $session['lastname'],
					'extension_no' => $session['extension'],
					'domain' => $session['subdomain'],
					'meet_type' => 'Schedule'
				]); 

				$ringqmeetId = $ringqmeet['room_name'] ?? '';
				$data['hostName'] = $session['firstname'] . ' ' . $session['lastname'];
				$data['hostEmail'] = $session['email'];
				$data['ringqmeetId'] = $ringqmeetId;
				$data['id'] = uniqid();

                // Public links contain no participant PII or role assertions.
                $httpHost = explode(':', $this->request->getHttpHost())[0];
                $meetingLink = 'https://' . $httpHost . '/meet/m/' . rawurlencode($ringqmeetId);
                $data['ringqmeetLink'] = $meetingLink;
                $data['ringqmeetParticipantLink'] = $meetingLink;

                if (isset($data['internalUsers']) && is_array($data['internalUsers'])) {
                    foreach ($data['internalUsers'] as &$user) {
                        $email = $user['user_email'] ?? '';
                        $firstName = $user['first_name'] ?? '';
                        $lastName = $user['last_name'] ?? '';
                        $extension = $user['extension'] ?? '';
                        $user['meetLink'] = $meetingLink;
                    }
                }

				$contents = json_encode($data); 
				$this->redis->lpush($key, $contents); 

				$this->redis->lpush("email_queue", json_encode([
					"type" => "schedule",
					"data" => $data
				])); 

				return $this->response->setJsonContent([ 
					"result" => "success", 
					"message" => "Successfully created schedule.",
				]); 
			} 
			elseif ($type == 2) { // Update 
				if (!isset($data['id'])) { 
					return $this->response->setJsonContent([
						"result" => "error", 
						"message" => "Schedule ID is required."
					]); 
				}  
				$list = $this->redis->lrange($key, 0, -1); 
				foreach ($list as $index => $item) {
					$schedule = json_decode($item, true);
					if ($schedule['id'] == $data['id']) { 
						$this->redis->lset($key, $index, json_encode($data)); 
						return $this->response->setJsonContent([ 
							"result" => "success", 
							"message" => "Successfully updated schedule.",
						]);
					} 
				} 
				return $this->response->setJsonContent([
					"result" => "error", 
					"message" => "Schedule not found."
				]); 
			} 
			elseif ($type == 3) { // Delete 
				if (!isset($data['id'])) {
					return $this->response->setJsonContent([
						"result" => "error", 
						"message" => "Schedule ID is required."
					]); 
				} 
				$list = $this->redis->lrange($key, 0, -1); 
				foreach ($list as $item) { 
					$schedule = json_decode($item, true); 
					if ($schedule['id'] == $data['id']) {  
						$this->redis->lrem($key, 0, $item);
						return $this->response->setJsonContent([ 
							"result" => "success",
							"message" => "Successfully deleted schedule." ,
						]);  
					} 
				} 
				return $this->response->setJsonContent([
					"result" => "error", 
					"message" => "Schedule not found."
				]); 
			}
		}
	}

	public function bookingAction($type = 1) 
	{
		$this->view->setRenderLevel(View::LEVEL_NO_RENDER);

		if ($type == 4) { // Public booking view
			$bk = $this->request->get("bk");
			if (!$bk || strlen($bk) < 36) {
				 return $this->response->setJsonContent(["result" => "error", "message" => "Invalid booking identifier."]);
			}
			$domain_uuid = substr($bk, 0, 36);
			$username = substr($bk, 36);

			$extension = $username; 
			try {
				$vExtensions = VExtensions::findFirst([
					"conditions" => "domain_uuid = :domain_uuid: AND number_alias = :username:",
					"bind" => ["domain_uuid" => $domain_uuid, "username" => $username]
				]);
				
				if ($vExtensions) {
					$extension = $vExtensions->extension;
				}
			} catch (\Exception $e) {
				// Fallback
			}

			$key = "booking:" . $extension . ":" . $domain_uuid;
			$content = $this->redis->lrange($key, 0, -1);
			$bookings = [];
			foreach ($content as $item) {
				$data = json_decode($item, true);
				if (isset($data['isPrivate']) && ($data['isPrivate'] === true || $data['isPrivate'] === "true" || $data['isPrivate'] === 1 || $data['isPrivate'] === "1")) {
					continue;
				}

				// Skip expired bookings (where all dates are in the past)
				$isPast = false;
				if (!($data['useWorkHours'] ?? false) && isset($data['selectedDates']) && is_array($data['selectedDates']) && !empty($data['selectedDates'])) {
					$isPast = true;
					$today = date('Y-m-d');
					
					$validDates = [];
					foreach ($data['selectedDates'] as $isoDate) {
						$datePart = explode('T', $isoDate)[0];
						if ($datePart >= $today) {
							$isPast = false;
							$validDates[] = $isoDate;
						}
					}
					$data['selectedDates'] = $validDates;
				}
				if ($isPast) {
					continue;
				}

				// Calculate duration in minutes for availability check
				$durationStr = $data['duration'] ?? '30 min';
				$minutes = 0;
				if (preg_match('/(\d+)\s*hr/', $durationStr, $matches)) {
					$minutes += intval($matches[1]) * 60;
				}
				if (preg_match('/(\d+)\s*min/', $durationStr, $matches)) {
					$minutes += intval($matches[1]);
				}
				if ($minutes == 0 && is_numeric($durationStr)) {
					$minutes = intval($durationStr);
				}
				if ($minutes == 0) $minutes = 30;

				$clientBookingsKey = "client_bookings:" . ($data['id'] ?? '');
				$appointments = $this->redis->lrange($clientBookingsKey, 0, -1);
				$bookedSlots = [];
				foreach ($appointments as $apptJson) {
					$appt = json_decode($apptJson, true);
					if (!empty($appt['date']) && !empty($appt['time']) && $appt['date'] != '0000-00-00') {
						$bookedSlots[] = [
							'date' => $appt['date'],
							'time' => $appt['time'],
							'duration' => $minutes
						];
					}
				}
				$data['bookedSlots'] = $bookedSlots;

				unset($data['internalUsers']);
				unset($data['attendees']);
				unset($data['ringqmeetId']);
				unset($data['hostEmail']);
				unset($data['useWorkHours']);
				unset($data['maxParticipants']);
				unset($data['isPrivate']);
				$bookings[] = $data;
			}
			return $this->response->setJsonContent([
				"result" => "success",
				"content" => $bookings
			]);
		}

		if ($type == 5) { // Public submit booking
			if ($this->request->isPost()) {
				$bk = $this->request->get("bk");
				if (!$bk || strlen($bk) < 36) {
					 return $this->response->setJsonContent(["result" => "error", "message" => "Invalid booking identifier."]);
				}
				$domain_uuid = substr($bk, 0, 36);
				$username = substr($bk, 36);
	
				$extension = $username; 
				try {
					$vExtensions = VExtensions::findFirst([
						"conditions" => "domain_uuid = :domain_uuid: AND number_alias = :username:",
						"bind" => ["domain_uuid" => $domain_uuid, "username" => $username]
					]);
					
					if ($vExtensions) {
						$extension = $vExtensions->extension;
					}
				} catch (\Exception $e) {
					// Fallback
				}

				$contents = file_get_contents("php://input");
				$data = json_decode($contents, true);

                // Rate Limiting
                $ip = $this->request->getClientAddress();
                $rateLimitKey = "rate_limit:booking:" . $ip;
                $requestCount = $this->redis->incr($rateLimitKey);
                if ($requestCount == 1) {
                    $this->redis->expire($rateLimitKey, 60); // 1 minute window
                }
                if ($requestCount > 5) {
                    return $this->response->setJsonContent([
                        "result" => "error",
                        "message" => "Too many requests. Please try again later."
                    ]);
                }

                // Validation
                if (empty($data['userName']) || empty($data['userEmail']) || empty($data['selectedDate']) || empty($data['selectedTime'])) {
                     return $this->response->setJsonContent(["result" => "error", "message" => "Missing required fields."]);
                }
                if (!filter_var($data['userEmail'], FILTER_VALIDATE_EMAIL)) {
                     return $this->response->setJsonContent(["result" => "error", "message" => "Invalid email address."]);
                }

				$httpHost = explode(':', $this->request->getHttpHost())[0];
				$guestname = htmlspecialchars(strip_tags($data['userName'] ?? ''), ENT_QUOTES, 'UTF-8');
				$guestemail = filter_var($data['userEmail'] ?? '', FILTER_SANITIZE_EMAIL);

				// Look up the booking to get host info
				$bookings = $this->redis->lrange('booking:' . $extension . ':' . $domain_uuid, 0, -1);
				$hostFirstName = '';
				$hostLastName = '';
				foreach ($bookings as $item) {
					$booking = json_decode($item, true);
					if (isset($booking['id']) && $booking['id'] == ($data['bookingId'] ?? '')) {
						$hostParts = explode(' ', $booking['hostName'] ?? '', 2);
						$hostFirstName = $hostParts[0] ?? '';
						$hostLastName = $hostParts[1] ?? '';
						break;
					}
				}

				$ringqmeet = $this->ringqmeet([
					'first_name' => $hostFirstName,
					'last_name' => $hostLastName,
					'extension_no' => $extension,
					'domain' => $httpHost,
					'meet_type' => 'Booking'
				]);

				$appointment = [
					'id' => uniqid(),
					'userType' => 'external',
					'bookingTypeId' => $data['bookingId'] ?? '',
					'guestName' => $guestname,
					'guestEmail' => $guestemail,
					'guestNotes' => htmlspecialchars(strip_tags($data['notes'] ?? ''), ENT_QUOTES, 'UTF-8'),
					'ringqmeetId' => $ringqmeet['room_name'],
					'meetLink' => 'https://' . $httpHost . '/meet/m/' . rawurlencode((string)$ringqmeet['room_name']),
					'date' => $data['selectedDate'] ?? '',
					'time' => $data['selectedTime'] ?? '',
					'created_at' => date('Y-m-d H:i:s')
				];

				$key = "client_bookings:" . $data['bookingId'];
				$this->redis->lpush($key, json_encode($appointment));

				$this->redis->lpush("email_queue", json_encode([
					"type" => "booking",
					"userType" => "external",
					"data" => $appointment,
					"bookingId" => $data['bookingId'],
					"ownerExtension" => $extension,
					"ownerDomainUuid" => $domain_uuid,
					"ownerDomain" => $httpHost
				]));

				return $this->response->setJsonContent([ 
					"result" => "success",
					"message" => "Booking submitted successfully."
				]);
			}
		}

		$session = $this->session->get("auth");
		if (!$session) {
			return $this->response->setJsonContent([
				"result"  => "error",
				"message" => "Unathorized request. (Code AL1000)", 
			]);
		}

		if ($this->request->isGet()) {
			if ($type == 1) { // Get all internal extensions
				try {
					$users = [];
					
					$builder = $this->modelsManager->createBuilder()
						->columns([
							"VUsers.user_email",
							"QUsers.first_name",
							"QUsers.last_name",
							"VExtensions.extension"
						])
						->from("VUsers")
						->leftJoin("QUsers", "VUsers.user_uuid = QUsers.user_uuid")
						->leftJoin("VExtensionUsers", "VUsers.user_uuid = VExtensionUsers.user_uuid AND VUsers.domain_uuid = VExtensionUsers.domain_uuid")
						->leftJoin("VExtensions", "VExtensionUsers.extension_uuid = VExtensions.extension_uuid AND VExtensionUsers.domain_uuid = VExtensions.domain_uuid")
						->where("VUsers.domain_uuid = :domain_uuid:", ["domain_uuid" => $session["domain_uuid"]])
						->andWhere("VUsers.user_uuid != :user_uuid:", ["user_uuid" => $session["user_uuid"]])
						->andWhere("VExtensions.extension != :extension:", ["extension" => $session["extension"]])
						->andWhere("VExtensions.outbound_caller_id_number IS NOT NULL AND VExtensions.outbound_caller_id_number != ''");

					$results = $builder->getQuery()->execute();

					foreach ($results as $row) {
						$users[] = [
							"user_email" => $row->user_email,
							"first_name" => $row->first_name ?: "",
							"last_name" => $row->last_name ?: "",
							"extension" => $row->extension ?: ""
						];
					}

					return $this->response->setJsonContent([
						"result" => "success",
						"content" => [
							"users" => $users
						]
					]);
				} catch (\Exception $e) {
					return $this->response->setJsonContent([
						"result" => "error",
						"message" => "Error fetching booking data: " . ControllerBase::safeErrorMessage($e),
					]);
				}
			}
			elseif ($type == 2) { // get all created bookings
				$key = "booking:" . $session['extension'] . ":" . $session['domain_uuid'];
				$content = $this->redis->lrange($key, 0, -1);
				$bookings = [];
				$now = time();

				foreach ($content as $item) {
					$data = json_decode($item, true);
					$clientBookingsKey = "client_bookings:" . $data['id'];
					$appointments = $this->redis->lrange($clientBookingsKey, 0, -1);
					$data['bookedCount'] = count($appointments);
					
					$nextMeetingTs = null;
					$nextMeetingStr = null;
					$nextMeetingEndStr = null;
					$durationStr = null;
					$nextMeetingRoomId = null;
					$nextMeetingGuestName = null;

					foreach ($appointments as $apptJson) {
						$appt = json_decode($apptJson, true);
						$date = $appt['date'] ?? '';
						$time = $appt['time'] ?? '';
						
						if (empty($date) || $date == '0000-00-00') continue;

						$ts = strtotime("$date $time");
						if ($ts !== false) {
							// Calculate End Time
							$durationStr = $data['duration'] ?? '30 min';
							$minutes = 0;
							if (preg_match('/(\d+)\s*hr/', $durationStr, $matches)) {
								$minutes += intval($matches[1]) * 60;
							}
							if (preg_match('/(\d+)\s*min/', $durationStr, $matches)) {
								$minutes += intval($matches[1]);
							}
							if ($minutes == 0 && is_numeric($durationStr)) {
								$minutes = intval($durationStr);
							}
							if ($minutes == 0) $minutes = 30;

							$endTs = $ts + ($minutes * 60);

							if ($endTs > $now) {
								if ($nextMeetingTs === null || $ts < $nextMeetingTs) {
									$nextMeetingTs = $ts;
									$nextMeetingStr = date("M d, h:i A", $ts);
									$nextMeetingEndStr = date("h:i A", $endTs);
									$nextMeetingRoomId = $appt['ringqmeetId'] ?? '';
									$nextMeetingGuestName = $appt['guestName'] ?? 'Guest';
								}
							}
						}
					}
					
					$data['nextMeeting'] = $nextMeetingStr;
					$data['nextMeetingTs'] = $nextMeetingTs;
					$data['nextMeetingEnd'] = $nextMeetingEndStr;
					$data['nextMeetingDuration'] = $durationStr;
					$data['nextMeetingRoomId'] = $nextMeetingRoomId;
					$data['nextMeetingGuestName'] = $nextMeetingGuestName;

					// Check if all selected dates are in the past
					$isPast = false;
					if (!($data['useWorkHours'] ?? false) && isset($data['selectedDates']) && is_array($data['selectedDates']) && !empty($data['selectedDates'])) {
						$isPast = true;
						$today = date('Y-m-d');
						foreach ($data['selectedDates'] as $isoDate) {
							$datePart = explode('T', $isoDate)[0];
							if ($datePart >= $today) {
								$isPast = false;
								break;
							}
						}
					}
					$data['isPast'] = $isPast; 
					$bookings[] = $data;
				}
				return $this->response->setJsonContent([
					"result" => "success",
					"content" => $bookings
				]);
			}
			elseif ($type == 6) { // Get booked users list
				$bookingId = $this->request->get("id");
				if (!$bookingId) {
					 return $this->response->setJsonContent(["result" => "error", "message" => "Booking ID is required."]);
				}
				
				$key = "client_bookings:" . $bookingId;
				$content = $this->redis->lrange($key, 0, -1);
				$bookings = [];

				// Pre-fetch all rooms to efficiently check status
				$roomsRaw = $this->redis->lrange("rooms", 0, -1);
				$endedRooms = [];
				$missedRooms = [];
				foreach ($roomsRaw as $rItem) {
					$roomData = json_decode($rItem, true);
					if (isset($roomData['room_name']) && isset($roomData['status'])) {
						if ($roomData['status'] === 'ended') {
							$endedRooms[$roomData['room_name']] = true;
						} elseif ($roomData['status'] === 'missed') {
							$missedRooms[$roomData['room_name']] = true;
						}
					}
				}

				foreach ($content as $item) {
					$participant = json_decode($item, true);
					$participantRoomId = $participant['ringqmeetId'] ?? null;
					$participant['isRoomEnded'] = $participantRoomId && isset($endedRooms[$participantRoomId]);
					$participant['isRoomMissed'] = $participantRoomId && isset($missedRooms[$participantRoomId]);
					$bookings[] = $participant;
				}
				return $this->response->setJsonContent([
					"result" => "success",
					"content" => $bookings
				]);
			}
		}
		if ($this->request->isPost()) { 
			$key = "booking:" . $session['extension'] . ":" . $session['domain_uuid'];
			$contents = file_get_contents("php://input");
			$data = json_decode($contents, true); 
			if ($type == 1) { // Create
				$data['hostName'] = $session['firstname'] . ' ' . $session['lastname'];
				$data['hostEmail'] = $session['email'];
				$data['id'] = uniqid();
				$contents = json_encode($data); 
				$key = "booking:" . $session['extension'] . ":" . $session['domain_uuid'];
				$this->redis->lpush($key, $contents); 

				if (!empty($data['internalUsers'])) {
					foreach ($data['internalUsers'] as $user) {
						$ringqmeet = $this->ringqmeet([
							'first_name' => $session['firstname'] ?? '',
							'last_name' => $session['lastname'] ?? '',
							'extension_no' => $session['extension'] ?? '',
							'domain' => $session['subdomain'],
							'meet_type' => 'Booking'
						]); 

						$appointment = [
							'id' => uniqid(),
							'userType' => 'internal',
							'bookingTypeId' => $data['id'],
							'guestName' => $user['display'],
							'guestEmail' => $user['user_email'],
							'guestNotes' => '-',
							'ringqmeetId' => $ringqmeet['room_name'],
							'meetLink' => 'https://' . $session['subdomain'] . '/meet/m/' . rawurlencode((string)$ringqmeet['room_name']),
							'date' => '0000-00-00',
							'time' => '00:00 AM',
							'created_at' => date('Y-m-d H:i:s')
						];

						$this->redis->lpush("client_bookings:" . $data['id'], json_encode($appointment));

						$this->redis->lpush("email_queue", json_encode([
							"type" => "booking",
							"userType" => "internal",
							"data" => $appointment,
							"bookingId" => $data['id'],
							"ownerExtension" => $session['extension'],
							"ownerDomainUuid" => $session['domain_uuid'],
							"ownerDomain" => $session['subdomain']
						]));
					}
				}

				if (!empty($data['attendees'])) {
					$attendees = explode(', ', $data['attendees']);

					foreach($attendees as $attendee) {
						$ringqmeet = $this->ringqmeet([
							'first_name' => $session['firstname'] ?? '',
							'last_name' => $session['lastname'] ?? '',
							'extension_no' => $session['extension'] ?? '',
							'domain' => $session['subdomain'],
							'meet_type' => 'Booking'
						]); 

						$appointment = [
							'id' => uniqid(),
							'userType' => 'custom',
							'bookingTypeId' => $data['id'],
							'guestName' => '-',
							'guestEmail' => $attendee,
							'guestNotes' => '-',
							'ringqmeetId' => $ringqmeet['room_name'],
							'meetLink' => 'https://' . $session['subdomain'] . '/meet/m/' . rawurlencode((string)$ringqmeet['room_name']),
							'date' => '0000-00-00',
							'time' => '00:00 AM',
							'created_at' => date('Y-m-d H:i:s')
						];

						$this->redis->lpush("client_bookings:" . $data['id'], json_encode($appointment));

						$this->redis->lpush("email_queue", json_encode([
							"type" => "booking",
							"userType" => "custom",
							"data" => $appointment,
							"bookingId" => $data['id'],
							"ownerExtension" => $session['extension'],
							"ownerDomainUuid" => $session['domain_uuid'],
							"ownerDomain" => $session['subdomain']
						]));
					}
				}

				return $this->response->setJsonContent([ 
					"result" => "success", 
					"message" => "Successfully created booking.",
				]);
			} 
			elseif ($type == 2) { // Update 
				if (!isset($data['id'])) { 
					return $this->response->setJsonContent([
						"result" => "error", 
						"message" => "Booking ID is required."
					]); 
				}  
				$list = $this->redis->lrange($key, 0, -1); 
				foreach ($list as $index => $item) {
					$booking = json_decode($item, true);
					if ($booking['id'] == $data['id']) { 
						// Synchronize Participants
						$clientBookingsKey = "client_bookings:" . $data['id'];
						$existingParticipantsRaw = $this->redis->lrange($clientBookingsKey, 0, -1);
						$existingParticipants = [];
						$keptEmails = []; // Track emails that should remain

						foreach ($existingParticipantsRaw as $pItem) {
							$p = json_decode($pItem, true);
							// Key by email for easy lookup. 
							// Note: Using email as unique identifier for this logic.
							$email = $p['guestEmail'] ?? ($p['email'] ?? ''); // Fallback keys
							if ($email) {
								$existingParticipants[$email] = $p;
							}
						}

						// 1. Sync Internal Users
						if (!empty($data['internalUsers'])) {
							foreach ($data['internalUsers'] as $user) {
								$email = $user['user_email'];
								$keptEmails[$email] = true;

								if (!isset($existingParticipants[$email])) {
									// Add new Internal User
									$appointment = [
										'id' => uniqid(),
										'userType' => 'internal',
										'bookingTypeId' => $data['id'],
										'guestName' => $user['display'],
										'guestEmail' => $email,
										'guestNotes' => '-',
										'meetLink' => $user['meetLink'] ?? '',
										'date' => '0000-00-00',
										'time' => '00:00 AM',
										'created_at' => date('Y-m-d H:i:s')
									];
									
									// If meetLink is missing in update data, try to reconstruct it (fallback)
									if (empty($appointment['meetLink'])) {
										$ringqmeetId = $data['ringqmeetId'] ?? ($booking['ringqmeetId'] ?? '');
										$appointment['meetLink'] = 'https://' . $session['subdomain'] . '/meet/m/' . rawurlencode((string)$ringqmeetId);
									}

									$this->redis->lpush($clientBookingsKey, json_encode($appointment));
									
									$this->redis->lpush("email_queue", json_encode([
										"type" => "booking",
										"userType" => "internal",
										"data" => $appointment,
										"bookingId" => $data['id'],
										"ownerExtension" => $session['extension'],
										"ownerDomainUuid" => $session['domain_uuid'],
										"ownerDomain" => $session['subdomain']
									]));
								}
							}
						}

						// 2. Sync Custom Attendees
						if (!empty($data['attendees'])) {
							$attendees = preg_split('/\s*,\s*/', $data['attendees'], -1, PREG_SPLIT_NO_EMPTY);
							foreach($attendees as $attendeeEmail) {
								$keptEmails[$attendeeEmail] = true;

								if (!isset($existingParticipants[$attendeeEmail])) {
									// Add new Custom Attendee
									$ringqmeetId = $data['ringqmeetId'] ?? ($booking['ringqmeetId'] ?? '');
									$appointment = [
										'id' => uniqid(),
										'userType' => 'custom',
										'bookingTypeId' => $data['id'],
										'guestName' => '-',
										'guestEmail' => $attendeeEmail,
										'guestNotes' => '-',
									'meetLink' => 'https://' . $session['subdomain'] . '/meet/m/' . rawurlencode((string)$ringqmeetId),
										'date' => '0000-00-00',
										'time' => '00:00 AM',
										'created_at' => date('Y-m-d H:i:s')
									];

									$this->redis->lpush($clientBookingsKey, json_encode($appointment));

									$this->redis->lpush("email_queue", json_encode([
										"type" => "booking",
										"userType" => "custom",
										"data" => $appointment,
										"bookingId" => $data['id'],
										"ownerExtension" => $session['extension'],
										"ownerDomainUuid" => $session['domain_uuid'],
										"ownerDomain" => $session['subdomain']
									]));
								}
							}
						}

						// 3. Remove Deleted Participants
						foreach ($existingParticipantsRaw as $pItem) {
							$p = json_decode($pItem, true);
							$email = $p['guestEmail'] ?? ($p['email'] ?? '');
							$uType = $p['userType'] ?? 'external';

							// Only remove Internal or Custom users who are NOT in the kept list
							if (($uType == 'internal' || $uType == 'custom') && !isset($keptEmails[$email])) {
								$this->redis->lrem($clientBookingsKey, 0, $pItem);
							}
						}

						$this->redis->lset($key, $index, json_encode($data)); 
						return $this->response->setJsonContent([ 
							"result" => "success", 
							"message" => "Successfully updated booking.", 
						]);
					} 
				} 
				return $this->response->setJsonContent([
					"result" => "error", 
					"message" => "Booking not found."
				]); 
			} 
			elseif ($type == 3) { // Delete 
				if (!isset($data['id'])) {
					return $this->response->setJsonContent([
						"result" => "error", 
						"message" => "Booking ID is required."
					]); 
				} 
				$list = $this->redis->lrange($key, 0, -1); 
				foreach ($list as $item) { 
					$booking = json_decode($item, true); 
					if ($booking['id'] == $data['id']) {
						$this->redis->lrem($key, 0, $item);
						$this->redis->del("client_bookings:" . $data['id']);
						return $this->response->setJsonContent([ 
							"result" => "success",
							"message" => "Successfully deleted booking." ,
						]);
					} 
				} 
				return $this->response->setJsonContent([
					"result" => "error", 
					"message" => "Booking not found."
				]); 
			} 
			elseif ($type == 7) { // Delete Participant
				if (!isset($data['id']) || !isset($data['bookingId'])) {
					return $this->response->setJsonContent([
						"result" => "error", 
						"message" => "Participant ID and Booking ID are required."
					]); 
				} 
				$key = "client_bookings:" . $data['bookingId'];
				$list = $this->redis->lrange($key, 0, -1); 
				$deletedParticipant = null;

				foreach ($list as $item) { 
					$participant = json_decode($item, true); 
					if (($participant['id'] ?? '') == $data['id']) {
						$this->redis->lrem($key, 0, $item);
						$deletedParticipant = $participant;
						break;
					} 
				} 

				if ($deletedParticipant) {
					// Update parent booking definition if Internal or Custom
					$userType = $deletedParticipant['userType'] ?? 'external';
					if ($userType == 'internal' || $userType == 'custom') {
						$parentKey = "booking:" . $session['extension'] . ":" . $session['domain_uuid'];
						$parentList = $this->redis->lrange($parentKey, 0, -1);
						
						foreach ($parentList as $index => $parentItem) {
							$bookingDef = json_decode($parentItem, true);
							if (($bookingDef['id'] ?? '') == $data['bookingId']) {
								$updated = false;
								$emailToRemove = $deletedParticipant['guestEmail'] ?? '';

								if ($userType == 'internal' && isset($bookingDef['internalUsers'])) {
									$newInternalUsers = [];
									foreach ($bookingDef['internalUsers'] as $u) {
										if (($u['user_email'] ?? '') != $emailToRemove) {
											$newInternalUsers[] = $u;
										} else {
											$updated = true;
										}
									}
									$bookingDef['internalUsers'] = $newInternalUsers;
								}

								if ($userType == 'custom' && isset($bookingDef['attendees'])) {
									$attendeesStr = $bookingDef['attendees'];
									// Split by comma, handling potential spaces
									$attendeesArr = preg_split('/\s*,\s*/', $attendeesStr, -1, PREG_SPLIT_NO_EMPTY);
									$newAttendees = [];
									foreach ($attendeesArr as $att) {
										if ($att != $emailToRemove) {
											$newAttendees[] = $att;
										} else {
											$updated = true;
										}
									}
									$bookingDef['attendees'] = implode(', ', $newAttendees);
								}

								if ($updated) {
									$this->redis->lset($parentKey, $index, json_encode($bookingDef));
								}
								break;
							}
						}
					}

					// Queue cancellation email ONLY if it's an upcoming booking
					$date = $deletedParticipant['date'] ?? '';
					$time = $deletedParticipant['time'] ?? '';
					$isUpcoming = false;
					if (!empty($date) && $date != '0000-00-00') {
						$ts = strtotime("$date $time");
						if ($ts !== false && $ts > time()) {
							$isUpcoming = true;
						}
					}

					if ($isUpcoming) {
						$this->redis->lpush("email_queue", json_encode([
							"type" => "booking_cancellation",
							"bookingId" => $data['bookingId'],
							"data" => $deletedParticipant,
							"ownerExtension" => $session['extension'],
							"ownerDomainUuid" => $session['domain_uuid'],
							"ownerDomain" => $session['subdomain']
						]));
					}

					return $this->response->setJsonContent([ 
						"result" => "success",
						"message" => "Successfully cancelled participant booking." ,
					]);
				}

				return $this->response->setJsonContent([
					"result" => "error", 
					"message" => "Participant not found."
				]); 
			} 
			elseif ($type == 8) { // Mark Room Missed
				if (!isset($data['ringqmeetId'])) {
					return $this->response->setJsonContent([
						"result" => "error", 
						"message" => "ringqmeetId is required."
					]); 
				} 

				$targetRoomId = $data['ringqmeetId'];

				if ($targetRoomId) {
					$roomsRaw = $this->redis->lrange('rooms', 0, -1);
					foreach ($roomsRaw as $roomKey => $roomItem) {
						if (($roomData['room_name'] ?? '') == $targetRoomId) {
							$this->redis->lrem('rooms', 0, $roomItem);
							$roomData['time_ended'] = date('g:i A');
							$roomData['status'] = 'missed';
							$this->redis->rpush('rooms', json_encode($roomData)); 

							return $this->response->setJsonContent([ 
								"result" => "success",
								"message" => "Room successfully marked as missed."
							]);
						}
					} 

					return $this->response->setJsonContent([ 
						"result" => "success",
						"message" => "No active room found to end."
					]);
				}

				return $this->response->setJsonContent([
					"result" => "error", 
					"message" => "Missing room ID."
				]); 
			}
		}
	}

	public function webinarAction($type = 1) 
	{
		$this->view->setRenderLevel(View::LEVEL_NO_RENDER);

		if ($type == 4) { // Public webinar view
			$id = $this->request->get("id");
			if (!$id) {
				 return $this->response->setJsonContent(["result" => "error", "message" => "Webinar ID is required."]);
			}
			$key = "webinar_details:" . $id;
			$content = $this->redis->get($key);
			return $this->response->setJsonContent([
				"result" => "success",
				"content" => $content ? json_decode($content, true) : null
			]);
		}

		if ($type == 5) { // Public submit registration
			if ($this->request->isPost()) {
				$contents = file_get_contents("php://input");
				$data = json_decode($contents, true);
				$id = $data['id'] ?? '';

                if (empty($data['firstName']) || empty($data['lastName']) || empty($data['email'])) {
                     return $this->response->setJsonContent(["result" => "error", "message" => "Missing required fields."]);
                }

				$webinarKey = "webinar_details:" . $id;
				$webinarContent = $this->redis->get($webinarKey);
				$ringqmeetId = '';
				if ($webinarContent) {
					$webinarData = json_decode($webinarContent, true);
					$ringqmeetId = $webinarData['ringqmeetId'] ?? '';
				}

				$registration = [
					'id' => uniqid(),
					'webinarId' => $id,
					'firstName' => htmlspecialchars(strip_tags($data['firstName'] ?? ''), ENT_QUOTES, 'UTF-8'),
					'lastName' => htmlspecialchars(strip_tags($data['lastName'] ?? ''), ENT_QUOTES, 'UTF-8'),
					'email' => filter_var($data['email'] ?? '', FILTER_SANITIZE_EMAIL),
					'notes' => htmlspecialchars(strip_tags($data['notes'] ?? ''), ENT_QUOTES, 'UTF-8'),
					'meetLink' => 'https://' . explode(':', $this->request->getHttpHost())[0] . '/meet/m/' . rawurlencode((string)$ringqmeetId),
					'created_at' => date('Y-m-d H:i:s')
				];

				$key = "webinar_participants:" . $id;
				$this->redis->lpush($key, json_encode($registration));

				$this->redis->lpush("email_queue", json_encode([
					"type" => "webinar",
					"data" => $registration,
					"webinarId" => $id
				]));

				return $this->response->setJsonContent([
					"result" => "success",
					"message" => "Registration successful."
				]);
			}
		}

		$session = $this->session->get("auth");
		if (!$session) {
			return $this->response->setJsonContent([
				"result"  => "error",
				"message" => "Unathorized request. (Code AL1000)", 
			]);
		}

		if ($this->request->isGet()) {
			if ($type == 2) { // get all created webinars
				$key = "webinars:" . $session['extension'] . ":" . $session['domain_uuid'];
				$content = $this->redis->lrange($key, 0, -1);
				$webinars = [];
				$now = time();

				foreach ($content as $item) {
					$data = json_decode($item, true);
					$participantsKey = "webinar_participants:" . ($data['id'] ?? '');
					$data['bookedCount'] = $this->redis->llen($participantsKey);

					$date = $data['date'] ?? '';
					$time = $data['time'] ?? '';
					
					$nextMeetingTs = null;
					$nextMeetingStr = null;
					$nextMeetingEndStr = null;
					$durationStr = $data['duration'] ?? '1 hr';

					if (!empty($date) && !empty($time)) {
						// Clean time string if needed
						$timeParts = explode(':', $time);
						if (count($timeParts) == 2) {
							$datePart = explode('T', $date)[0];
							$ts = strtotime("$datePart $time");

							if ($ts !== false) {
								$nextMeetingTs = $ts;
								$nextMeetingStr = date("M d, h:i A", $ts);

								// Calculate End Time
								$minutes = 0;
								if (preg_match('/(\d+)\s*hr/', $durationStr, $matches)) {
									$minutes += intval($matches[1]) * 60;
								}
								if (preg_match('/(\d+)\s*min/', $durationStr, $matches)) {
									$minutes += intval($matches[1]);
								}
								if ($minutes == 0 && is_numeric($durationStr)) {
									$minutes = intval($durationStr);
								}
								if ($minutes == 0) $minutes = 60;

								$endTs = $ts + ($minutes * 60);
								$nextMeetingEndStr = date("h:i A", $endTs);

								if ($endTs <= $now) {
                                    $nextMeetingTs = null;
                                    $nextMeetingStr = null;
                                    $nextMeetingEndStr = null;
                                }
							}
						}
					}

					$data['nextMeeting'] = $nextMeetingStr;
					$data['nextMeetingTs'] = $nextMeetingTs;
					$data['nextMeetingEnd'] = $nextMeetingEndStr;
					$data['nextMeetingDuration'] = $durationStr;

					// Calculate sort timestamp
					$sortTs = 0;
					if (!empty($date) && !empty($time)) {
						$datePart = explode('T', $date)[0];
						$sortTs = strtotime("$datePart $time") ?: 0;
					}
					$data['sortTs'] = $sortTs;

					$webinars[] = $data;
				}

				// Sort webinars by date and time ascending (soonest/past first)
				usort($webinars, function($a, $b) {
					return ($a['sortTs'] ?? 0) <=> ($b['sortTs'] ?? 0);
				});

				return $this->response->setJsonContent([
					"result" => "success",
					"content" => $webinars
				]);
			}
			elseif ($type == 6) { // Get participants list
				$id = $this->request->get("id");
				if (!$id) {
					 return $this->response->setJsonContent(["result" => "error", "message" => "Webinar ID is required."]);
				}
				$key = "webinar_participants:" . $id;
				$content = $this->redis->lrange($key, 0, -1);
				$participants = [];

				// Pre-fetch all rooms to efficiently check status
				$roomsRaw = $this->redis->lrange("rooms", 0, -1);
				$endedRooms = [];
				$missedRooms = [];
				foreach ($roomsRaw as $rItem) {
					$roomData = json_decode($rItem, true);
					if (isset($roomData['room_name']) && isset($roomData['status'])) {
						if ($roomData['status'] === 'ended') {
							$endedRooms[$roomData['room_name']] = true;
						} elseif ($roomData['status'] === 'missed') {
							$missedRooms[$roomData['room_name']] = true;
						}
					}
				}

				foreach ($content as $item) {
					$participant = json_decode($item, true);
					$participantRoomId = $participant['ringqmeetId'] ?? null;
					$participant['isRoomEnded'] = $participantRoomId && isset($endedRooms[$participantRoomId]);
					$participant['isRoomMissed'] = $participantRoomId && isset($missedRooms[$participantRoomId]);
					$participants[] = $participant;
				}
				return $this->response->setJsonContent([
					"result" => "success",
					"content" => $participants
				]);
			}
		}
		if ($this->request->isPost()) { 
			$key = "webinars:" . $session['extension'] . ":" . $session['domain_uuid'];
			$contents = file_get_contents("php://input");
			$data = json_decode($contents, true); 
			if ($type == 1) { // Create
				$invitees = WebinarInvitees::normalise($data['participants'] ?? null, $session['email'] ?? '');
				if ($invitees['error'] !== null) {
					return $this->response->setJsonContent(["result" => "error", "message" => $invitees['error']]);
				}
				unset($data['participants']);

				$ringqmeet = $this->ringqmeet([
					'first_name' => $session['firstname'],
					'last_name' => $session['lastname'],
					'extension_no' => $session['extension'],
					'domain' => $session['subdomain'],
					'meet_type' => 'Webinar'
				]); 

				$ringqmeetId = $ringqmeet['room_name'] ?? '';
				$data['hostName'] = $session['firstname'] . ' ' . $session['lastname'];
				$data['hostEmail'] = $session['email'];
				$data['ringqmeetId'] = $ringqmeetId;
				$data['id'] = uniqid();

				$contents = json_encode($data);
				$this->redis->lpush($key, $contents);
				$this->redis->set("webinar_details:" . $data['id'], $contents);
				$this->redis->sadd("webinar_ids", $data['id']);

				$this->redis->lpush("email_queue", json_encode([
					"type" => "webinar_created",
					"webinarId" => $data['id'],
					"host" => explode(':', $this->request->getHttpHost())[0],
					"data" => []
				]));

				$added = WebinarInvitees::register($this->redis, $data['id'], $data, $session['domain_uuid'], $session['subdomain'], $invitees['rows']);

				return $this->response->setJsonContent([ 
					"result" => "success", 
					"message" => "Successfully created webinar.",        
					"added" => count($added),
				]); 
			} 
			elseif ($type == 2) { // Update 
				if (!isset($data['id'])) { 
					return $this->response->setJsonContent(["result" => "error", "message" => "Webinar ID is required."]); 
				}  
				$list = $this->redis->lrange($key, 0, -1); 
				foreach ($list as $index => $item) {
					$webinar = json_decode($item, true);
					if ($webinar['id'] == $data['id']) { 
						$invitees = WebinarInvitees::normalise(
							$data['participants'] ?? null,
							$session['email'] ?? '',
							WebinarInvitees::existingEmails($this->redis, $data['id'])
						);
						if ($invitees['error'] !== null) {
							return $this->response->setJsonContent(["result" => "error", "message" => $invitees['error']]);
						}
						unset($data['participants']);

						$owner = $this->webinarOwnerFields($webinar, $session, $data['id']);
						if ($owner['ringqmeetId'] === null) {
							$mintedRoom = $this->ringqmeet([
								'first_name' => $session['firstname'],
								'last_name' => $session['lastname'],
								'extension_no' => $session['extension'],
								'domain' => $session['subdomain'],
								'meet_type' => 'Webinar'
							]);
							$owner['ringqmeetId'] = $mintedRoom['room_name'] ?? '';
						}
						$data['hostName'] = $owner['hostName'];
						$data['hostEmail'] = $owner['hostEmail'];
						$data['ringqmeetId'] = $owner['ringqmeetId'];

						$this->redis->lset($key, $index, json_encode($data)); 
						$this->redis->set("webinar_details:" . $data['id'], json_encode($data));
						$this->redis->sadd("webinar_ids", $data['id']);
						WebinarInvitees::refreshInvites($this->redis, $data['id'], $data);
						$added = WebinarInvitees::register($this->redis, $data['id'], $data, $session['domain_uuid'], $session['subdomain'], $invitees['rows']);
						return $this->response->setJsonContent([ 
							"result" => "success", 
							"message" => "Successfully updated webinar.", 
							"added" => count($added),
							"skipped" => $invitees['skipped'],
						]);
					} 
				} 
				return $this->response->setJsonContent(["result" => "error", "message" => "Webinar not found."]); 
			} 
			elseif ($type == 3) { // Delete 
				if (!isset($data['id'])) {
					return $this->response->setJsonContent(["result" => "error", "message" => "Webinar ID is required."]); 
				} 
				$list = $this->redis->lrange($key, 0, -1); 
				foreach ($list as $item) { 
					$webinar = json_decode($item, true); 
					if ($webinar['id'] == $data['id']) {  
						$this->redis->lrem($key, 0, $item);
						$this->redis->del("webinar_details:" . $data['id']);
						WebinarInvitees::revokeWebinar($this->redis, $data['id']);
						$this->redis->del("webinar_participants:" . $data['id']);
						$this->redis->srem("webinar_ids", $data['id']);
						return $this->response->setJsonContent([ 
							"result" => "success",
							"message" => "Successfully deleted webinar." ,
						]);  
					} 
				} 
				return $this->response->setJsonContent(["result" => "error", "message" => "Webinar not found."]); 
			} 
			elseif ($type == 7) { // Delete Participant
				if (!isset($data['id']) || !isset($data['webinarId'])) {
					return $this->response->setJsonContent([
						"result" => "error", 
						"message" => "Participant ID and Webinar ID are required."
					]); 
				} 
				$key = "webinar_participants:" . $data['webinarId'];
				$list = $this->redis->lrange($key, 0, -1); 
				foreach ($list as $item) { 
					$participant = json_decode($item, true); 
					if (($participant['id'] ?? '') == $data['id']) {
						$this->redis->lrem($key, 0, $item);
						WebinarInvitees::revokeParticipant($this->redis, $data['webinarId'], $data['id']);
						return $this->response->setJsonContent([ 
							"result" => "success",
							"message" => "Successfully removed participant." ,
						]);
					} 
				} 
				return $this->response->setJsonContent([
					"result" => "error", 
					"message" => "Participant not found."
				]); 
			} 
			elseif ($type == 8) { // Mark Room Missed
				if (!isset($data['ringqmeetId'])) {
					return $this->response->setJsonContent([
						"result" => "error", 
						"message" => "ringqmeetId is required."
					]); 
				} 

				$targetRoomId = $data['ringqmeetId'];

				if ($targetRoomId) {
					$roomsRaw = $this->redis->lrange('rooms', 0, -1);
					foreach ($roomsRaw as $roomKey => $roomItem) {
						$roomData = json_decode($roomItem, true);
						if (($roomData['room_name'] ?? '') == $targetRoomId) {
							$this->redis->lrem('rooms', 0, $roomItem);
							$roomData['time_ended'] = date('g:i A');
							$roomData['status'] = 'missed';
							$this->redis->rpush('rooms', json_encode($roomData)); 

							return $this->response->setJsonContent([ 
								"result" => "success",
								"message" => "Room successfully marked as missed."
							]);
						}
					}
					
					return $this->response->setJsonContent([ 
						"result" => "success",
						"message" => "No active room found to end."
					]);
				}

				return $this->response->setJsonContent([
					"result" => "error", 
					"message" => "Missing room ID."
				]); 
			}
		}
	}

	private function webinarOwnerFields($stored, $session, $webinarId)
	{
		$hostName = '';
		if (is_array($stored) && isset($stored['hostName'])) {
			$hostName = trim((string)$stored['hostName']);
		}
		if ($hostName === '') {
			$hostName = trim((string)($session['firstname'] ?? '') . ' ' . (string)($session['lastname'] ?? ''));
		}

		$hostEmail = '';
		if (is_array($stored) && isset($stored['hostEmail'])) {
			$hostEmail = trim((string)$stored['hostEmail']);
		}
		if ($hostEmail === '') {
			$hostEmail = trim((string)($session['email'] ?? ''));
		}

		$ringqmeetId = '';
		if (is_array($stored) && isset($stored['ringqmeetId'])) {
			$ringqmeetId = trim((string)$stored['ringqmeetId']);
		}
		if ($ringqmeetId === '') {
			$ringqmeetId = $this->webinarReferenceFromRegistrations($webinarId);
		}

		return [
			'hostName'    => $hostName,
			'hostEmail'   => $hostEmail,
			'ringqmeetId' => $ringqmeetId === '' ? null : $ringqmeetId,
		];
	}

	/**
	 * The meeting reference a registration already recorded, or '' when none has.
	 *
	 * Every registration stores `meetLink` as `/meet/m/<ringqmeetId>`, so a
	 * webinar whose own record was wiped can still say which room its
	 * registrants were sent to. Reading it back is what makes the repair
	 * non-destructive for a webinar that already has people in it.
	 */
	private function webinarReferenceFromRegistrations($webinarId)
	{
		$rows = $this->redis->lrange("webinar_participants:" . $webinarId, 0, -1);
		if (!is_array($rows)) return '';
		foreach ($rows as $row) {
			$registration = json_decode($row, true);
			if (!is_array($registration)) continue;
			$link = trim((string)($registration['meetLink'] ?? ''));
			if ($link === '') continue;
			$path = (string)parse_url($link, PHP_URL_PATH);
			if (preg_match('~/meet/m/([^/]+)$~', $path, $matches)) {
				$reference = rawurldecode($matches[1]);
				if ($reference !== '') return $reference;
			}
		}
		return '';
	}


	public function ringqmeet($data = []) {
		$security = new \Phalcon\Security\Random();
        $roomId = $security->uuid();
		$owner = "{$data['first_name']}{$data['last_name']}{$data['extension_no']}";

		// Scheduled and booking UUIDs are external references. They are mapped
		// idempotently by /meet/api/v1 on first host use and never enter the
		// unscoped legacy `rooms` list.
		return [
			'owner' => $owner,
			'room_name' => $roomId
		];
	}

