	public function linkedinAction($type = 1) {
		$this->view->setRenderLevel(View::LEVEL_NO_RENDER);
		
		$session = $this->session->get("auth");
		if (!$session) {
			return $this->response->setJsonContent([
				"result" => "error",
				"message" => "Unauthorized"
			]);
		}

		if ($type == 3 && $this->request->isPost()) {
			$key = 'linkedin-profile:' . $session['extension'] . ":" . $session['domain_uuid'];
			$this->redis->del($key);
			return $this->response->setJsonContent([
				"result" => "success",
				"message" => "Disconnected successfully"
			]);
		}

		if ($this->request->isGet()) {
			$profileKey = 'linkedin-profile:' . $session['extension'] . ":" . $session['domain_uuid'];
			$profile = $this->redis->hgetall($profileKey);
			
			$credsKey = 'linkedin-creds:' . $session['domain_uuid'];
			$creds = $this->redis->get($credsKey);

			if ($type == 1) {
				return $this->response->setJsonContent([
					"result" => "success", 
					"connected" => ($profile && !empty($profile)),
					"content" => $profile ?: null,
					"creds" => $creds ? json_decode($creds, true) : null
				]);
			}
		}

		if ($this->request->isPost()) {
			$data = json_decode(file_get_contents("php://input"), true);
			$clientId = $data['clientId'] ?? '';
			$clientSecret = $data['clientSecret'] ?? '';
			$redirectUri = $data['redirectUri'] ?? '';

			if (empty($clientId) || empty($clientSecret) || empty($redirectUri)) {
				return $this->response->setJsonContent([
					"result" => "error",
					"message" => "Missing credentials"
				]);
			}

			// Store credentials permanently
			$key = "linkedin-creds:" . $session['domain_uuid'];
			$this->redis->set($key, json_encode([
				'client_id' => $clientId,
				'client_secret' => $clientSecret,
				'redirect_uri' => $redirectUri
			]));

			return $this->response->setJsonContent([
				"result"  => "success",
				"message" => "Credentials saved", 
			]);
		}
	}

	public function connectAction() {
		$this->view->setRenderLevel(View::LEVEL_NO_RENDER);
		$session = $this->session->get("auth");
		
		if (!$session) {
			return $this->response->setJsonContent([
				"result" => "error",
				"message" => "Unauthorized"
			]);
		}

		$code = $this->request->get("code");
		$error = $this->request->get("error");

		if ($error) {
			return $this->response->setJsonContent([
				"result" => "error",
				"message" => "LinkedIn Authorization Error: " . htmlspecialchars($error)
			]);
		}

		if ($code) {
			$key = "linkedin-creds:" . $session['domain_uuid'];
			$credsJson = $this->redis->get($key);

			if (!$credsJson) { 
				return $this->response->setJsonContent([
					"result" => "error",
					"message" => "Credentials not found. Please try again."
				]);
			}

			$creds = json_decode($credsJson, true);
			$clientId = $creds['client_id'];
			$clientSecret = $creds['client_secret'];
			$redirectUri = $creds['redirect_uri'];

			// Exchange code for token
			$tokenUrl = "https://www.linkedin.com/oauth/v2/accessToken";
			$params = [
				'grant_type' => 'authorization_code',
				'code' => $code,
				'redirect_uri' => $redirectUri,
				'client_id' => $clientId,
				'client_secret' => $clientSecret,
			];

			$ch = curl_init();
			curl_setopt($ch, CURLOPT_URL, $tokenUrl);
			curl_setopt($ch, CURLOPT_POST, 1);
			curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query($params));
			curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
			curl_setopt($ch, CURLOPT_HTTPHEADER, ['Content-Type: application/x-www-form-urlencoded']);
			$response = curl_exec($ch);
			curl_close($ch);

			$tokenData = json_decode($response, true);
			$accessToken = $tokenData['access_token'] ?? null;

			if ($accessToken) {
				// Fetch Profile using OpenID Connect userinfo endpoint
				$ch = curl_init();
				curl_setopt($ch, CURLOPT_URL, "https://api.linkedin.com/v2/userinfo");
				curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
				curl_setopt($ch, CURLOPT_HTTPHEADER, [
					"Authorization: Bearer $accessToken",
				]);
				$profileResponse = curl_exec($ch);
				curl_close($ch);
				$profileData = json_decode($profileResponse, true); 
				$profileData['locale_country']  = $profileData['locale']['country'] ?? null;
				$profileData['locale_language'] = $profileData['locale']['language'] ?? null;
				unset($profileData['locale']);
				$this->redis->hmset('linkedin-profile:'.$session['extension'] .":". $session['domain_uuid'], $profileData);

				$this->response->setContent("<html><body><script>window.close();</script><div style='display:flex;justify-content:center;align-items:center;height:100vh;font-family:sans-serif;'><div><h2>Connection Successful</h2><p>You can close this tab now.</p></div></div></body></html>");
				return $this->response;
			}
		}
	}

    public function ssoAction()
    {
	    $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
	    $this->response->setHeader("Content-Type", "application/json");
	    $session = $this->session->get("auth");
	    if ($session) {
	       if ($this->request->isPost()) {
	          $parameters = [];
	          $parameters["type"] = intval($this->request->getPost("type", "int"));
	          $parameters["ssoQR"] = intval($this->request->getPost("ssoQR", "int"));
	          $parameters["ssoNumber"] = intval($this->request->getPost("ssoNumber", "int"));
	          $parameters["webPassword"] = intval($this->request->getPost("webPassword", "int"));
	          if (empty($parameters["type"])) {
	             $contents = file_get_contents("php://input");
	             $parameters = json_decode($contents, true);
	          }
	          if ($parameters["type"] == 1) {
				$this->redis->set("security:" . $session["subdomain"] . "-ssoQR", $parameters["ssoQR"]);
				$this->redis->set("security:" . $session["subdomain"] . "-ssoNumber", $parameters["ssoNumber"]);
				$this->redis->set("security:" . $session["subdomain"] . "-webPassword", $parameters["webPassword"]);
				$serverIp = $this->request->getServerAddress();
				$this->redis->set("security:" . $serverIp . "-webPassword", $parameters["webPassword"]);
				$qCallBehaviors = QCallBehaviors::find([
		            "conditions" => "domain_uuid = :domain_uuid:",
		            "bind" => [	
		               "domain_uuid" => $session["domain_uuid"],
		            ],
		            "bindTypes" => [Column::BIND_PARAM_STR],
		        ]);
				foreach($qCallBehaviors as $qCallBehavior) {
					$qCallBehavior->sso_qr = intval($parameters["ssoQR"]) == 1 ? 1 : 2;
					$qCallBehavior->sso_number = intval($parameters["ssoNumber"]) == 1 ? 1 : 2;
					$qCallBehavior->update();
				} 
				$response = json_encode([
					"result" => "success",
					"message" => "Successfully updated integration settings.",
				]);
				$this->response->setContent($response);
				return $this->response;
	          }
	       }
	    }
    }

     public function backupAction($type = 6, $page = 1)
    {
		$this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json"); 

        $session = $this->session->get("auth");
        if (!$session) {
			return $this->response->setJsonContent([
				"result" => "error",
				"message" => "Unathorized request. (Code AL1000)",
			]);
		}
		$qCompany = QCompanies::findFirst([
			"conditions" => "domain_uuid = :domain_uuid:",
			"bind" => [
				"domain_uuid" => $session["domain_uuid"],
			],
			"bindTypes" => [Column::BIND_PARAM_STR],
		]);
		if (!$qCompany) { 
			return $this->response->setJsonContent([
				"result" => "error",
				"message" => "Unathorized request. (Code AL1000)",
			]);
		}
		$ringqConfig = json_decode($this->redis->get('ringq_config'), true);
		$uuid = $ringqConfig['data']['uuid'];
		$accessToken = $ringqConfig['data']['access_token'];
		$licenseKey = $ringqConfig['data']['licenseKey'];
		$userId = $ringqConfig['data']['user_id'];

		// Import extensions
		if ($type == 15) {
			if ($this->request->hasFiles() == true) {
				$file = $this->request->getUploadedFiles()[0];
				if ($file->getError() != 0) {
					$response = json_encode([
						"result" => "error",
						"message" => "File upload failed with error code: " . $file->getError() . ". Please check your server configuration (upload_max_filesize, post_max_size)."
					]);
					$this->response->setContent($response);
					return $this->response;
				}
				$validationErrors = [];
				// Manual Validation
				$maxSize = 10 * 1024 * 1024; // 10MB
				if ($file->getSize() > $maxSize) {
					$validationErrors[] = "Backup file exceeds the maximum file size (100MB).";
				}
				$fileName = $file->getName();
				$ext = pathinfo($fileName, PATHINFO_EXTENSION);
				if (strtolower($ext) !== 'csv') {
					$validationErrors[] = "Allowed file types are .csv.";
				}
				$fileName = $file->getName();
				$tempPath = $file->getTempName();
				$ext = pathinfo($fileName, PATHINFO_EXTENSION);
				$finfo = new finfo(FILEINFO_MIME_TYPE);
				$mimeType = $finfo->file($tempPath);
				$allowedMimeTypes = ['text/csv', 'text/plain', 'application/vnd.ms-excel'];
				if (strtolower($ext) !== 'csv' || !in_array($mimeType, $allowedMimeTypes)) {
					$validationErrors[] = "Invalid file: Only CSV files are allowed.";
				}
				if (empty($validationErrors)) {
					$security = new \Phalcon\Security\Random();
					$fileNameUuid = $security->uuid();
					$targetDir = "/var/www/ringq/app/migrations";
					$targetPath = $targetDir . "/" . $fileNameUuid .".csv";
					$contacts = [];
					if ($file->moveTo($targetPath)) { 
						if (file_exists($targetPath)) {
							if (($handle = fopen($targetPath, 'r')) !== false) {
								$headers = fgetcsv($handle); // Read header row
								$lastCompany = '';
								while (($data = fgetcsv($handle)) !== false) {
									// Combine header and row data
									$row = array_combine($headers, $data);
									$contacts[] = $row;
								}
								fclose($handle);
							}
							unlink($targetPath);
						}
						$this->db->begin();
						$counter2 = 0;
						foreach($contacts as $contact) {
							$parameters = array();
							// Extension	Email Address	Firtst Name	Last Name	Mobile Number (optional) SIP UID
							$parameters["email"] = $this->filter->sanitize($contact["email_address"], "string") ?? null; 
							$parameters["extension"] =  intval($contact["extension"]) ?? null; 
							$parameters["firstname"] = $this->filter->sanitize($contact["first_name"], "string") ?? null; 
							$parameters["lastname"] = $this->filter->sanitize($contact["last_name"], "string") ?? null; 
							$parameters["mobile_number"] = $this->filter->sanitize($contact["mobile_number"], "string")  ?? null; 
							$parameters["extensionSip"] = intval($contact["sip_uid"]) ?? null;
							$parameters["auth_id"] = $this->filter->sanitize($contact["auth_id"] ?? "", "string");
							$parameters["auth_password"] = $this->filter->sanitize($contact["auth_password"] ?? "", "string");
							$parameters["email"] = strtolower($parameters["email"]);
							$extensionForm = new ExtensionForm();
							// Same 2-character name rule as a single save; ExtensionForm (3+) gets stand-ins.
							$extensionFormParameters = $parameters;
							if ($this->nameFitsExtensionForm($parameters["firstname"] ?? "") && $this->nameFitsExtensionForm($parameters["lastname"] ?? "")) {
								$extensionFormParameters["firstname"] = "Name";
								$extensionFormParameters["lastname"] = "Name";
							}
							if (!$extensionForm->isValid($extensionFormParameters)) {
							  $this->db->rollback();
						      $messages = $extensionForm->getMessages();
						      $message = "";
						      foreach ($messages as $error) {
						         $message .= $error . " ";
						      }
						      $response = json_encode([
						         "result" => "error",
						         "message" => trim($message) . " (Code AE1000)",
						      ]);
						      $this->response->setContent($response);
						      return $this->response;
						    }
						    if ($parameters["extension"] == 0) {
								$nextExtension = VExtensions::findFirst(
								    [
								        "conditions" => "domain_uuid = :domain_uuid: AND extension < :extension: AND LENGTH(extension) < :max_len:",
								        "bind"       => [
								            "domain_uuid" => $session["domain_uuid"],
								            "extension"  => 9000,
								            "max_len" => 5 
								        ],
								        "order" => "extension DESC"
								    ]
								);
								if ($nextExtension) {
									$parameters["extension"] = $nextExtension->extension + 1 + $counter2;
								}
						    }
						    if ($parameters["extension"] >= 9000 && $parameters["extension"] <= 9500) {
								$this->db->rollback();
								$response = json_encode([
									"result" => "error",
									"message" => "Sorry, exntesion must not be between 9000 - 9500",
								]);
								$this->response->setContent($response);
								return $this->response;
						    }
						    if ($parameters["extension"] >= 3000 && $parameters["extension"] <= 3100) {
								$this->db->rollback();
								$response = json_encode([
									"result" => "error",
									"message" => "Sorry, exntesion must not be between 3000 - 3100",
								]);
								$this->response->setContent($response);
								return $this->response;
						    }
						    if ($parameters["extension"] >= 5555 && $parameters["extension"] <= 5600) {
								$this->db->rollback();
								$response = json_encode([
									"result" => "error",
									"message" => "Sorry, exntesion must not be between 5555 - 5600",
								]);
								$this->response->setContent($response);
								return $this->response;
						    }
						    if ($parameters["extension"] >= 7777 && $parameters["extension"] <= 7780) {
								$this->db->rollback();
								$response = json_encode([
									"result" => "error",
									"message" => "Sorry, exntesion must not be between 7777 - 7780",
								]);
								$this->response->setContent($response);
								return $this->response;
						    }
						    if ($parameters["extension"] >= 6000 && $parameters["extension"] <= 6500) {
								$this->db->rollback();
								$response = json_encode([
									"result" => "error",
									"message" => "Sorry, exntesion must not be between 6000 - 6500",
								]);
								$this->response->setContent($response);
								return $this->response;
						    }
						    // if ($parameters["extension"] >= 2000 && $parameters["extension"] <= 2500) {
							// 	$this->db->rollback();
							// 	$response = json_encode([
							// 		"result" => "error",
							// 		"message" => "Sorry, exntesion must not be between 2000 - 2500",
							// 	]);
							// 	$this->response->setContent($response);
							// 	return $this->response;
						    // }
						    if ($parameters["extension"] >= 4000 && $parameters["extension"] <= 4020) {
								$this->db->rollback();
								$response = json_encode([
									"result" => "error",
									"message" => "Sorry, exntesion must not be between 4000 - 4020",
								]);
								$this->response->setContent($response);
								return $this->response;
						    }
							$findExistingEmail = VUsers::findFirst([
								'conditions' => "domain_uuid = :domain_uuid: AND user_email = :user_email:",
								'bind' => [
									'domain_uuid' => $session["domain_uuid"],
									'user_email' => $parameters["email"]
								],
								"bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
							]);
							if ($findExistingEmail) {
								$this->db->rollback();
								$response = json_encode([
									"result" => "error",
									"message" => "The provided email address is already registered. Please use a different one.",
								]);
								$this->response->setContent($response);
								return $this->response;
							}
							$counter2++;
							$extensionLimits = $this->redis->get($session["domain_uuid"]. "-ext");
							if ($extensionLimits && !empty($parameters["extension"])) {
								$vExtensions = VExtensions::find([
									"conditions" => "domain_uuid = :domain_uuid:",
									"bind" => [
										"domain_uuid" => $session["domain_uuid"],
									],
									"bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_INT],
								]);
								$extensionCount = 0;
								foreach ($vExtensions as $vExtension) {
									if (is_numeric($vExtension->extension)) {
										$extensionCount++;
									}
								}
								$extensionLimits = intval($extensionLimits) - $counter2;
								$extensionCount = $extensionCount - 3;
								if ($extensionLimits < $extensionCount) {
									$this->db->rollback();
									$response = json_encode([
										"result" => "error",
										"message" => "Sorry, extension limit reached. Please upgrade package to create new extensions. (Code AE1003)",
									]);
									$this->response->setContent($response);
									return $this->response;
								}
								$sipIpChecker = QCallBehaviors::findFirst(
									[
										"conditions" => "domain_uuid = :domain_uuid: AND force_ping = :force_ping:",
										"bind" =>
											[
												"domain_uuid" => $session["domain_uuid"],
												"force_ping" => $parameters["extension"],
											],
										"bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
									]
								);
								if ($sipIpChecker) {
									$this->db->rollback();
									$response = json_encode([
										"result" => "error",
										"message" => "Sorry, SIP ID already exists. (Code AE1003)",
									]);
									$this->response->setContent($response);
									return $this->response;
								}
								 if ($parameters["extensionSip"] != 0) {
								     if (!$this->sipIdChecker($session["domain_uuid"], $parameters["extension"], $parameters["extensionSip"])) {
								        $response = json_encode([
								           "result" => "error",
								           "message" => "Sorry, SIP ID already exists. (Code AE1003)",
								        ]);
								        $this->response->setContent($response);
								        return $this->response;
								     }
								 }
								if (strlen(strval($parameters["extension"])) < 4 || strlen(strval($parameters["extension"])) > 4) {
									$this->db->rollback();
									$response = json_encode([
										"result" => "error",
										"message" => "Sorry, extension must be only 4 digits.",
									]);
									$this->response->setContent($response);
									return $this->response;
								}
							}
							$qCompany = QCompanies::findFirst(
								[
									"conditions" => "domain_uuid = :domain_uuid:",
									"bind" => [
									"domain_uuid" => $session["domain_uuid"],
									],
									"bindTypes" => [Column::BIND_PARAM_STR],
								]
							);
							$vExtension = VExtensions::findFirst(
								[
									"conditions" => "domain_uuid = :domain_uuid: AND extension =:extension:",
									"bind" => [
										"domain_uuid" => $session["domain_uuid"],
										"extension" => intval($parameters["extension"]),
									],
									"bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_INT],
								]
							);
							if ($vExtension) {
								$this->db->rollback();
								$response = json_encode([
									"result" => "error",
									"message" => "Sorry, extension already exists. (Code AE1003)",
								]);
								$this->response->setContent($response);
								return $this->response;
							}
							// SIP username (auth_id) maps to number_alias, which must be unique within the domain.
							if (!empty($parameters["auth_id"])) {
								$vAliasExists = VExtensions::findFirst([
									"conditions" => "domain_uuid = :domain_uuid: AND number_alias = :number_alias:",
									"bind" => [
										"domain_uuid" => $session["domain_uuid"],
										"number_alias" => $parameters["auth_id"],
									],
									"bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
								]);
								if ($vAliasExists) {
									$this->db->rollback();
									$response = json_encode([
										"result" => "error",
										"message" => "Sorry, SIP username (auth_id) already exists. (Code AE1003)",
									]);
									$this->response->setContent($response);
									return $this->response;
								}
							}
							$security = new \Phalcon\Security\Random();
							$vDomains = VDomains::findFirst([
								"conditions" => "domain_uuid = :domain_uuid:",
								"bind" => [
									"domain_uuid" => $session["domain_uuid"],
								],
							]);
							$user_uuid = $security->uuid();
							$domain_uuid = $session["domain_uuid"];
							$company_email = $parameters["email"];
							$voicemail_uuid = $security->uuid();
							$company = strtolower(str_replace(" ", "", preg_replace("/[^a-zA-Z0-9_ -]/s", " ", $qCompany->company_name)));
							$fqdn = $vDomains->domain_name;
							$extension = intval($parameters["extension"]);
							$lastname = PersonName::capitalize($parameters["lastname"]);
							$firstname = PersonName::capitalize($parameters["firstname"]);
							$username = $security->hex(10);
							$salt = $this->security->hash($security->base64(16));
							$password = $this->security->hash($security->base64(16));
							$password2 = $security->base64(16);
							$extension_password = $password2; // md5($salt . $password2);
							// SIP credentials supplied via CSV (auth_id = SIP username, auth_password = SIP password).
							// Use-if-present, otherwise keep the auto-generated values above.
							if (!empty($parameters["auth_id"])) {
								$username = $parameters["auth_id"];
							}
							if (!empty($parameters["auth_password"])) {
								$extension_password = $parameters["auth_password"];
							}
							$parameters["username"] = $username; // consumed by the phone provisioning branch below
							$qUser = new QUsers();
							$qUser->user_uuid = $user_uuid;
							$qUser->domain_uuid = $domain_uuid;
							$qUser->first_name = $firstname;
							$qUser->last_name = $lastname;
							$qUser->extension_enabled = true;
							$qUser->insert_date = date("Y-m-d H:i:s");
							$qUser->user_email = $company_email;
							$qUser->password = password_hash($password2, PASSWORD_DEFAULT);
							if (!$qUser->save()) {
								$this->db->rollback();
								$response = json_encode([
									"result" => "error",
									"message" => "An error has occurred. (Code AE1001)",
								]);
								$this->response->setContent($response);
								return $this->response;
							}
							$vUser = new VUsers();
							$vUser->username = $username;
							$vUser->user_uuid = $user_uuid;
							$vUser->domain_uuid = $domain_uuid;
							$vUser->user_email = $company_email;
							$vUser->password = $password;
							// $vUser->salt = $salt;
							$vUser->user_status = "Logged Out";
							$vUser->user_enabled = "true";
							$vUser->api_key = $security->base64(32);
							$vUser->image = null;
							$vUser->first_name = $firstname;
							$vUser->last_name = $lastname;
							$vUser->insert_user = $user_uuid;
							$vUser->add_user = !empty($parameters["mac_address"]) ? trim(strtolower($parameters["mac_address"])) : null;
							$prevRouterTunnels = $this->savedRouterTunnels($parameters["extension"] ."@". $session["subdomain"]. "-macAddresses");
							$this->srapsSyncLater($parameters["extension"] ."@". $session["subdomain"]. "-macAddresses", $session, $parameters ?? null); // [sraps]
							$this->redis->del($parameters["extension"] ."@". $session["subdomain"]. "-macAddresses");
							if (!empty($parameters["mac_address"])) {
								$macBrands = explode(",", $parameters["mac_brand"]);
								$macModels = explode(",", $parameters["mac_model"]);
								$macStuns = explode(",", $parameters["mac_stun"]);
								$macTimezones = explode(",", $parameters["mac_timezone"]);
								$macAddresses = explode(",", $parameters["mac_address"]);
								$macTemplateIds  = isset($parameters["mac_template_id"]) ? explode(",", $parameters["mac_template_id"]) : [];
								$macHostUrls     = isset($parameters["mac_host_url"]) ? explode(",", $parameters["mac_host_url"]) : [];
								$macRouterTunnels = (isset($parameters["mac_router_tunnel"]) && $parameters["mac_router_tunnel"] !== null) ? explode(",", (string) $parameters["mac_router_tunnel"]) : null;
								for($x = 0; $x < count($macAddresses); $x++) {
									try {
										$macHostUrl = $this->resolveProvisionHostUrl($macHostUrls[$x] ?? "", $session["subdomain"]);
										$routerTunnelId = $this->resolveRouterTunnel($macRouterTunnels, $x, $macAddresses[$x], $prevRouterTunnels);
										$this->redis->lpush($parameters["extension"] ."@". $session["subdomain"]. "-macAddresses", $macBrands[$x] ."@". $macModels[$x] ."@". $macAddresses[$x] . "@". $macStuns[$x] ."@". $macTimezones[$x] . "@". $macHostUrl . "@". $routerTunnelId);
										$hashKey = 'provision:'. str_replace(' ', '',$macBrands[$x]) .':'. str_replace(' ', '',$macModels[$x]);
										$data = $this->redis->hGetAll($hashKey);
										$contentTemplate = $this->redis->hGet($hashKey, "value");
										$phoneBrand = $this->redis->hGet($hashKey, "phoneBrand");
										$cleanMac = strtolower(str_replace([':', '-'], '', $macAddresses[$x]));
										$subdomain  = $session["subdomain"];
										$registrarHost = ($macHostUrl ?? "") !== "" ? $macHostUrl : $subdomain;
										$provisionBase = $this->provisionBaseUrl($macHostUrl ?? "", $subdomain);
										if ($macBrands[$x] == 'yealink') {
											$cfgUpdates = [
												"account.1.enable"                  => "1",
												"account.1.label"                   => $parameters["extension"] . " | " . ($parameters["firstname"] . ' ' . $parameters["lastname"]),
												"account.1.display_name"            => $parameters["firstname"] . ' ' . $parameters["lastname"],
												"account.1.user_name"               => $parameters["username"],
												"account.1.auth_name"               => $parameters["username"],
												"account.1.password"                => $vExtension->password,
												"account.1.stun_server"             => $macStuns[$x],
												"network.stun_server"               => $macStuns[$x],
												"static.sip.nat_stun.server"        => $macStuns[$x],
												"account.1.sip_server.1.address"    => $registrarHost,
												"account.1.sip_server_host.legacy"  => $registrarHost,
												"account.1.voice_mail.number"       => "*99",
												"local_time.time_zone"              => $macTimezones[$x],
												"local_time.time_zone_name"         => $macTimezones[$x],
												"static.auto_provision.server_url"  => "{$provisionBase}/{$cleanMac}.cfg",
											];

											foreach ($cfgUpdates as $key => $value) {
												$pattern = '/^(' . preg_quote($key, '/') . ')\s*=.*$/m';
												if (preg_match($pattern, $contentTemplate)) {
													$contentTemplate = preg_replace($pattern, "$1=$value", $contentTemplate);
												} else {
													$contentTemplate .= "\n{$key}={$value}";
												}
											}

											$provisionKey = "provision:yealink:{$cleanMac}:cfg:" . $parameters["username"];
											$this->redis->set($provisionKey, $contentTemplate);
										}
										elseif ($macBrands[$x] == 'fanvil') {
											libxml_use_internal_errors(true);
											$xmlObject = simplexml_load_string($contentTemplate);
											if ($xmlObject === false) {
												return $this->response->setJsonContent([
													"result" => "error",
													"message" => "Invalid XML format in textConfig",
													"debug" => libxml_get_errors()
												]);
											}

											$xmlUpdates = [
												'TimeZone'        => $macTimezones[$x],
												'TimeZoneName'    => 'UTC'. $this->timeZoneName($phoneBrand, $macTimezones[$x]),
												'STUNServerAddr'  => $macStuns[$x],
												'STUNServer'      => $macStuns[$x],
												'PhoneNumber'     => $parameters["username"],
