		                            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
		                            "order" => "dialplan_order ASC"
		                        ]
		                    );
		                    foreach ($vDialplans as $vDialplan) {
		                            $xml .= "\n". $vDialplan->dialplan_xml;
		                    }
		                    $vDialplan2 = VDialplans::findFirst(
		                        [
		                            "conditions" => "domain_uuid = :domain_uuid: AND dialplan_name = :dialplan_name:",
		                            "bind" =>
		                                [
		                                    "domain_uuid" => $session["domain_uuid"],
		                                    "dialplan_name" => "outbound-rules"
		                                ],
		                            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
		                        ]
		                    );
		                    if ($vDialplan2) {
		                        $vDialplan2->dialplan_enabled = "true";
		                        $vDialplan2->dialplan_xml = $xml;
		                        if (!$vDialplan2->update()) {
		                            $this->db->rollback();
		                            $messages = $vDialplan2->getMessages();
		                            $message = "";
		                            foreach ($messages as $error) {
		                                $message .= $error . " ";
		                            }
		                            $response = json_encode(
		                                [
		                                    "result" => "error",
		                                    "message" => trim($message) . " (Code AS1005)",
		                                    "content" => [],
		                                ]
		                            );
		                            $this->response->setContent($response);
		                            return $this->response;
		                        }
		                    } else {
		                        $outbound_uuid2 = $security->uuid();
		                        $vDialplan0 = new VDialplans();
		                        $vDialplan0->domain_uuid = $session["domain_uuid"];
		                        $vDialplan0->dialplan_uuid = $outbound_uuid2;
		                        $vDialplan0->app_uuid = $security->uuid();
		                        $vDialplan0->hostname = null;
		                        $vDialplan0->dialplan_xml = $xml;
		                        $vDialplan0->dialplan_name = "outbound-rules";
		                        $vDialplan0->dialplan_order = intval($parameters["emergency"]) == 1 ? 81 : 85;
		                        $vDialplan0->dialplan_context = $session["subdomain"];
		                        $vDialplan0->dialplan_continue = "false";
		                        $vDialplan0->dialplan_enabled = "true";
		                        if (!$vDialplan0->create()) {
		                            $this->db->rollback();
		                            $messages = $vDialplan0->getMessages();
		                            $message = "";
		                            foreach ($messages as $error) {
		                                $message .= $error . " ";
		                            }
		                            $response = json_encode(
		                                [
		                                    "result" => "error",
		                                    "message" => trim($message) . " (Code AS1002)",
		                                    "content" => [],
		                                ]
		                            );
		                            $this->response->setContent($response);
		                            return $this->response;
		                        }
		                    }
						}
						if (file_exists("/var/cache/fusionpbx/dialplan.". $session["subdomain"])) {
							unlink("/var/cache/fusionpbx/dialplan.". $session["subdomain"]);
						}
						if (file_exists("/var/cache/fusionpbx/configuration.sofia.conf.". gethostname())) {
							unlink("/var/cache/fusionpbx/configuration.sofia.conf.". gethostname());
						}
						if (file_exists("/var/cache/ringq/dialplan.". $session["subdomain"])) {
							unlink("/var/cache/ringq/dialplan.". $session["subdomain"]);
						}
						if (file_exists("/var/cache/ringq/configuration.sofia.conf.". gethostname())) {
							unlink("/var/cache/ringq/configuration.sofia.conf.". gethostname());
						}
		                $this->redis->set($session["subdomain"] . ":outboundParallel", "1");
						$this->db->commit();
						$client = new Client(Client::engine(Client::CLIENT_4X, "ws://127.0.0.1:3000", [
							"persistent" => false,
						]));
						$client->initialize();
						$client->emit("gatewaystart", ["uuid" => ""]);
						$response = json_encode(
							[
								"result" => "success",
								"message" => "Successfully, added new gateway. (Code AG1004)",
								"content" => [],
							]
						);
						$this->response->setContent($response);
						return $this->response;
					}
				} else {
					$response = json_encode([
						"result" => "error",
						"message" => implode(" ", $validationErrors)
					]);
					$this->response->setContent($response);
					return $this->response;
				}
			}
		}
    }

    // ───────────────────────────────────────────────────────────────
    // Support ticket with attachments (web client "Need support?" chat).
    //
    // POST accounts/support as multipart/form-data with no "type" field:
    //   category      voice | crash | server | other
    //   issue         e.g. "Choppy voice." (the help desk's encounter field)
    //   reportedAt    ISO 8601 date and time
    //   description   may be empty
    //   contactName, contactEmail, instance, partnerEmail
    //   mainIssueId, mainIssue   optional; the id/name from accounts/support/5
    //   file[]        0-5 files: PNG, JPEG, PDF, DOC/DOCX, XLS/XLSX, 15 MB each
    //
    // Files must be sent as "file[]" (or any distinct names): PHP keeps only
    // the last of several parts that share the plain name "file".
    // Forwarded to apiringq /ticket/createticket, which already accepts a
    // "payload" JSON field plus files and passes them to cms_create_ticket.
    // The Flutter app's JSON/form requests carry "type" and are unchanged.
    // ───────────────────────────────────────────────────────────────

    private const SUPPORT_MAX_FILES = 5;
    private const SUPPORT_MAX_FILE_BYTES = 15728640;
    private const SUPPORT_CATEGORIES = ["voice", "crash", "server", "other"];

    // Extension => content types libmagic may report for a genuine file of
    // that kind. OOXML files are zip containers and legacy Office files are
    // OLE compound documents, so both are accepted under those names too.
    private const SUPPORT_FILE_TYPES = [
        "png" => ["image/png"],
        "jpg" => ["image/jpeg"],
        "jpeg" => ["image/jpeg"],
        "pdf" => ["application/pdf"],
        "doc" => ["application/msword", "application/cdfv2", "application/x-ole-storage", "application/vnd.ms-office"],
        "docx" => ["application/vnd.openxmlformats-officedocument.wordprocessingml.document", "application/zip", "application/octet-stream"],
        "xls" => ["application/vnd.ms-excel", "application/cdfv2", "application/x-ole-storage", "application/vnd.ms-office"],
        "xlsx" => ["application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", "application/zip", "application/octet-stream"],
    ];

    private function isSupportTicketUpload(): bool
    {
        if (!$this->request->isPost()) {
            return false;
        }
        $contentType = strtolower((string) $this->request->getContentType());
        if (strpos($contentType, "multipart/form-data") === false) {
            return false;
        }
        if ((string) $this->request->getPost("type") !== "") {
            return false;
        }
        return $this->request->getPost("category") !== null
            || $this->request->getPost("issue") !== null
            || $this->request->hasFiles();
    }

    // Returns the accepted files, or an error message naming the file.
    private function validateSupportFiles(array $files)
    {
        $accepted = [];
        foreach ($files as $file) {
            $name = (string) $file->getName();
            if ($file->getError() === UPLOAD_ERR_NO_FILE && $name === "") {
                continue;
            }
            if ($file->getError() !== UPLOAD_ERR_OK) {
                return "\"{$name}\" could not be uploaded.";
            }
            if ((int) $file->getSize() > self::SUPPORT_MAX_FILE_BYTES) {
                return "\"{$name}\" is larger than 15 MB.";
            }
            $extension = strtolower((string) pathinfo($name, PATHINFO_EXTENSION));
            if (!isset(self::SUPPORT_FILE_TYPES[$extension])) {
                return "\"{$name}\" is not an allowed file type. Use PNG, JPEG, PDF, DOC, DOCX, XLS or XLSX.";
            }
            $realType = strtolower((string) $file->getRealType());
            if (!in_array($realType, self::SUPPORT_FILE_TYPES[$extension], true)) {
                return "\"{$name}\" does not look like a ." . $extension . " file.";
            }
            $accepted[] = $file;
        }
        if (count($accepted) > self::SUPPORT_MAX_FILES) {
            return "Attach at most " . self::SUPPORT_MAX_FILES . " files.";
        }
        return $accepted;
    }

    // Keyword each web category must appear in a help desk issue type name.
    private const SUPPORT_CATEGORY_KEYWORDS = ["voice" => "voice", "crash" => "crash", "server" => "server"];

    // Returns ["id" => string, "name" => string] for the issue type a
    // category belongs to, or null when none matches (always for "other").
    private function matchSupportIssue($category, array $issues)
    {
        $keyword = self::SUPPORT_CATEGORY_KEYWORDS[$category] ?? null;
        if ($keyword === null) {
            return null;
        }
        foreach ($issues as $issue) {
            $name = (string) ($issue["mainIssue"] ?? "");
            if (isset($issue["id"]) && stripos($name, $keyword) !== false) {
                return ["id" => (string) $issue["id"], "name" => $name];
            }
        }
        return null;
    }

    // The help desk's issue types, via apiringq /ticket/viewissue (what
    // accounts/support/5 returns). An empty list on any failure.
    private function fetchSupportIssues($qCompany, $urlPath, $licenseKey)
    {
        $curl = curl_init();
        curl_setopt_array($curl, [
            CURLOPT_URL => (string) $urlPath . "/ticket/viewissue",
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_CONNECTTIMEOUT => 10,
            CURLOPT_TIMEOUT => 30,
            CURLOPT_HTTP_VERSION => CURL_HTTP_VERSION_1_1,
            CURLOPT_CUSTOMREQUEST => "POST",
            CURLOPT_HTTPHEADER => [
                "Accept: application/vnd.api+json",
                "Content-Type: application/vnd.api+json",
                "UUID: " . $qCompany->uuid,
                "Authorization: asgasgihqwgagsjokashiogahiosasbjg",
                "Authorization-token: " . $qCompany->token,
            ],
            CURLOPT_POSTFIELDS => json_encode(["userId" => $qCompany->uid, "page" => 1, "licenseKey" => (string) $licenseKey]),
        ]);
        $response = curl_exec($curl);
        curl_close($curl);
        $decoded = $response === false ? null : json_decode((string) $response, true);
        return is_array($decoded) && isset($decoded["data"]) && is_array($decoded["data"]) ? $decoded["data"] : [];
    }

    private function createSupportTicketWithFiles($session, $qCompany, $urlPath, $licenseKey)
    {
        $urlPath = (string) $urlPath;
        $licenseKey = (string) $licenseKey;
        $reply = function (array $payload) {
            $this->response->setContent(json_encode($payload));
            return $this->response;
        };

        $category = strtolower(trim((string) $this->request->getPost("category")));
        if (!in_array($category, self::SUPPORT_CATEGORIES, true)) {
            return $reply(["result" => "error", "message" => "Choose a category: voice, crash, server or other."]);
        }
        $issue = trim((string) $this->request->getPost("issue"));
        if ($issue === "") {
            return $reply(["result" => "error", "message" => "Describe the issue."]);
        }

        $files = $this->validateSupportFiles($this->request->getUploadedFiles());
        if (is_string($files)) {
            return $reply(["result" => "error", "message" => $files]);
        }

        $sessionName = trim(($session["firstname"] ?? "") . " " . ($session["lastname"] ?? ""));
        $contactName = trim((string) $this->request->getPost("contactName"));
        $contactEmail = trim((string) $this->request->getPost("contactEmail"));
        if ($contactName === "") {
            $contactName = $sessionName;
        }
        if ($contactEmail === "" || !filter_var($contactEmail, FILTER_VALIDATE_EMAIL)) {
            $contactEmail = (string) ($session["email"] ?? "");
        }

        // The help desk has no fields for these, and apiringq refuses an
        // empty description, so they travel in the description text.
        $details = [];
        $reportedAt = trim((string) $this->request->getPost("reportedAt"));
        $instance = trim((string) $this->request->getPost("instance"));
        $partnerEmail = trim((string) $this->request->getPost("partnerEmail"));
        if ($reportedAt !== "") {
            $details[] = "Reported at: " . $reportedAt;
        }
        if ($instance !== "") {
            $details[] = "Instance: " . $instance;
        }
        if ($partnerEmail !== "") {
            $details[] = "Partner email: " . $partnerEmail;
        }
        $description = trim((string) $this->request->getPost("description"));
        if ($description === "") {
            $description = $issue;
        }
        if ($details) {
            $description .= "\n\n" . implode("\n", $details);
        }

        // The help desk files a ticket under one of its own issue types
        // (accounts/support/5). A client may send that id; otherwise the
        // category is matched to one by name. "other" has no matching type,
        // so it needs an explicit mainIssueId.
        $mainIssueId = trim((string) $this->request->getPost("mainIssueId"));
        $mainIssue = trim((string) $this->request->getPost("mainIssue"));
        if ($mainIssueId === "") {
            $match = $this->matchSupportIssue($category, $this->fetchSupportIssues($qCompany, $urlPath, $licenseKey));
            if ($match === null) {
                return $reply(["result" => "error", "message" => $category === "other"
                    ? "Choose an issue type: send mainIssueId from accounts/support/5."
                    : "The help desk issue types are unavailable. Please try again."]);
            }
            $mainIssueId = $match["id"];
            if ($mainIssue === "") {
                $mainIssue = $match["name"];
            }
        }
        $permissionMode = $this->redis->get($session["extension"] . "-" . $session["subdomain"] . "-permission");
        $payload = [
            "userId" => $qCompany->uid,
            "mainIssueId" => $mainIssueId,
            "mainIssue" => $mainIssue !== "" ? $mainIssue : $category,
            "encounter" => $issue,
            "description" => $description,
            "contact" => $contactName,
            "email" => $contactEmail,
            "name" => $contactName,
            "customerExt" => $session["extension"],
            "customerRole" => $permissionMode == 7 ? "user" : "admin",
            "licenseKey" => $licenseKey,
        ];

        // Built by hand: parts are named "file[]" so apiringq's PHP keeps
        // every file, and a filename cannot inject multipart headers.
        $boundary = "----RingQSupport" . bin2hex(random_bytes(16));
        $body = "--{$boundary}\r\n"
            . "Content-Disposition: form-data; name=\"payload\"\r\n\r\n"
            . json_encode($payload) . "\r\n";
        $attachments = [];
        foreach ($files as $file) {
            $filename = str_replace(['"', "\r", "\n"], "", (string) $file->getName());
            $body .= "--{$boundary}\r\n"
                . "Content-Disposition: form-data; name=\"file[]\"; filename=\"{$filename}\"\r\n"
                . "Content-Type: " . ((string) $file->getRealType() ?: "application/octet-stream") . "\r\n\r\n"
                . file_get_contents($file->getTempName()) . "\r\n";
            $attachments[] = ["filename" => $filename, "url" => null, "size" => (int) $file->getSize()];
        }
        $body .= "--{$boundary}--\r\n";

        $curl = curl_init();
        curl_setopt_array($curl, [
            CURLOPT_URL => $urlPath . "/ticket/createticket",
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_CONNECTTIMEOUT => 10,
            CURLOPT_TIMEOUT => 120,
            CURLOPT_HTTP_VERSION => CURL_HTTP_VERSION_1_1,
            CURLOPT_POST => true,
            CURLOPT_HTTPHEADER => [
                "Accept: application/json",
                "Content-Type: multipart/form-data; boundary=" . $boundary,
                "UUID: " . $qCompany->uuid,
                "Authorization: asgasgihqwgagsjokashiogahiosasbjg",
                "Authorization-token: " . $qCompany->token,
            ],
            CURLOPT_POSTFIELDS => $body,
        ]);
        $response = curl_exec($curl);
        if ($response === false) {
            error_log("support ticket upload: " . curl_error($curl));
            curl_close($curl);
            return $reply(["result" => "error", "message" => "The help desk could not be reached. Please try again."]);
        }
        curl_close($curl);

        $result = json_decode((string) $response, true);
        if (!is_array($result) || ($result["result"] ?? "") !== "success") {
            $message = is_array($result) && !empty($result["message"]) ? (string) $result["message"] : "The ticket could not be created.";
            return $reply(["result" => "error", "message" => $message]);
        }
        return $reply([
            "result" => "success",
            "ticketNo" => $result["ticketNo"] ?? null,
            "attachments" => $attachments,
        ]);
    }

    public function supportAction($type = 1, $page = 1, $ticketNo = 0)
    {
		$this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $session = $this->session->get("auth");
        if ($session) {
			$qCompany = QCompanies::findFirst([
               "conditions" => "domain_uuid = :domain_uuid:",
               "bind" => [
                  "domain_uuid" => $session["domain_uuid"],
               ],
               "bindTypes" => [Column::BIND_PARAM_STR],
            ]);
            if (!$qCompany) {
                $response = json_encode(
	                [
	                    "result" => "error",
	                    "message" => "Unathorized request. (Code AL1000)",
	                ]
	            );
	            $this->response->setContent($response);
	            return $this->response;
            }
			$urlPath = "https://apiringq.ringq.io";
            $vDomain = VDomains::findFirst([
               "conditions" => "domain_uuid = :domain_uuid:",
               "bind" => [
                  "domain_uuid" => $session["domain_uuid"],
               ],
               "bindTypes" => [Column::BIND_PARAM_STR],
            ]);
			if ($this->request->getServerAddress() == "165.232.164.1" || $vDomain->domain_name == "demo.my1.ringq.ai" || $vDomain->domain_name == "ringqltd.us2.ringq.ai") {
				$urlPath = "https://test.ringq.io";
			}
			$licenseKey = "";
			$installationConfig = $this->redis->get("ringq_config");
			if ($installationConfig) {
				$urlPath = "https://licensekey.ringq.com";
				$configData = json_decode($installationConfig, true);
                $licenseKey = $configData['data']['licenseKey'];
			}
        	if ($this->request->isGet() || ($this->request->isPost() && $type == 12)) {
        		if ($type == 1 || $type == 2 || $type == 3 || $type == 4 || $type == 5) {
					$post_data = [
                        "userId" => $qCompany->uid,
                        "page" => $page,
						"licenseKey" => $licenseKey
                    ];
                    if ($type == 1) {
                    	$urlPath = $urlPath ."/ticket/newticket";
                    }
        			if ($type == 2) {
        				$urlPath = $urlPath ."/ticket/openticket";
        			}
        			if ($type == 3) {
        				$urlPath = $urlPath ."/ticket/closeticket";
        			}
        			if ($type == 4) {
