    public function logoutAction($deviceId = 0, $pushToken = "")
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $session = $this->session->get("auth");
        if (!$session) {
            $response = json_encode(
                [
                    "result" => "error",
                    "message" => "Unathorized request. (Code AL1000)",
                ]
            );
            $this->response->setContent($response);
            return $this->response;
        }
        $qDevice = QDevices::findFirst(
            [
                "conditions" => "domain_uuid = :domain_uuid: AND user_uuid = :user_uuid: AND id = :id:",
                "bind" =>
                    [
                        "domain_uuid" => $session["domain_uuid"],
                        "user_uuid" => $session["user_uuid"],
                        "id" => intval($deviceId)
                    ],
                "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR, Column::BIND_PARAM_INT]
            ]
        );
        if ($qDevice) {
            $qDevice->delete();
        }
        // [logout-push] The mobile apps send their device UUID, not the numeric q_devices id, so
        // the lookup above never matched and a signed-out phone kept getting call pushes. They now
        // also send ?push_token= (the iOS VoIP / Android FCM token): forget that phone everywhere
        // the push code looks it up.
        $logoutPushToken = trim(strval($this->request->getQuery("push_token", "string", "")));
        if ($logoutPushToken !== "") {
            $signedOutDevices = QDevices::find(
                [
                    "conditions" => "domain_uuid = :domain_uuid: AND user_uuid = :user_uuid: AND push_token = :push_token:",
                    "bind" =>
                        [
                            "domain_uuid" => $session["domain_uuid"],
                            "user_uuid" => $session["user_uuid"],
                            "push_token" => $logoutPushToken,
                        ],
                    "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR, Column::BIND_PARAM_STR]
                ]
            );
            foreach ($signedOutDevices as $signedOutDevice) {
                $signedOutDevice->delete();
            }
            $pushBase = $session["extension"] . "@" . $session["subdomain"];
            $this->redis->srem("iosDevicePushToken-" . $pushBase, $logoutPushToken);
            $this->redis->srem("iosSucessPushToken-" . $pushBase, $logoutPushToken);
            $this->redis->del("apnsRoute:" . $logoutPushToken);
            $androidKey = "android:" . $session["extension"] . ":" . $session["subdomain"];
            if ($this->redis->get($androidKey) === $logoutPushToken) {
                $this->redis->del($androidKey);
            }
        }
        $vExtensionUser = VExtensionUsers::findFirst(
            [
                "conditions" => "user_uuid = :user_uuid:",
                "bind" =>
                    [
                        "user_uuid" => $session["user_uuid"],
                    ],
                "bindTypes" =>
                    [
                        Column::BIND_PARAM_STR,
                    ]
            ]
        );
        if ($vExtensionUser) {
            $vUser = VUsers::findFirst(
                [
                    "conditions" => "user_uuid = :user_uuid:",
                    "bind" =>
                        [
                            "user_uuid" => $session["user_uuid"],
                        ],
                    "bindTypes" =>
                        [
                            Column::BIND_PARAM_STR,
                        ]
                ]
            );
            if ($vUser) {
                $vUser->user_status = "Logged Out";
                $vUser->update();
            }
            $qUser = QUsers::findFirst(
                [
                    "conditions" => "user_uuid = :user_uuid:",
                    "bind" =>
                        [
                            "user_uuid" => $session["user_uuid"],
                        ],
                    "bindTypes" =>
                        [
                            Column::BIND_PARAM_STR,
                        ]
                ]
            );
            if ($qUser) {
                $this->redis->del($session["subdomain"] . $session["extension"] .":". $qUser->push_token);
                // THIS WAS A BUG CAUSING WEBAPP LOGOUT TO ALSO REMOVE IOS PUSH TOKENS
                // $this->redis->del($session["extension"] . "@" . $session["subdomain"]);
                $qUser->push_token = null;
                $qUser->update();
            }
            if (!empty($pushToken)) {
           		$pushToken = $this->filter->sanitize($pushToken, "string");
	            $this->redis->srem("deviceWebToken-". $session["extension"] ."@". $session["subdomain"], $pushToken);
            }
			$client = new Client(Client::engine(Client::CLIENT_4X, "ws://127.0.0.1:3000", [
            	"persistent" => false,
	        ]));
	        $client->initialize();
	        $client->emit("localstreamreload", ["subdomain" => $session["subdomain"]]);
            $this->redis->set("wallstatus:" . $session["subdomain"] . ":". $vExtensionUser->vExtensions->extension, 0);
        }

		$client = new Client(Client::engine(Client::CLIENT_4X, "ws://127.0.0.1:3000", [
	        "persistent" => false,
	    ]));
	    $client->initialize();
	    $client->emit("logoutStatus2", ["subdomain" => $session["subdomain"], "extension" => $session["extension"], "status" => 0, "deviceId" => $deviceId]);
        $client = new Client(Client::engine(Client::CLIENT_4X, "ws://127.0.0.1:3000", [
            "persistent" => false,
        ]));
        $client->initialize();
		$devicePushToken = isset($qDevice->push_token) ? $qDevice->push_token : $session["pushtoken"];
		$this->redis->del("iosDevicePushToken-". $session["extension"] ."@". $session["subdomain"]);
		error_log("<!-- THIS IS CALLED : " . "iosDevicePushToken-". $session["extension"] ."@". $session["subdomain"]);
		$client->emit("logout", ["subdomain" => $session["subdomain"], "extension" => $session["extension"], "pushToken" => $devicePushToken, "deviceId" => $deviceId]);
        if ($this->cookies->has("RINGQKIE") || $this->cookies->has('RINGQENS')) {
            $tokens = $this->cookies->get('RINGQENS');
            $user_uuid = $this->cookies->get('RINGQKIE');
            $access_token = $tokens->getValue();
            $qToken = QTokens::findFirst(
                [
                    "conditions" => "access_token = :access_token:",
                    "bind" =>
                        [
                            "access_token" => $access_token,
                        ],
                    "bindTypes" => [Column::BIND_PARAM_STR]
                ]
            );
            if ($qToken) {
                $qToken->delete();
            }
            $user_uuid->delete();
            $tokens->delete();
        }
        $this->cookies->get('RINGQ')->delete();
        $this->session->destroy();
		$response = json_encode(
            [
                "result" => "success",
                "message" => "Successfully logged out.",
            ]
        );
        $this->response->setContent($response);
        return $this->response;
    }

