                    $this->redis->set($parameters["extension"] ."@". $session["subdomain"] ."-ringGroupTimeout", $this->dialPlanEntry($parameters["no_answer_action"], strval(intval($parameters["extension"]))));
                    if (file_exists("/var/cache/fusionpbx/dialplan.". $session["subdomain"])) {
                        unlink("/var/cache/fusionpbx/dialplan.". $session["subdomain"]);
                    }
                    if (file_exists("/var/cache/ringq/dialplan.". $session["subdomain"])) {
                        unlink("/var/cache/ringq/dialplan.". $session["subdomain"]);
                    }
                    $response = json_encode(
                        [
                            "result" => "success",
                            "message" => "Successfully, created the team.",
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                } else if (intval($parameters["type"]) == 2) {
					$vRingGroups = VRingGroups::findFirst(
                        [
                            "conditions" => "domain_uuid = :domain_uuid: AND ring_group_extension != :ring_group_extension: AND ring_group_name = :ring_group_name:",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                    "ring_group_extension" => intval($parameters["extension"]),
                                    "ring_group_name" => $parameters["voicemail_name"],
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_INT, Column::BIND_PARAM_STR],
                        ]
                    );
                    if ($vRingGroups) {
                        $response = json_encode(
                            [
                                "result" => "error",
                                "message" => "Sorry, team name already exists (Code AT21002)",
                                "content" => [],
                            ]
                        );
                        $this->response->setContent($response);
                    }
                    $vRingGroup = VRingGroups::findFirst(
                        [
                            "conditions" => "domain_uuid = :domain_uuid: AND ring_group_extension = :ring_group_extension:",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                    "ring_group_extension" => intval($parameters["extension"]),
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_INT],
                        ]
                    );
                    if (!$vRingGroup) {
                        $response = json_encode(
                            [
                                "result" => "error",
                                "message" => "Sorry, team extension does not exists (Code AT21005)",
                                "content" => [],
                            ]
                        );
                        $this->response->setContent($response);
                    }
                    $this->db->begin();
                    $vRingGroup->ring_group_name = $parameters["voicemail_name"];
                    $vRingGroup->ring_group_call_timeout = intval($parameters["no_answer_seconds"]);
                    $vRingGroup->ring_group_timeout_app = "transfer";
                    $vRingGroup->ring_group_timeout_data = $this->dialPlanEntry($parameters["no_answer_action"], strval(intval($parameters["extension"])));
                    $vRingGroup->update_user = $session["user_uuid"];
                    $vRingGroup->update_date = date("Y-m-d H:i:s");
                    if(!$vRingGroup->update()) {
                        $this->db->rollback();
                        $response = json_encode(
                            [
                                "result" => "error",
                                "message" => "An error has occurred. (Code AT21003)",
                            ]
                        );
                        $this->response->setContent($response);
                        return $this->response;
                    }
                    $vVoicemail = VVoicemails::findFirst(
                        [
                            "conditions" => "domain_uuid = :domain_uuid: AND voicemail_id = :voicemail_id:",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                    "voicemail_id" => intval($parameters["extension"]),
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_INT],
                        ]
                    );
                    if (!$vVoicemail) {
                        $response = json_encode(
                            [
                                "result" => "error",
                                "message" => "Sorry, team extension does not exists (Code AT21005)",
                                "content" => [],
                            ]
                        );
                        $this->response->setContent($response);
                    }
                    $vRingGroup->ring_group_name = $parameters["voicemail_name"];
                    $vRingGroup->update_user = $session["user_uuid"];
                    $vRingGroup->update_date = date("Y-m-d H:i:s");
                    if(!$vRingGroup->update()) {
                        $this->db->rollback();
                        $response = json_encode(
                            [
                                "result" => "error",
                                "message" => "An error has occurred. (Code AT21006)",
                            ]
                        );
                        $this->response->setContent($response);
                        return $this->response;
                    }
                    $vRingGroupDestinations = VRingGroupDestinations::find(
                        [
                            "conditions" => "domain_uuid = :domain_uuid: AND ring_group_uuid = :ring_group_uuid:",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                    "ring_group_uuid" => $vRingGroup->ring_group_uuid,
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                        ]
                    );
                    foreach($vRingGroupDestinations as $vRingGroupDestination) {
						$ringExtension = VExtensions::findFirst([
                            "conditions" => "domain_uuid = :domain_uuid: AND extension = :extension:",
                            "bind" => [
                                "domain_uuid" => $session["domain_uuid"],
                                "extension" => $vRingGroupDestination->destination_number,
                            ],
                            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_INT],
                        ]);
                        if ($ringExtension) {
                        	$ringExtension->call_group = null;
                        	$ringExtension->pickup_group = null;
							if (file_exists("/var/cache/ringq/directory." . $ringExtension->extension . "@" . $session["subdomain"])) {
							    unlink("/var/cache/ringq/directory." . $ringExtension->extension . "@" . $session["subdomain"]);
							}
							if (file_exists("/var/cache/ringq/directory." . $ringExtension->number_alias . "@" . $session["subdomain"])) {
							    unlink("/var/cache/ringq/directory." . $ringExtension->number_alias . "@" . $session["subdomain"]);
							}
                        	if(!$ringExtension->update()) {
	                            $this->db->rollback();
	                            $response = json_encode(
	                                [
	                                    "result" => "error",
	                                    "message" => "An error has occurred. (Code AT21004)",
	                                ]
	                            );
	                            $this->response->setContent($response);
	                            return $this->response;
	                        }
                        }
                        if(!$vRingGroupDestination->delete()) {
                            $this->db->rollback();
                            $response = json_encode(
                                [
                                    "result" => "error",
                                    "message" => "An error has occurred. (Code AT21004)",
                                ]
                            );
                            $this->response->setContent($response);
                            return $this->response;
                        }
                    }
                    $security = new \Phalcon\Security\Random();
                    $extensions = explode(",", $parameters["extensions"]);
                    $extensions2 = array();
                    foreach ($extensions as $extension) {
                        array_push($extensions2, intval($extension));
                        if ($parameters["enable_pickup"] == 1) {
	                        $ringExtension = VExtensions::findFirst([
	                            "conditions" => "domain_uuid = :domain_uuid: AND extension = :extension:",
	                            "bind" => [
	                                "domain_uuid" => $session["domain_uuid"],
	                                "extension" => $extension,
	                            ],
	                            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_INT],
	                        ]);
	                        if ($ringExtension) {
	                        	$ringExtension->call_group = $parameters["voicemail_name"];
	                        	$ringExtension->pickup_group = $parameters["voicemail_name"];
	                        	if(!$ringExtension->update()) {
		                            $this->db->rollback();
		                            $response = json_encode(
		                                [
		                                    "result" => "error",
		                                    "message" => "An error has occurred. (Code AT21004)",
		                                ]
		                            );
		                            $this->response->setContent($response);
		                            return $this->response;
		                        }
	                        }
                        }
                        $vRingGroupDestination = new VRingGroupDestinations();
                        $vRingGroupDestination->ring_group_uuid = $vRingGroup->ring_group_uuid;
                        $vRingGroupDestination->ring_group_destination_uuid = $security->uuid();
                        $vRingGroupDestination->destination_number = strval(intval($extension));
                        $vRingGroupDestination->destination_delay = 0;
                        $vRingGroupDestination->destination_timeout = intval($parameters["no_answer_seconds"]);
                        $vRingGroupDestination->destination_enabled = "true";
                        $vRingGroupDestination->domain_uuid = $session["domain_uuid"];
                        $vRingGroupDestination->insert_user = $session["user_uuid"];
                        if(!$vRingGroupDestination->create()) {
                            $this->db->rollback();
                            $response = json_encode(
                                [
                                    "result" => "error",
                                    "message" => "An error has occurred. (Code AT21004)",
                                ]
                            );
                            $this->response->setContent($response);
                            return $this->response;
                        }
                    }
                    $vVoicemail->notify_missed = intval($parameters["notify_missed"]);
                    $vVoicemail->notify_missed2 = intval($parameters["notify_missed2"]);
                    $vVoicemail->extensions = implode(",", $extensions2);
                    if(!$vVoicemail->update()) {
                        $this->db->rollback();
                        $response = json_encode(
                            [
                                "result" => "error",
                                "message" => "An error has occurred. (Code AT21006)",
                            ]
                        );
                        $this->response->setContent($response);
                        return $this->response;
                    }
                    $vDialplan = VDialplans::findFirst(
                        [
                            "conditions" => "domain_uuid = :domain_uuid: AND dialplan_number = :dialplan_number:",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                    "dialplan_number" => "*88" . intval($parameters["extension"]),
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                        ]
                    );
                    $extensions3 = implode("|", $extensions2);
                    $vDialplan->dialplan_xml = '<extension name="vmain_group-team-'. $parameters["extension"] .'" continue="" uuid="'. $vDialplan->dialplan_uuid .'">
                        <condition field="${user_name}" expression="^'. $extensions3 .'$"/>
                        <condition field="destination_number" expression="^\*88'. $parameters["extension"] .'$">
                            <action application="answer" data=""/>
                            <action application="sleep" data="1000"/>
                            <action application="set" data="record_append=false"/>
                            <action application="set" data="voicemail_action=check"/>
                            <action application="set" data="voicemail_id='. $parameters["extension"] .'"/>
                            <action application="set" data="voicemail_profile=default"/>
                            <action application="lua" data="app.lua voicemail"/>
                        </condition>
                    </extension>';
                    $vDialplan->update_user = $session["user_uuid"];
                    $vDialplan->update_date = date("Y-m-d H:i:s");
                    if (!$vDialplan->update()) {
                        $this->db->rollback();
                        $messages = $vDialplan->getMessages();
                        $message = "";
                        foreach ($messages as $error) {
                            $message .= $error . " ";
                        }
                        $response = json_encode(
                            [
                                "result" => "error",
                                "message" => trim($message) . " (Code AT21007)",
                                "content" => [],
                            ]
                        );
                        $this->response->setContent($response);
                        return $this->response;
                    }
                    $vDialplan2 = VDialplans::findFirst(
                        [
                            "conditions" => "domain_uuid = :domain_uuid: AND dialplan_number = :dialplan_number:",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                    "dialplan_number" => intval($parameters["extension"]),
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                        ]
                    );
					if ($parameters["enable_paging"] == 1) {
                    	$muted = $parameters["mute_paging"] == 1 ? "true" : "false";
                    	$teamDestinations = implode(",", $extensions);
						$vDialplan2->dialplan_xml = '<extension name="page" continue="false" uuid="'. $vDialplan2->dialplan_uuid .'">
						  <condition field="destination_number" expression="^'. $parameters["extension"]. '$">
						    <action application="set" data="caller_id_name=Paging*"/>
						    <action application="set" data="caller_id_number=${effective_caller_id_number}"/>
						    <action application="export" data="nolocal:sip_auto_answer=true"/>
						    <action application="export" data="nolocal:sip_invite_params=intercom=true"/>
						    <action application="export" data="nolocal:sip_h_X-Auto-Answer=true"/>
						    <!-- Vendor-specific SIP Headers for Hardware Phones -->
						    <action application="export" data="nolocal:sip_h_Call-Info=<http://www.notused.com>;answer-after=0"/>
						    <action application="export" data="nolocal:sip_h_Alert-Info=Ring Answer"/>
						    <!-- Page Group Configurations -->
						    <action application="set" data="destinations='. $teamDestinations .'"/>
						    <action application="set" data="moderator=false"/>
						    <action application="set" data="mute='. (string)$muted .'"/>
						    <!-- Execute Lua script -->
						    <action application="lua" data="page.lua"/>
						  </condition>
						</extension>';
						error_log((string)$muted);
                    } else {
                    	$vDialplan2->dialplan_xml = '<extension name="ring_group-team-'. $parameters["extension"] .'" continue="" uuid="'. $vDialplan2->dialplan_uuid .'">
	                        <condition field="destination_number" expression="^'. $parameters["extension"] .'$">
	                            <action application="ring_ready" data=""/>
	                            <action application="set" data="ring_group_uuid='. $vRingGroup->ring_group_uuid .'"/>
	                            <action application="lua" data="app.lua ring_groups"/>
	                        </condition>
	                    </extension>';
                    }
                    $vDialplan2->update_user = $session["user_uuid"];
                    $vDialplan2->update_date = date("Y-m-d H:i:s");
                    if (!$vDialplan2->update()) {
                        $this->db->rollback();
                        $messages = $vDialplan2->getMessages();
                        $message = "";
                        foreach ($messages as $error) {
                            $message .= $error . " ";
                        }
                        $response = json_encode(
                            [
                                "result" => "error",
                                "message" => trim($message) . " (Code AT21007)",
                                "content" => [],
                            ]
                        );
                        $this->response->setContent($response);
                        return $this->response;
                    }
                    $this->db->commit();
                    $this->redis->set($parameters["extension"] ."@". $session["subdomain"] ."-teamEnablePaging", $parameters["enable_paging"]);
                    $this->redis->set($parameters["extension"] ."@". $session["subdomain"] ."-teamMutePaging", $parameters["mute_paging"]);
                    $this->redis->set($parameters["extension"] ."@". $session["subdomain"] ."-teamEnablePickup", $parameters["enable_pickup"]);
                    $this->redis->set($parameters["extension"] ."@". $session["subdomain"] ."-ringGroupTimeout", $this->dialPlanEntry($parameters["no_answer_action"], strval(intval($parameters["extension"]))));
                    if (file_exists("/var/cache/fusionpbx/dialplan.". $session["subdomain"])) {
                        unlink("/var/cache/fusionpbx/dialplan.". $session["subdomain"]);
                    }
                    if (file_exists("/var/cache/ringq/dialplan.". $session["subdomain"])) {
                        unlink("/var/cache/ringq/dialplan.". $session["subdomain"]);
                    }
                    $response = json_encode(
                        [
                            "result" => "success",
                            "message" => "Successfully updated the team.",
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                }
            } else {
                if (intval($parameters["type"]) == 3) {
                    $vRingGroup = VRingGroups::findFirst(
                        [
                            "conditions" => "domain_uuid = :domain_uuid: AND ring_group_extension = :ring_group_extension:",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                    "ring_group_extension" => intval($parameters["extension"]),
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_INT],
                        ]
                    );
                    $vVoicemail = VVoicemails::findFirst(
                        [
                            "conditions" => "domain_uuid = :domain_uuid: AND voicemail_id = :voicemail_id:",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                    "voicemail_id" => intval($parameters["extension"]),
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_INT],
                        ]
                    );
                    if (!$vRingGroup) {
                        $response = json_encode(
                            [
                                "result" => "error",
                                "message" => "Sorry, team extension does not exists (Code AT21005)",
                                "content" => [],
                            ]
                        );
                        $this->response->setContent($response);
                        return $this->response;
                    }
                    $this->db->begin();
                    // The ring group owns the dialplan reference, so this lookup is only possible when it exists.
                    $vDialplan = null;
                    if ($vRingGroup->dialplan_uuid) {
                        $vDialplan = VDialplans::findFirst(
                            [
                                "conditions" => "domain_uuid = :domain_uuid: AND dialplan_uuid = :dialplan_uuid:",
                                "bind" =>
                                    [
                                        "domain_uuid" => $session["domain_uuid"],
                                        "dialplan_uuid" => $vRingGroup->dialplan_uuid,
                                    ],
                                "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                            ]
                        );
                    }
                    // The *88 pickup dialplan is optional; a team created before it existed simply has none.
                    $vDialplan2 = VDialplans::findFirst(
                        [
                            "conditions" => "domain_uuid = :domain_uuid: AND dialplan_number = :dialplan_number:",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                    "dialplan_number" => "*88" . intval($parameters["extension"]),
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                        ]
                    );
                    if ($vRingGroup) {
                        $vRingGroupDestinations = VRingGroupDestinations::find(
                            [
                                "conditions" => "domain_uuid = :domain_uuid: AND ring_group_uuid = :ring_group_uuid:",
                                "bind" =>
                                    [
                                        "domain_uuid" => $session["domain_uuid"],
                                        "ring_group_uuid" => $vRingGroup->ring_group_uuid,
                                    ],
                                "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                            ]
                        );
                        foreach ($vRingGroupDestinations as $vRingGroupDestination) {
							$ringExtension = VExtensions::findFirst([
	                            "conditions" => "domain_uuid = :domain_uuid: AND extension = :extension:",
	                            "bind" => [
	                                "domain_uuid" => $session["domain_uuid"],
	                                "extension" => $vRingGroupDestination->destination_number,
	                            ],
	                            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_INT],
	                        ]);
	                        if ($ringExtension) {
	                        	$ringExtension->call_group = null;
	                        	$ringExtension->pickup_group = null;
								if (file_exists("/var/cache/ringq/directory." . $ringExtension->extension . "@" . $session["subdomain"])) {
								    unlink("/var/cache/ringq/directory." . $ringExtension->extension . "@" . $session["subdomain"]);
								}
								if (file_exists("/var/cache/ringq/directory." . $ringExtension->number_alias . "@" . $session["subdomain"])) {
								    unlink("/var/cache/ringq/directory." . $ringExtension->number_alias . "@" . $session["subdomain"]);
								}
	                        	if(!$ringExtension->update()) {
		                            $this->db->rollback();
		                            $response = json_encode(
		                                [
		                                    "result" => "error",
		                                    "message" => "An error has occurred. (Code AT21004)",
		                                ]
		                            );
		                            $this->response->setContent($response);
		                            return $this->response;
		                        }
	                        }
                            if (!$vRingGroupDestination->delete()) {
                                $this->db->rollback();
                                $response = json_encode(
                                    [
                                        "result" => "error",
                                        "message" => "An error has occurred. (Code AT21004)",
                                    ]
                                );
                                $this->response->setContent($response);
                                return $this->response;
                            }
                        }
                    }
                    // Each part is deleted only when present. $failed reports which one refused, so a genuine
                    // database error is still surfaced rather than silently swallowed.
                    $teamParts = [
                        ["AT21010", $vRingGroup],
                        ["AT21010", $vVoicemail],
                        ["AT21011", $vDialplan],
                        ["AT21011", $vDialplan2],
                    ];
                    foreach ($teamParts as $teamPart) {
                        list($code, $record) = $teamPart;
                        if (!$record) {
                            continue;
                        }
                        if (!$record->delete()) {
                            $this->db->rollback();
                            $message = "";
                            foreach ($record->getMessages() as $error) {
                                $message .= $error . " ";
                            }
                            $response = json_encode(
                                [
                                    "result" => "error",
                                    "message" => trim($message) . " (Code " . $code . ")",
                                    "content" => [],
                                ]
                            );
                            $this->response->setContent($response);
                            return $this->response;
                        }
                    }
                    $this->db->commit();
                    $this->redis->del($parameters["extension"] ."@". $session["subdomain"] ."-teamEnablePaging");
                    $this->redis->del($parameters["extension"] ."@". $session["subdomain"] ."-teamMutePaging");
                    $this->redis->del($parameters["extension"] ."@". $session["subdomain"] ."-teamEnablePickup");
                    $this->redis->del($parameters["extension"] ."@". $session["subdomain"] ."-ringGroupTimeout");
                    if (file_exists("/var/cache/fusionpbx/dialplan.". $session["subdomain"])) {
                        unlink("/var/cache/fusionpbx/dialplan.". $session["subdomain"]);
                    }
                    if (file_exists("/var/cache/ringq/dialplan.". $session["subdomain"])) {
                        unlink("/var/cache/ringq/dialplan.". $session["subdomain"]);
                    }
                    $response = json_encode(
                        [
                            "result" => "success",
                            "message" => "Successfully delted the team.",
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                }
            }
        }
    }

    public function voicemailAction()
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $session = $this->session->get("auth");
        if (!$session) {
            $response = json_encode(
                [
                    "result" => "error",
                    "message" => "Sorry, unathorized request made (Code AU21000)",
                ]
            );
            $this->response->setContent($response);
            return $this->response;
        }
        if ($this->request->isPost()) {
            $parameters = array();
            $parameters["id"] = intval($this->request->getPost("id", "int"));
            $parameters["type"] = intval($this->request->getPost("type", "int"));
            $parameters["extension"] = intval($this->request->getPost("extension", "int"));
            $parameters["greeting_name"] = $this->request->getPost("greeting_name", "string");
            $parameters["greeting_description"] = $this->request->getPost("greeting_description", "string");
            if (empty($parameters["type"])) {
                $contents = file_get_contents("php://input");
                $parameters = json_decode($contents, true);
            }
            if ($this->isPlainUser($session) && (string) ($parameters["extension"] ?? "") !== (string) $session["extension"]) {
                return $this->forbiddenForUser();
            }
            if ($parameters["type"] == 1 || $parameters["type"] == 2) {
	            $audioForm = new AudioForm();
	            if (!$audioForm->isValid($parameters)) {
	                $messages = $audioForm->getMessages();
	                $message = "";
	                foreach ($messages as $error) {
	                    $message .= $error . " ";
	                }
	                $response = json_encode(
	                    [
	                        "result" => "error",
	                        "message" => trim($message) . " (Code AU21001)",
	                        "content" => [],
	                    ]
	                );
	                $this->response->setContent($response);
	                return $this->response;
	            }
	            $vVoicemailGreeting = VVoicemailGreetings::findFirst(
	                [
	                    "conditions" => "domain_uuid = :domain_uuid: AND voicemail_id = :voicemail_id: AND greeting_name = :greeting_name:",
	                    "bind" =>
	                        [
	                            "domain_uuid" => $session["domain_uuid"],
	                            "voicemail_id" => strval(intval($parameters["extension"])),
	                            "greeting_name" => $greeting_name,
	                        ],
	                    "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
	                ]
	            );
	            if (!$vVoicemailGreeting) {
	                $response = json_encode(
	                    [
	                        "result" => "error",
	                        "message" => "Please check voicemail entry.",
	                        "content" => [],
	                    ]
	                );
	                $this->response->setContent($response);
	                return $this->response;
	            } else {
	                $vVoicemailGreeting->greeting_name = $greeting_name;
