    /*
    |--------------------------------------------------------------------------
    | Network settings: the internal interface and the public (external) IP
    |--------------------------------------------------------------------------
    |
    | Two types on ONE action, deliberately:
    |
    |   accounts/interface/2  -> mint a code and email it (no write)
    |   accounts/interface    -> verify the code, then apply the change
    |
    | `app/config/services.php` registers ACTIONS, not types, so a new type
    | needs no ACL entry -- the same reason `booking/booking/9` did not. A new
    | *action* would have to be added to BOTH role blocks, and missing either
    | 404s in a way indistinguishable from a failed deployment.
    |
    | The OTP gates EVERY save on the IP tab, including an interface-only
    | change and a re-save of unchanged values. That is broader than "public IP
    | changed" on purpose: `sip-ip`/`rtp-ip` decide which address FreeSWITCH
    | binds and can drop every registration on the box just as surely.
    |
    */
    public function interfaceAction($type = 1)
    {
		$this->view->setRenderLevel(View::LEVEL_NO_RENDER);
		$this->response->setHeader("Content-Type", "application/json");

		// This action had NO session guard of its own -- it relied entirely on
		// the Phalcon ACL, unlike its neighbours (compare phonetempAction's
		// "Code AI1001"). The OTP below must not be the only thing standing in
		// front of a write that re-points the SIP profile, and the OTP itself
		// needs the session to know whom to email.
		$session = $this->session->get("auth");
		if (!$session) {
			return $this->response->setContent(json_encode([
				"result" => "error",
				"message" => "Unauthorized. (Code AI1001)",
			]));
		}

		if ($this->request->isPost()) {
			$parameters = [];
			$parameters["ipAddress"] = $this->request->getPost("ipAddress", "string");
			$parameters["ipAddress2"] = $this->request->getPost("ipAddress2", "string");
			$parameters["otp"] = $this->request->getPost("otp", "string");
			if (empty($parameters["ipAddress"])) {
				$contents = file_get_contents("php://input");
				$parameters = json_decode($contents, true);
			}
			// Both end up in the SIP profiles and the server's DNS A record, so only a plain IPv4
			// address is accepted. Phalcon has no "ipv4" sanitizer: it only raised a notice and
			// let any string through. The interface address may be private, so no range flags.
			$parameters["ipAddress"] = filter_var(trim((string)($parameters["ipAddress"] ?? "")), FILTER_VALIDATE_IP, FILTER_FLAG_IPV4) ?: "";
			$parameters["ipAddress2"] = filter_var(trim((string)($parameters["ipAddress2"] ?? "")), FILTER_VALIDATE_IP, FILTER_FLAG_IPV4) ?: "";
			if (!$parameters["ipAddress"]) {
			    $response = json_encode([
			        "result" => "error",
			        "message" => "Sorry, invalid IP address.",
			    ]);
			    $this->response->setContent($response);
			    return $this->response;
			}
			if (!$parameters["ipAddress2"]) {
			    $response = json_encode([
			        "result" => "error",
			        "message" => "Sorry, invalid IP address.",
			    ]);
			    $this->response->setContent($response);
			    return $this->response;
			}

			// ---- OTP gate ------------------------------------------------
			// Type 2 mints and mails a code and writes NOTHING. Type 1 must
			// present that code, and the code is bound to the exact pair of
			// addresses it was issued for -- otherwise a code obtained for a
			// harmless value would authorise any later value, and the email the
			// operator read would not describe the change being made.
			if (intval($type) === 2) {
				return $this->sendInterfaceOtp($session, $parameters);
			}

			$otpFailure = $this->checkInterfaceOtp($session, $parameters);
			if ($otpFailure !== null) {
				$this->response->setContent(json_encode($otpFailure));
				return $this->response;
			}
			// ---- end OTP gate --------------------------------------------
            $vSipProfileSettings = VSipProfileSettings::find(
                [
                    "conditions" => "sip_profile_setting_name =:sip_profile_setting_name: OR sip_profile_setting_name =:sip_profile_setting_name2:",
                    "bind" => [
                        "sip_profile_setting_name" => "sip-ip",
                        "sip_profile_setting_name2" => "rtp-ip"
                    ],
                ]
            );
            foreach($vSipProfileSettings as $vSipProfileSetting) {
            	$vSipProfileSetting->sip_profile_setting_value = $parameters["ipAddress"];
            	$vSipProfileSetting->update();
            }
            $vSipProfileSettings2 = VSipProfileSettings::find(
                [
                    "conditions" => "sip_profile_setting_name =:sip_profile_setting_name: OR sip_profile_setting_name =:sip_profile_setting_name2:",
                    "bind" => [
                        "sip_profile_setting_name" => "ext-sip-ip",
                        "sip_profile_setting_name2" => "ext-rtp-ip"
                    ],
                ]
            );
            foreach($vSipProfileSettings2 as $vSipProfileSetting2) {
            	$vSipProfileSetting2->sip_profile_setting_value = $parameters["ipAddress2"];
            	$vSipProfileSetting2->update();
            }

			$getLicenseConfig = $this->redis->get('ringq_config');
        	$licenseConfig = json_decode($getLicenseConfig, true);

            $clApiUrl = 'https://api.cloudflare.com/client/v4/';

			$subdomain = '';
			$zoneDns = '';
			if ($licenseConfig['data']['installationType'] === 'multi') {
				$zoneDns = 'ringq.cloud';
				$subdomain = '*.' . str_replace('multi.', '', $licenseConfig['data']['fqdn']);
			}
			elseif ($licenseConfig['data']['installationType'] === 'single') {
				$zoneDns = 'ringq.ai';
				$subdomain = $licenseConfig['data']['fqdn'];
			}

            $request = function ($url, $postData = null, $method = "GET") {
                $ch = curl_init();
                curl_setopt($ch, CURLOPT_URL, $url);
                curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
                curl_setopt($ch, CURLOPT_HTTPHEADER, [
					"X-Auth-Email: " . 'cm@cal4care.com',
					"X-Auth-Key: " . 'cfk_yK52gGCUJcEJ4wTpUb440zCGDezukshBJCEWouIKa05a872a',
					"Content-Type: application/json"
				]);
                if ($method === "POST" || $method === "PUT" || $method === "PATCH") {
                    curl_setopt($ch, CURLOPT_CUSTOMREQUEST, $method);
                    curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode($postData));
                }
                $response = curl_exec($ch);
                curl_close($ch);
                return json_decode($response, true);
            }; 
            $zoneId = null;
            $getZoneId = $request($clApiUrl . "zones?name={$zoneDns}");
            if (!empty($getZoneId['result'])) {
                $zoneId = $getZoneId['result'][0]['id'];
            }
            $recordId = null;
            $url = $clApiUrl . "zones/{$zoneId}/dns_records?type=A&name={$subdomain}";
            $getDnsRecordId = $request($url);
            if (!empty($getDnsRecordId['result'][0]['id'])) {
                $recordId = $getDnsRecordId['result'][0]['id'];
            }
            if ($zoneId && $recordId) {
                $request(
                    $clApiUrl . "zones/{$zoneId}/dns_records/{$recordId}",
                    [
						"type" => "A",
						"name" => "{$subdomain}",
						"content" => $parameters["ipAddress2"],
						"ttl" => 120,
						"proxied" => false
                    ],
                    "PUT"
                );
            }
           	if (file_exists("/var/cache/ringq/configuration.sofia.conf.". gethostname())) {
                unlink("/var/cache/ringq/configuration.sofia.conf.". gethostname());
            }
			exec("sudo fs_cli -x 'reload mod_sofia'");
			exec("sudo fs_cli -x 'unload mod_xml_cdr'");
			exec("sudo fs_cli -x 'reload mod_xml_cdr'"); 
			exec("sudo /var/www/ringq/app/scripts/pbx-setup.sh 2>&1");
 
			return $this->response->setContent(json_encode([
				"result" => "success",
				"message" => "Successfuly updated interface.",
				"content" => "",
			]));
		}
    }

    /*
    |--------------------------------------------------------------------------
    | Network-change OTP
    |--------------------------------------------------------------------------
    |
    | The code is never stored, only its SHA-256 -- a redis dump is therefore
    | not a bypass. It is bound to the address pair it was issued for, single
    | use, attempt-capped, and every failure answers in the SAME shape, so the
    | endpoint cannot be used to tell "no request outstanding" apart from
    | "wrong code".
    |
    | The mail itself is sent by `app/jobs/worker.php`, which already holds the
    | relay credentials and drains `email_queue` every tick. Nothing about the
    | message body lives here.
    |
    */

    /**
     * The implementation moved to library/ActionOtp.php when the support
     * access grant became a second caller. The constants below are aliases so
     * any existing reference keeps working and there is still one source of
     * truth for the values.
     */

    /** Seconds a code stays valid. Mirrors kNetworkOtpTtlSeconds in the client. */
    const INTERFACE_OTP_TTL = ActionOtp::TTL;

    /** Seconds before another code may be requested. */
    const INTERFACE_OTP_COOLDOWN = ActionOtp::COOLDOWN;

    /** Wrong codes allowed before the outstanding code is destroyed. */
    const INTERFACE_OTP_MAX_ATTEMPTS = ActionOtp::MAX_ATTEMPTS;

    const ACTION_OTP_PREFIXES = ActionOtp::PREFIXES;

    private function actionOtpKeys($session, $purpose)
    {
        return ActionOtp::keys($session, $purpose);
    }

    private function actionOtpNormalise($target)
    {
        return ActionOtp::normalise($target);
    }

    private function actionOtpFqdn($session)
    {
        return ActionOtp::fqdn($this->getDI(), $session);
    }

    private function sendActionOtp($session, $purpose, array $target, $jobType, array $mail)
    {
        return $this->response->setContent(json_encode(
            ActionOtp::send($this->getDI(), $session, $purpose, $target, $jobType, $mail)
        ));
    }

    private function checkActionOtp($session, $purpose, array $target, $submitted, $mismatchMessage)
    {
        return ActionOtp::check($this->getDI(), $session, $purpose, $target, $submitted, $mismatchMessage);
    }

    /**
     * Mint a code, queue the email, and write nothing else.
     */
    private function sendInterfaceOtp($session, $parameters)
    {

        return $this->sendActionOtp($session, "ip-change", $this->interfaceOtpTarget($parameters), "ip_change_otp", [
            "newInterface"    => $parameters["ipAddress"],
            "newPublicIp"     => $parameters["ipAddress2"],
            "currentPublicIp" => $this->activeSipProfileSetting("ext-sip-ip"),
        ]);
    }

    private function activeSipProfileSetting($name)
    {
        try {
            $row = $this->db->fetchOne(
                "SELECT s.sip_profile_setting_value FROM v_sip_profile_settings s
                   JOIN v_sip_profiles p ON p.sip_profile_uuid = s.sip_profile_uuid
                  WHERE s.sip_profile_setting_name = :name AND COALESCE(s.sip_profile_setting_value, '') <> ''
                  ORDER BY CASE WHEN p.sip_profile_enabled::text = 'true' AND s.sip_profile_setting_enabled::text = 'true' THEN 0 ELSE 1 END,
                           CASE p.sip_profile_name WHEN 'internal' THEN 0 WHEN 'external' THEN 1 ELSE 2 END
                  LIMIT 1",
                \Phalcon\Db\Enum::FETCH_ASSOC,
                ["name" => $name]
            );
        } catch (\Throwable $e) {
            error_log("activeSipProfileSetting: " . $e->getMessage());
            return "";
        }
        return $row ? (string) $row["sip_profile_setting_value"] : "";
    }

    private function interfaceOtpTarget($parameters)
    {
        return [
            "ipAddress"  => $parameters["ipAddress"],
            "ipAddress2" => $parameters["ipAddress2"],
        ];
    }

    /**
     * Null when the submitted code authorises this exact change; otherwise the
     * error payload to return. On success the code is destroyed BEFORE the
     * caller writes anything -- a code that survives its own save is a replay.
     */
    private function checkInterfaceOtp($session, $parameters)
    {
        return $this->checkActionOtp(
            $session,
            "ip-change",
            $this->interfaceOtpTarget($parameters),
            $parameters["otp"] ?? "",
            "The addresses changed after that code was sent. Request a new code for the new values."
        );
    }

    private function sipProfileOtpTarget($parameters)
    {
        $op = intval($parameters["op"] ?? $parameters["type"] ?? 0);
        if ($op === 3) {
            return ["op" => 3, "sip_profile_uuid" => (string)($parameters["sip_profile_uuid"] ?? "")];
        }
        return [
            "op"                => $op,
            "sip_profile_uuid"  => (string)($parameters["sip_profile_uuid"] ?? ""),
            "sip_profile_name"  => trim((string)($parameters["sip_profile_name"] ?? "")),
            "sip_ip"            => trim((string)($parameters["sip_ip"] ?? "")),
            "sip_ext_ip"        => trim((string)($parameters["sip_ext_ip"] ?? "")),
            "sip_port"          => (string)intval($parameters["sip_port"] ?? 0),
            "sip_transport"     => (string)($parameters["sip_transport"] ?? ""),
            "inbound_codec_neg" => (string)($parameters["inbound_codec_neg"] ?? ""),
            "codecs"            => (string)($parameters["codecs"] ?? ""),
            "tls"               => (string)intval($parameters["tls"] ?? 0),
        ];
    }

    const ACL_SYSTEM_LISTS = ["providers", "localnet.auto"];

    const ACL_READONLY_LISTS = ["localnet.auto"];

    const ACL_MAX_OPS = 200;

    const ACL_MAX_NODES_PER_LIST = 1000;

    public function aclAction($type = 1)
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");

        $session = $this->session->get("auth");
        if (!$session) {
            return $this->response->setContent(json_encode([
                "result" => "error",
                "message" => "Unauthorized. (Code AI1001)",
            ]));
        }

        $permissionMode = (string)$this->redis->get(($session["extension"] ?? "") . "-" . ($session["subdomain"] ?? "") . "-permission");
        if (!in_array($permissionMode, ["7", "8"], true)) {
            return $this->response->setContent(json_encode([
                "result" => "error",
                "message" => "Only an owner or manager can change ACL lists.",
            ]));
        }

        try {
            if (!$this->request->isPost()) {
                return $this->response->setContent(json_encode([
                    "result" => "success",
                    "lists" => $this->aclListsForDisplay(),
                ]));
            }

            $body = json_decode((string)file_get_contents("php://input"), true);
            if (!is_array($body)) {
                $body = [];
            }

            $plan = $this->aclPlanChanges($body["ops"] ?? null);
            if (isset($plan["error"])) {
                return $this->response->setContent(json_encode([
                    "result" => "error",
                    "message" => $plan["error"],
                ]));
            }
            $target = ["hash" => hash("sha256", json_encode($plan["ops"]))];

            if (intval($type) === 2) {
                return $this->sendActionOtp($session, "acl-change", $target, "acl_change_otp", [
                    "changes"     => array_slice($plan["summary"], 0, 40),
                    "changeCount" => count($plan["summary"]),
                ]);
            }

            if (intval($type) !== 3) {
                return $this->response->setContent(json_encode([
                    "result" => "error",
                    "message" => "Unknown request.",
                ]));
            }

            $otpFailure = $this->checkActionOtp(
                $session,
                "acl-change",
                $target,
                $body["otp"] ?? "",
                "The ACL changes were edited after that code was sent. Request a new code for the new changes."
            );
            if ($otpFailure !== null) {
                return $this->response->setContent(json_encode($otpFailure));
            }

            $this->aclApplyChanges($plan["ops"], (string)($session["user_uuid"] ?? ""));

            foreach (glob("/var/cache/ringq/configuration.acl.conf*") ?: [] as $cacheFile) {
                @unlink($cacheFile);
            }
            $reloadOutput = [];
            $reloadCode = 1;
            exec("sudo fs_cli -x 'reloadacl' 2>&1", $reloadOutput, $reloadCode);
            $reloaded = $reloadCode === 0 && stripos(implode("\n", $reloadOutput), "-ERR") === false;

            return $this->response->setContent(json_encode([
                "result" => "success",
                "message" => $reloaded
                    ? "ACL lists updated and reloaded."
                    : "ACL lists updated, but FreeSWITCH did not confirm the reload. They apply on the next reload.",
                "reloaded" => $reloaded,
                "warnings" => $plan["warnings"],
                "lists" => $this->aclListsForDisplay(),
            ]));
        } catch (\Throwable $e) {
            error_log("aclAction: " . $e->getMessage());
            return $this->response->setContent(json_encode([
                "result" => "error",
                "message" => "The ACL lists could not be updated. Nothing was changed.",
            ]));
        }
    }

    private function aclReferences()
    {
        $rows = $this->db->fetchAll(
            "SELECT p.sip_profile_name, s.sip_profile_setting_name, s.sip_profile_setting_value
               FROM v_sip_profile_settings s
               JOIN v_sip_profiles p ON p.sip_profile_uuid = s.sip_profile_uuid
              WHERE s.sip_profile_setting_name LIKE '%acl%'
                AND s.sip_profile_setting_name <> 'auth-calls-acl-only'
                AND COALESCE(s.sip_profile_setting_value, '') <> ''",
            \Phalcon\Db\Enum::FETCH_ASSOC
        );
        $refs = [];
        foreach ($rows as $row) {
            $name = strtolower(trim((string)$row["sip_profile_setting_value"]));
            $refs[$name][] = $row["sip_profile_name"] . " (" . $row["sip_profile_setting_name"] . ")";
        }
        return $refs;
    }

    private function aclLoadState()
    {
        $lists = [];
        foreach ($this->db->fetchAll(
            "SELECT access_control_uuid, access_control_name, access_control_default, access_control_description
               FROM v_access_controls ORDER BY access_control_name",
            \Phalcon\Db\Enum::FETCH_ASSOC
        ) as $row) {
            $lists[(string)$row["access_control_uuid"]] = [
                "name" => (string)$row["access_control_name"],
                "default" => (string)$row["access_control_default"],
                "description" => (string)($row["access_control_description"] ?? ""),
                "nodes" => [],
            ];
        }
        foreach ($this->db->fetchAll(
            "SELECT access_control_node_uuid, access_control_uuid, node_type, node_cidr, node_description
               FROM v_access_control_nodes ORDER BY node_cidr",
            \Phalcon\Db\Enum::FETCH_ASSOC
        ) as $row) {
            $listUuid = (string)$row["access_control_uuid"];
            if (!isset($lists[$listUuid])) {
                continue;
            }
            $lists[$listUuid]["nodes"][(string)$row["access_control_node_uuid"]] = [
                "type" => (string)$row["node_type"],
                "cidr" => (string)$row["node_cidr"],
                "description" => (string)($row["node_description"] ?? ""),
            ];
        }
        return $lists;
    }

    private function aclListsForDisplay()
    {
        $refs = $this->aclReferences();
        $domains = [];
        foreach ($this->db->fetchAll(
            "SELECT DISTINCT domain_name FROM v_domains
              WHERE domain_uuid IN (SELECT DISTINCT domain_uuid FROM v_extensions WHERE enabled = 'true')
                AND domain_enabled = 'true'
              ORDER BY domain_name",
            \Phalcon\Db\Enum::FETCH_ASSOC
        ) as $row) {
            $domains[] = (string)$row["domain_name"];
        }

        $out = [];
        foreach ($this->aclLoadState() as $uuid => $list) {
            $lower = strtolower($list["name"]);
            $nodes = [];
            foreach ($list["nodes"] as $nodeUuid => $node) {
                $nodes[] = ["uuid" => $nodeUuid] + $node;
            }
            $out[] = [
                "uuid" => $uuid,
                "name" => $list["name"],
                "default" => $list["default"],
                "description" => $list["description"],
                "system" => in_array($lower, self::ACL_SYSTEM_LISTS, true),
                "readOnly" => in_array($lower, self::ACL_READONLY_LISTS, true),
                "referencedBy" => $refs[$lower] ?? [],
                "nodes" => $nodes,
                "autoDomains" => in_array($lower, ["providers", "domains"], true) ? $domains : [],
            ];
        }
        return $out;
    }

    public static function aclNormaliseCidr($value)
    {
        $value = trim((string)$value);
        if ($value === "") {
            return null;
        }
        $parts = explode("/", $value);
        if (count($parts) > 2) {
            return null;
        }
        $packed = @inet_pton($parts[0]);
        if ($packed === false) {
            return null;
        }
        $bits = strlen($packed) * 8;
        if (count($parts) === 2) {
            if (!preg_match('/^\d{1,3}$/', $parts[1])) {
                return null;
            }
            $prefix = intval($parts[1]);
            if ($prefix > $bits) {
                return null;
            }
        } else {
            $prefix = $bits;
        }
        $masked = "";
        for ($i = 0; $i < strlen($packed); $i++) {
            $keep = max(0, min(8, $prefix - $i * 8));
            $mask = $keep === 0 ? 0 : (0xFF << (8 - $keep)) & 0xFF;
            $masked .= chr(ord($packed[$i]) & $mask);
        }
        return inet_ntop($masked) . "/" . $prefix;
    }

    public static function aclValidName($name)
    {
        $name = trim((string)$name);
        if (!preg_match('/^[A-Za-z0-9._-]{1,64}$/', $name)) {
            return false;
        }
        $lower = strtolower($name);
        if ($lower === "domains" || substr($lower, -5) === ".auto") {
            return false;
        }
        return true;
    }

    private function aclPlanChanges($ops)
    {
        if (!is_array($ops) || count($ops) === 0) {
            return ["error" => "There are no ACL changes to save."];
        }
        if (count($ops) > self::ACL_MAX_OPS) {
            return ["error" => "Too many changes in one save. Save at most " . self::ACL_MAX_OPS . " at a time."];
        }

        $state = $this->aclLoadState();
        $refs = $this->aclReferences();
        $gatewayCidrs = [];
        foreach ($this->db->fetchAll("SELECT realm, proxy FROM v_gateways", \Phalcon\Db\Enum::FETCH_ASSOC) as $row) {
            foreach ([$row["realm"] ?? "", $row["proxy"] ?? ""] as $host) {
                $host = preg_replace('/:\d+$/', '', trim((string)$host));
                $cidr = self::aclNormaliseCidr($host);
                if ($cidr !== null) {
                    $gatewayCidrs[$cidr] = true;
                }
            }
        }

        $normalised = [];
        $summary = [];
        $warnings = [];
        $newIndex = 0;

        $findByName = function ($name) use (&$state) {
            foreach ($state as $uuid => $list) {
                if (strtolower($list["name"]) === strtolower($name)) {
                    return $uuid;
                }
            }
            return null;
        };
        $nodeInput = function ($raw) {
            if (!is_array($raw)) {
                return ["error" => "An ACL entry is malformed."];
            }
            $type = strtolower(trim((string)($raw["type"] ?? "allow")));
            if (!in_array($type, ["allow", "deny"], true)) {
                return ["error" => "An ACL entry must be allow or deny."];
            }
            $cidr = self::aclNormaliseCidr($raw["cidr"] ?? "");
            if ($cidr === null) {
                return ["error" => "\"" . trim((string)($raw["cidr"] ?? "")) . "\" is not a valid IP address or CIDR range."];
            }
            if ($type === "allow" && substr($cidr, -2) === "/0") {
                return ["error" => "An allow entry for " . $cidr . " would trust every address. Set the list default instead."];
            }
            $description = trim((string)($raw["description"] ?? ""));
            if (strlen($description) > 255) {
                return ["error" => "An ACL entry description is longer than 255 characters."];
            }
            return ["type" => $type, "cidr" => $cidr, "description" => $description];
        };
        $duplicate = function ($listUuid, $type, $cidr, $exceptNode = null) use (&$state) {
            foreach ($state[$listUuid]["nodes"] as $nodeUuid => $node) {
                if ($nodeUuid !== $exceptNode && $node["type"] === $type && $node["cidr"] === $cidr) {
                    return true;
                }
            }
            return false;
        };
        $guard = function ($listUuid, $what) use (&$state) {
            if (!isset($state[$listUuid])) {
                return "One of the ACL lists changed while you were editing. Reload and try again.";
            }
            if (in_array(strtolower($state[$listUuid]["name"]), self::ACL_READONLY_LISTS, true)) {
                return $state[$listUuid]["name"] . " is managed by the server and cannot be " . $what . ".";
            }
            return null;
        };

        foreach ($ops as $op) {
            if (!is_array($op)) {
                return ["error" => "An ACL change is malformed."];
            }
            $kind = (string)($op["op"] ?? "");

            if ($kind === "createList") {
                $name = trim((string)($op["name"] ?? ""));
                if (!self::aclValidName($name)) {
                    return ["error" => "\"" . $name . "\" is not a valid list name. Use letters, numbers, dot, dash or underscore (max 64), not ending in .auto."];
                }
                if ($findByName($name) !== null) {
                    return ["error" => "A list named " . $name . " already exists."];
                }
                $default = strtolower(trim((string)($op["default"] ?? "deny")));
                if (!in_array($default, ["allow", "deny"], true)) {
                    return ["error" => "A list default must be allow or deny."];
                }
                $description = trim((string)($op["description"] ?? ""));
                $ref = "new:" . $newIndex++;
                $state[$ref] = ["name" => $name, "default" => $default, "description" => $description, "nodes" => []];
                $nodes = [];
                foreach ((is_array($op["nodes"] ?? null) ? $op["nodes"] : []) as $rawNode) {
                    $node = $nodeInput($rawNode);
                    if (isset($node["error"])) {
                        return $node;
                    }
                    if ($duplicate($ref, $node["type"], $node["cidr"])) {
                        return ["error" => $node["cidr"] . " is listed twice in " . $name . "."];
                    }
                    $state[$ref]["nodes"]["new-node:" . count($nodes)] = $node;
                    $nodes[] = $node;
                }
                $normalised[] = ["op" => "createList", "ref" => $ref, "name" => $name, "default" => $default, "description" => $description, "nodes" => $nodes];
                $summary[] = "New list " . $name . " (default " . $default . ", " . count($nodes) . " entries)";
                continue;
            }

            if ($kind === "updateList" || $kind === "deleteList") {
                $uuid = (string)($op["uuid"] ?? "");
                $blocked = $guard($uuid, $kind === "deleteList" ? "deleted" : "changed");
                if ($blocked !== null) {
                    return ["error" => $blocked];
                }
                $list = $state[$uuid];
                $lower = strtolower($list["name"]);
                $isSystem = in_array($lower, self::ACL_SYSTEM_LISTS, true);

                if ($kind === "deleteList") {
                    if ($isSystem) {
                        return ["error" => $list["name"] . " is a system list and cannot be deleted."];
                    }
                    if (!empty($refs[$lower])) {
                        return ["error" => $list["name"] . " is used by " . implode(", ", $refs[$lower]) . " and cannot be deleted."];
                    }
                    unset($state[$uuid]);
                    $normalised[] = ["op" => "deleteList", "uuid" => $uuid];
                    $summary[] = "Delete list " . $list["name"] . " (" . count($list["nodes"]) . " entries)";
                    continue;
                }

                $name = array_key_exists("name", $op) ? trim((string)$op["name"]) : $list["name"];
                $default = array_key_exists("default", $op) ? strtolower(trim((string)$op["default"])) : $list["default"];
                $description = array_key_exists("description", $op) ? trim((string)$op["description"]) : $list["description"];
                if (!in_array($default, ["allow", "deny"], true)) {
                    return ["error" => "A list default must be allow or deny."];
                }
                if ($name !== $list["name"]) {
                    if ($isSystem) {
                        return ["error" => $list["name"] . " is a system list and cannot be renamed."];
                    }
                    if (!empty($refs[$lower])) {
                        return ["error" => $list["name"] . " is used by " . implode(", ", $refs[$lower]) . " and cannot be renamed."];
                    }
                    if (!self::aclValidName($name)) {
                        return ["error" => "\"" . $name . "\" is not a valid list name."];
                    }
                    $other = $findByName($name);
                    if ($other !== null && $other !== $uuid) {
                        return ["error" => "A list named " . $name . " already exists."];
                    }
                }
                if ($isSystem && $default !== $list["default"]) {
                    return ["error" => "The default of " . $list["name"] . " is managed by the server and cannot be changed."];
                }
                $changes = [];
                if ($name !== $list["name"]) $changes[] = "rename to " . $name;
                if ($default !== $list["default"]) $changes[] = "default " . $list["default"] . " -> " . $default;
                if ($description !== $list["description"]) $changes[] = "description";
                if (count($changes) === 0) {
                    continue;
                }
                if ($default === "allow" && $list["default"] !== "allow" && !empty($refs[$lower])) {
                    $warnings[] = $list["name"] . " now allows every address it does not list, and it is used by " . implode(", ", $refs[$lower]) . ".";
                }
                $state[$uuid]["name"] = $name;
                $state[$uuid]["default"] = $default;
                $state[$uuid]["description"] = $description;
                $normalised[] = ["op" => "updateList", "uuid" => $uuid, "name" => $name, "default" => $default, "description" => $description];
                $summary[] = $list["name"] . ": " . implode(", ", $changes);
                continue;
            }

            if ($kind === "addNode") {
                $listUuid = (string)($op["listUuid"] ?? "");
                $blocked = $guard($listUuid, "edited");
                if ($blocked !== null) {
                    return ["error" => $blocked];
                }
                $node = $nodeInput($op);
                if (isset($node["error"])) {
                    return $node;
                }
                if ($duplicate($listUuid, $node["type"], $node["cidr"])) {
                    return ["error" => $node["cidr"] . " is already in " . $state[$listUuid]["name"] . "."];
                }
                if (count($state[$listUuid]["nodes"]) >= self::ACL_MAX_NODES_PER_LIST) {
                    return ["error" => $state[$listUuid]["name"] . " already holds the maximum of " . self::ACL_MAX_NODES_PER_LIST . " entries."];
                }
                $state[$listUuid]["nodes"]["new-node:" . count($normalised)] = $node;
                $normalised[] = ["op" => "addNode", "listUuid" => $listUuid] + $node;
                $summary[] = $state[$listUuid]["name"] . ": + " . $node["type"] . " " . $node["cidr"];
                continue;
            }

            if ($kind === "updateNode" || $kind === "deleteNode") {
                $nodeUuid = (string)($op["uuid"] ?? "");
                $listUuid = null;
                foreach ($state as $candidate => $list) {
                    if (isset($list["nodes"][$nodeUuid])) {
                        $listUuid = $candidate;
                        break;
                    }
                }
                if ($listUuid === null || strpos($nodeUuid, "new-node:") === 0) {
                    return ["error" => "One of the ACL entries changed while you were editing. Reload and try again."];
                }
                $blocked = $guard($listUuid, "edited");
                if ($blocked !== null) {
                    return ["error" => $blocked];
                }
                $before = $state[$listUuid]["nodes"][$nodeUuid];
                $listName = $state[$listUuid]["name"];

                if ($kind === "deleteNode") {
                    unset($state[$listUuid]["nodes"][$nodeUuid]);
                    $normalised[] = ["op" => "deleteNode", "uuid" => $nodeUuid];
                    $summary[] = $listName . ": - " . $before["type"] . " " . $before["cidr"];
                    if (strtolower($listName) === "providers" && isset($gatewayCidrs[$before["cidr"]])) {
                        $warnings[] = $before["cidr"] . " belongs to a configured trunk and will be added back to providers by the next trunk or security sync.";
                    }
                    continue;
                }

                $node = $nodeInput($op + $before);
                if (isset($node["error"])) {
                    return $node;
                }
                if ($node === $before) {
                    continue;
                }
                if ($duplicate($listUuid, $node["type"], $node["cidr"], $nodeUuid)) {
                    return ["error" => $node["cidr"] . " is already in " . $listName . "."];
                }
                $state[$listUuid]["nodes"][$nodeUuid] = $node;
                $normalised[] = ["op" => "updateNode", "uuid" => $nodeUuid] + $node;
                $summary[] = $listName . ": " . $before["type"] . " " . $before["cidr"] . " -> " . $node["type"] . " " . $node["cidr"];
                continue;
            }

            return ["error" => "Unknown ACL change \"" . $kind . "\"."];
        }

        if (count($normalised) === 0) {
            return ["error" => "There are no ACL changes to save."];
        }

        return ["ops" => $normalised, "summary" => $summary, "warnings" => $warnings];
    }

    private function aclApplyChanges(array $ops, string $userUuid)
    {
        $random = new \Phalcon\Security\Random();
        $actor = preg_match('/^[0-9a-fA-F-]{36}$/', $userUuid) ? $userUuid : null;

        $this->db->begin();
        try {
            foreach ($ops as $op) {
                switch ($op["op"]) {
                    case "createList":
                        $uuid = $random->uuid();
                        $this->db->execute(
                            "INSERT INTO v_access_controls (access_control_uuid, access_control_name, access_control_default, access_control_description, insert_date, insert_user)
                             VALUES (?, ?, ?, ?, now(), ?)",
                            [$uuid, $op["name"], $op["default"], $op["description"] === "" ? null : $op["description"], $actor]
                        );
                        foreach ($op["nodes"] as $node) {
                            $this->aclInsertNode($random->uuid(), $uuid, $node, $actor);
                        }
                        break;
                    case "updateList":
                        $this->db->execute(
                            "UPDATE v_access_controls
                                SET access_control_name = ?, access_control_default = ?, access_control_description = ?, update_date = now(), update_user = ?
                              WHERE access_control_uuid = ?",
                            [$op["name"], $op["default"], $op["description"] === "" ? null : $op["description"], $actor, $op["uuid"]]
                        );
                        break;
                    case "deleteList":
                        $this->db->execute("DELETE FROM v_access_control_nodes WHERE access_control_uuid = ?", [$op["uuid"]]);
                        $this->db->execute("DELETE FROM v_access_controls WHERE access_control_uuid = ?", [$op["uuid"]]);
                        break;
                    case "addNode":
                        $this->aclInsertNode($random->uuid(), $op["listUuid"], $op, $actor);
                        break;
                    case "updateNode":
                        $this->db->execute(
                            "UPDATE v_access_control_nodes
                                SET node_type = ?, node_cidr = ?, node_description = ?, update_date = now(), update_user = ?
                              WHERE access_control_node_uuid = ?",
                            [$op["type"], $op["cidr"], $op["description"] === "" ? null : $op["description"], $actor, $op["uuid"]]
                        );
                        break;
                    case "deleteNode":
                        $this->db->execute("DELETE FROM v_access_control_nodes WHERE access_control_node_uuid = ?", [$op["uuid"]]);
                        break;
                    default:
                        throw new \RuntimeException("unknown acl op " . $op["op"]);
                }
            }
            $this->db->commit();
        } catch (\Throwable $e) {
            $this->db->rollback();
            throw $e;
        }
    }

    private function aclInsertNode(string $nodeUuid, string $listUuid, array $node, $actor)
    {
        $this->db->execute(
            "INSERT INTO v_access_control_nodes (access_control_node_uuid, access_control_uuid, node_type, node_cidr, node_description, insert_date, insert_user)
             VALUES (?, ?, ?, ?, ?, now(), ?)",
            [$nodeUuid, $listUuid, $node["type"], $node["cidr"], $node["description"] === "" ? null : $node["description"], $actor]
        );
    }

	public function datareportsAction()
	{
		$this->view->setRenderLevel(View::LEVEL_NO_RENDER);
		$this->response->setHeader("Content-Type", "application/json");
