			//     "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_INT],
			// ]);

			// if (empty($qDevice)) {
			//     $response = json_encode([
			//         "result" => "error",
			//         "message" => "Disallowed request.",
			//     ]);
			//     $this->response->setContent($response);
			//     return $this->response;
			// }

			$reportsForm = new ReportsForm();
			if (!$reportsForm->isValid($parameters)) {
				$messages = $reportsForm->getMessages();
				$message = "";
				foreach ($messages as $error) {
					$message .= $error . " ";
				}
				$response = json_encode([
					"result" => "error",
					"message" => trim($message) . " (Code AQ1005)",
				]);
				$this->response->setContent($response);
				return $this->response;
			}

		if ($parameters["type"] === "Wrap Up") {
			$QWrapupnotesList = QWrapupnotesList::find([
				'conditions' => 'insert_date BETWEEN :dateFrom: AND :dateTo: AND domain_uuid = :domainUuid:',
				'bind' => [
					'dateFrom' => $parameters["dateFrom"],
					'dateTo' => $parameters["dateTo"],
					'domainUuid' => $parameters["domainUuid"],
				],
				'order' => 'id DESC',
				'limit' => 10,
			]);
			// Ensure that the response data is properly set and is an array
			if ($QWrapupnotesList === false || $QWrapupnotesList->count() === 0) {
			    $response = json_encode([
			        "result" => "error",
			        "message" => "There is no Data to find",
			    ]);
			    $this->response->setContent($response);
			    return $this->response;
			}

			// Retrieve additional data from the database
			$QWrapupnotes = QWrapupnotes::find();
			$VCallCenterQueues = VCallCenterQueues::find();
			$VXmlCdr = VXmlCdr::find();

			// Create maps for quick lookup
			$queueNameMap = [];
			foreach ($VCallCenterQueues as $queue) {
			    $queueNameMap[$queue->domain_uuid] = $queue->queue_name;
			}

			$wrapupnotesMap = [];
			foreach ($QWrapupnotes as $note) {
			    $wrapupnotesMap[$note->domain_uuid] = $note->wrapup_note;
			}

			$sipCallIdMap = [];
			foreach ($VXmlCdr as $cdr) {
			    $sipCallIdMap[$cdr->domain_uuid] = $cdr->sip_call_id;
			}

			// Initialize an array to store the data
			$dataArray = [];

			if ($QWrapupnotesList->count() > 0) {
			    $index = 1;
			    foreach ($QWrapupnotesList as $note) {
			        $note->queue_name = null;
			        $note->sip_call_id = null;

			        if (isset($wrapupnotesMap[$note->domain_uuid])) {
			            $note->wrapup_note = $wrapupnotesMap[$note->domain_uuid];
			        }

			        if (isset($queueNameMap[$note->domain_uuid])) {
			            $note->queue_name = $queueNameMap[$note->domain_uuid];
			        }

			        if (isset($sipCallIdMap[$note->domain_uuid])) {
			            $note->sip_call_id = $sipCallIdMap[$note->domain_uuid];
			        }

			        // Save data to the array
			        $dataArray[] = [
			            'id' => $index,
			            'username' => ($note->username ?? ''),
			            'contact' => ($note->contact ?? ''),
			            'type' => 'Incoming',
			            'wrapup_note' => ($note->wrapup_note ?? ''),
			            'concern' => 'Customer Concerns',
			            'wrapup_code' => ($note->wrapup_code ?? ''),
			            'queue_name' => ($note->queue_name ?? ''),
			            'insert_date' => ($note->insert_date ?? ''),
			            'sip_call_id' => ($note->sip_call_id ?? '')
			        ];

			        $index++;
			    }
			}

			// Convert the data array to JSON
			$responseData = json_encode([
			    "result" => "success",
			    "data" => $dataArray
			]);

			$this->response->setContent($responseData);
			return $this->response;

        } elseif ($parameters["type"] === "Call Report") {


			$VXmlCdr = VXmlCdr::find([
				'conditions' => 'caller_id_name = :callerIdName: AND direction = :direction: AND insert_date BETWEEN :dateFrom: AND :dateTo: AND domain_uuid = :domainUuid:',
				'bind' => [
					'callerIdName' => $parameters["callerIdName"],
					'direction' => $parameters["direction"],
					'domainUuid' => $parameters["domainUuid"],
					'dateFrom' => $parameters["dateFrom"],
					'dateTo' => $parameters["dateTo"],
				],
				'limit' => 10,
			]);



			if ($VXmlCdr === false || $VXmlCdr->count() === 0) {
				$response = json_encode([
					"result" => "error",
					"message" => "There is no Data to find",
				]);
				$this->response->setContent($response);
				return $this->response;
			}




			$data = [];

			if ($VXmlCdr->count() > 0) {
				$index = 1;
				foreach ($VXmlCdr as $call) {
					$data[] = [
						'id' => $index,
						'caller_id_number' => ($call->caller_id_number ?? ''),
						'destination_number' => ($call->destination_number ?? ''),
						'direction' => ($call->direction ?? ''),
						'type' => 'Log-in',
						'duration' => ($call->duration ?? ''),
						'insert_date' => ($call->insert_date ?? ''),
						'record_name' => ($call->record_name ?? '')
					];
					$index++;
				}
			}

			$response = json_encode([
				"result" => "success",
				"data" => $data,
			]);

            $this->response->setContent($response);
            return $this->response;


        } elseif ($parameters["type"] === "Aux Code") {

			$qAuxcodesList = QAuxcodesList::find([
				'conditions' => 'insert_date BETWEEN :dateFrom: AND :dateTo: AND username LIKE :username: AND auxcode_status LIKE :auxcode_status: AND domain_uuid = :domainUuid:',
				'bind' => [
					'dateFrom' => $parameters["dateFrom"],
					'dateTo' => $parameters["dateTo"],
					'username' => '%' . $parameters["username"] . '%',
					'auxcode_status' => $parameters["auxcode_status"],
					'domainUuid' => $parameters["domainUuid"],
				],
				'limit' => 10,
			]);

			if ($qAuxcodesList === false || $qAuxcodesList->count() === 0) {
