    private function applyCallForwarding($parameters, $qCallBehavior, $vExtension, $session) {
         $call_profile = intval($this->redis->get($vExtension->extension . "+" . $session["subdomain"]));
         if (!empty($parameters["forward_all_destination"])) {
            $forward_all_destination = $qCallBehavior->forward_all_destination = $this->dialPlanEntry($parameters["forward_all_destination"], $vExtension->extension);
            $forward_all_destination = explode(",", $forward_all_destination);
            $vExtension->forward_all_destination = $forward_all_destination[$call_profile];
            $this->redis->del($vExtension->extension . "@" . $session["subdomain"] . "-forward-all-destination");
            $this->redis->rpush($vExtension->extension . "@" . $session["subdomain"] . "-forward-all-destination", $this->dialPlanEntry2($parameters["forward_all_destination"], $vExtension->extension));
         }
         if (!empty($parameters["forward_all_destination2"])) {
            $forward_all_destination2 = $qCallBehavior->forward_all_destination2 = $this->dialPlanEntry($parameters["forward_all_destination2"], $vExtension->extension);
            $forward_all_destination2 = explode(",", $forward_all_destination2);
            $vExtension->forward_all_destination2 = $forward_all_destination2[$call_profile];
            $this->redis->del($vExtension->extension . "@" . $session["subdomain"] . "-forward-all-destination2");
            $this->redis->rpush($vExtension->extension . "@" . $session["subdomain"] . "-forward-all-destination2", $this->dialPlanEntry2($parameters["forward_all_destination2"], $vExtension->extension));
         }
         if (!empty($parameters["forward_busy_destination"])) {
            $forward_busy_destination = $qCallBehavior->forward_busy_destination = $this->dialPlanEntry($parameters["forward_busy_destination"], $vExtension->extension);
            $forward_user_not_registered_destination = $qCallBehavior->forward_user_not_registered_destination = $this->dialPlanEntry($parameters["forward_busy_destination"], $vExtension->extension);
            $forward_busy_destination = explode(",", $forward_busy_destination);
            $forward_user_not_registered_destination = explode(",", $forward_user_not_registered_destination);
            $vExtension->forward_busy_destination = $forward_busy_destination[$call_profile];
            $vExtension->forward_user_not_registered_destination = $forward_user_not_registered_destination[$call_profile];
            $this->redis->del($vExtension->extension . "@" . $session["subdomain"] . "-forward-busy-destination");
            $this->redis->rpush($vExtension->extension . "@" . $session["subdomain"] . "-forward-busy-destination", $this->dialPlanEntry2($parameters["forward_busy_destination"], $vExtension->extension));
         }
         if (!empty($parameters["forward_busy_destination2"])) {
            $forward_busy_destination2 = $qCallBehavior->forward_busy_destination2 = $this->dialPlanEntry($parameters["forward_busy_destination2"], $vExtension->extension);
            $forward_user_not_registered_destination2 = $qCallBehavior->forward_user_not_registered_destination2 = $this->dialPlanEntry($parameters["forward_busy_destination2"], $vExtension->extension);
            $forward_busy_destination2 = explode(",", $forward_busy_destination2);
            $forward_user_not_registered_destination2 = explode(",", $forward_user_not_registered_destination2);
            $vExtension->forward_busy_destination2 = $forward_busy_destination2[$call_profile];
            $vExtension->forward_user_not_registered_destination2 = $forward_user_not_registered_destination2[$call_profile];
            $this->redis->del($vExtension->extension . "@" . $session["subdomain"] . "-forward-busy-destination2");
            $this->redis->rpush($vExtension->extension . "@" . $session["subdomain"] . "-forward-busy-destination2", $this->dialPlanEntry2($parameters["forward_busy_destination2"], $vExtension->extension));
         }
         if (!empty($parameters["forward_no_answer_destination"])) {
            $forward_no_answer_destination = $qCallBehavior->forward_no_answer_destination = $this->dialPlanEntry($parameters["forward_no_answer_destination"], $vExtension->extension);
            $forward_no_answer_destination = explode(",", $forward_no_answer_destination);
            $vExtension->forward_no_answer_destination = $forward_no_answer_destination[$call_profile];
            $this->redis->del($vExtension->extension . "@" . $session["subdomain"] . "-forward-no-answer-destination");
            $this->redis->rpush($vExtension->extension . "@" . $session["subdomain"] . "-forward-no-answer-destination", $this->dialPlanEntry2($parameters["forward_no_answer_destination"], $vExtension->extension));
         }
         if (!empty($parameters["forward_no_answer_destination2"])) {
            $forward_no_answer_destination2 = $qCallBehavior->forward_no_answer_destination2 = $this->dialPlanEntry($parameters["forward_no_answer_destination2"], $vExtension->extension);
            $forward_no_answer_destination2 = explode(",", $forward_no_answer_destination2);
            $vExtension->forward_no_answer_destination2 = $forward_no_answer_destination2[$call_profile];
            $this->redis->del($vExtension->extension . "@" . $session["subdomain"] . "-forward-no-answer-destination2");
            $this->redis->rpush($vExtension->extension . "@" . $session["subdomain"] . "-forward-no-answer-destination2", $this->dialPlanEntry2($parameters["forward_no_answer_destination2"], $vExtension->extension));
         }
         if (!empty($parameters["forward_no_answer_timeout"])) {
            $forward_no_answer_timeout = explode(",", $parameters["forward_no_answer_timeout"]);
            $vExtension->call_timeout = !empty($parameters["forward_no_answer_timeout"]) ? intval($forward_no_answer_timeout[$call_profile]) : 30;
            $qCallBehavior->forward_no_answer_timeout = $this->dialPlanEntry($parameters["forward_no_answer_timeout"], $vExtension->extension);
            $this->redis->del($vExtension->extension . "@" . $session["subdomain"] . "-forward-no-answer-timeout");
            $this->redis->rpush($vExtension->extension . "@" . $session["subdomain"] . "-forward-no-answer-timeout", $this->dialPlanEntry2($parameters["forward_no_answer_timeout"]));
         }
         if (!empty($parameters["forward_no_answer_timeout2"])) {
            $forward_no_answer_timeout2 = explode(",", $parameters["forward_no_answer_timeout2"]);
            $vExtension->call_timeout2 = !empty($parameters["forward_no_answer_timeout2"]) ? intval($forward_no_answer_timeout2[$call_profile]) : 30;
            $qCallBehavior->forward_no_answer_timeout2 = $this->dialPlanEntry($parameters["forward_no_answer_timeout2"], $vExtension->extension);
            $this->redis->del($vExtension->extension . "@" . $session["subdomain"] . "-forward-no-answer-timeout2");
            $this->redis->rpush($vExtension->extension . "@" . $session["subdomain"] . "-forward-no-answer-timeout2", $this->dialPlanEntry2($parameters["forward_no_answer_timeout2"]));
         }
         if (!empty($parameters["forward_all_enabled"])) {
            $forward_all_enabled = $qCallBehavior->forward_all_enabled = $parameters["forward_all_enabled"];
            $forward_all_enabled = explode(",", $forward_all_enabled);
            $vExtension->forward_all_enabled = $forward_all_enabled[$call_profile];
            if ($forward_all_enabled[$call_profile] == "false") {
               $vExtension->forward_all_destination = null;
            }
            $this->redis->del($parameters["extension"] . "@" . $session["subdomain"] . "-forward-all-enabled");
            $this->redis->rpush($parameters["extension"] . "@" . $session["subdomain"] . "-forward-all-enabled", $this->dialPlanEntry2($parameters["forward_all_enabled"]));
         }
         if (!empty($parameters["forward_all_enabled2"])) {
            $forward_all_enabled2 = $qCallBehavior->forward_all_enabled2 = $parameters["forward_all_enabled2"];
            $forward_all_enabled2 = explode(",", $forward_all_enabled2);
            $vExtension->forward_all_enabled2 = $forward_all_enabled2[$call_profile];
            if ($forward_all_enabled2[$call_profile] == "false") {
               $vExtension->forward_all_destination2 = null;
