            $forward_busy_enabled = explode(",", $forward_busy_enabled);
            $vExtension->forward_busy_enabled = $forward_busy_enabled[$call_profile];
            $qCallBehavior->forward_user_not_registered_enabled = $parameters["forward_busy_enabled"];
            $this->redis->del($vExtension->extension . "@" . $session["subdomain"] . "-forward-busy-enabled");
            $this->redis->rpush($vExtension->extension . "@" . $session["subdomain"] . "-forward-busy-enabled", $this->dialPlanEntry2($parameters["forward_busy_enabled"]));
         }
         if (!empty($parameters["forward_busy_enabled2"])) {
            $forward_busy_enabled2 = $qCallBehavior->forward_busy_enabled2 = $parameters["forward_busy_enabled2"];
            $forward_busy_enabled2 = explode(",", $forward_busy_enabled2);
            $vExtension->forward_busy_enabled2 = $forward_busy_enabled2[$call_profile];
            $qCallBehavior->forward_user_not_registered_enabled2 = $parameters["forward_busy_enabled2"];
            $this->redis->del($vExtension->extension . "@" . $session["subdomain"] . "-forward-busy-enabled2");
            $this->redis->rpush($vExtension->extension . "@" . $session["subdomain"] . "-forward-busy-enabled2", $this->dialPlanEntry2($parameters["forward_busy_enabled2"]));
         }
         if (!empty($parameters["forward_no_answer_enabled"])) {
            $forward_no_answer_enabled = $qCallBehavior->forward_no_answer_enabled = $parameters["forward_no_answer_enabled"];
            $forward_no_answer_enabled = explode(",", $forward_no_answer_enabled);
            $vExtension->forward_no_answer_enabled = $forward_no_answer_enabled[$call_profile];
            $this->redis->del($vExtension->extension . "@" . $session["subdomain"] . "-forward-no-answer-enabled");
            $this->redis->rpush($vExtension->extension . "@" . $session["subdomain"] . "-forward-no-answer-enabled", $this->dialPlanEntry2($parameters["forward_no_answer_enabled"]));
         }
         if (!empty($parameters["forward_no_answer_enabled2"])) {
            $forward_no_answer_enabled2 = $qCallBehavior->forward_no_answer_enabled2 = $parameters["forward_no_answer_enabled2"];
            $forward_no_answer_enabled2 = explode(",", $forward_no_answer_enabled2);
            $vExtension->forward_no_answer_enabled2 = $forward_no_answer_enabled2[$call_profile];
            $this->redis->del($vExtension->extension . "@" . $session["subdomain"] . "-forward-no-answer-enabled2");
            $this->redis->rpush($vExtension->extension . "@" . $session["subdomain"] . "-forward-no-answer-enabled2", $this->dialPlanEntry2($parameters["forward_no_answer_enabled2"]));
         }
         if (!empty($parameters["follow_me_enabled"])) {
            $qCallBehavior->follow_me_enabled = $parameters["follow_me_enabled"];
            $this->redis->del($vExtension->extension . "@" . $session["subdomain"] . "-forward-me-enabled");
            $this->redis->rpush($vExtension->extension . "@" . $session["subdomain"] . "-forward-me-enabled", $this->dialPlanEntry2($parameters["follow_me_enabled"]));
         }
         if (!empty($parameters["follow_me_enabled2"])) {
            $qCallBehavior->follow_me_enabled2 = $parameters["follow_me_enabled2"];
            $this->redis->del($vExtension->extension . "@" . $session["subdomain"] . "-forward-me-enabled2");
            $this->redis->rpush($vExtension->extension . "@" . $session["subdomain"] . "-forward-me-enabled2", $this->dialPlanEntry2($parameters["follow_me_enabled2"]));
         }
         if (!empty($parameters["simultaneous_destination_enabled"])) {
            $qCallBehavior->simultaneous_destination_enabled = $parameters["simultaneous_destination_enabled"];
