            $qCallBehavior->call_screening2 = $parameters["call_screening2"];
            $this->redis->del($vExtension->extension . "@" . $session["subdomain"] . "-callScreening2");
            $this->redis->rpush($vExtension->extension . "@" . $session["subdomain"] . "-callScreening2", explode(",", $parameters["call_screening2"]));
         }
        $qOutboundRules = QOutboundRules::find([
            "conditions" => "domain_uuid = :domain_uuid:",
            "bind" => [
               "domain_uuid" => $session["domain_uuid"],
            ],
            "order" => "dial_plan_order ASC"
        ]);
        $gateway_uuid = "";
        $destinationNumber = $qCallBehavior->mobile_number;
        $currentCallProfile = $this->redis->get($vExtension->extension . "+" . $session["subdomain"]);
         if (!empty($parameters["follow_me_destinations"])) {
            $qCallBehavior->follow_me_destinations = $this->followMeSlots($parameters["follow_me_destinations"], $vExtension->extension);
            $this->redis->del($vExtension->extension . "@" . $session["subdomain"] . "-follow-me-destinations");
            $this->redis->rpush($vExtension->extension . "@" . $session["subdomain"] . "-follow-me-destinations", explode(",", $qCallBehavior->follow_me_destinations));
         }
         if (!empty($parameters["follow_me_destinations2"])) {
            $qCallBehavior->follow_me_destinations2 = $this->followMeSlots($parameters["follow_me_destinations2"], $vExtension->extension);
            $this->redis->del($vExtension->extension . "@" . $session["subdomain"] . "-follow-me-destinations2");
            $this->redis->rpush($vExtension->extension . "@" . $session["subdomain"] . "-follow-me-destinations2", explode(",", $qCallBehavior->follow_me_destinations2));
         }
         if (!empty($parameters["follow_me_destinations"]) || !empty($parameters["follow_me_destinations2"]) || !empty($parameters["follow_me_enabled"]) || !empty($parameters["follow_me_enabled2"])) {
            $this->applyFollowMe($vExtension, $qCallBehavior, $qOutboundRules, intval($currentCallProfile), $session);
         }
        if ($qCallBehavior->mobile_number) {
        	foreach($qOutboundRules as $qOutboundRule) {
        	    if (str_starts_with($destinationNumber, $qOutboundRule->prefix_pattern)) {
        			if (str_contains($qOutboundRule->calls_number_length, "-")) {
        				$callsNumberLength = explode("-", $qOutboundRule->calls_number_length);
        				if (strlen($destinationNumber) >= current($callsNumberLength) && strlen($destinationNumber) <= next($callsNumberLength)) {
        			        if ($qOutboundRule->strip) {
        			            $destinationNumber = substr_replace($destinationNumber, "", 0, $qOutboundRule->strip);
        			        }
        			        if ($qOutboundRule->prepend) {
        			            $destinationNumber = $qOutboundRule->prepend . $destinationNumber;
        			        }
        			        $action = strtolower($qOutboundRule->action);
        			        $qGateway2 = VGateways::findFirst(
        			            [
        			                "conditions" => "domain_uuid = :domain_uuid: AND gateway = :gateway:",
        			                "bind" => [
        			                   "domain_uuid" => $session["domain_uuid"],
        			                   "gateway" => $action
        			                ],
        			                "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR]
        			            ]
        			        );
        			        $gateway_uuid = $qGateway2->gateway_uuid;
        			        break;
        				}
        	    	} else if ((strlen($destinationNumber) == $qOutboundRule->calls_number_length || $qOutboundRule->calls_number_length == 0)) {
        		        if ($qOutboundRule->strip) {
        		            $destinationNumber = substr_replace($destinationNumber, "", 0, $qOutboundRule->strip);
        		        }
        		        if ($qOutboundRule->prepend) {
        		            $destinationNumber = $qOutboundRule->prepend . $destinationNumber;
        		        }
        		        $action = strtolower($qOutboundRule->action);
        		        $qGateway2 = VGateways::findFirst(
        		            [
        		                "conditions" => "domain_uuid = :domain_uuid: AND gateway = :gateway:",
        		                "bind" => [
        		                   "domain_uuid" => $session["domain_uuid"],
        		                   "gateway" => $action
        		                ],
        		                "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR]
        		            ]
        		        );
        		        $gateway_uuid = $qGateway2->gateway_uuid;
        		        break;
        	    	}
        	    }
        	}
        }
         $currentCallProfile = $this->redis->get($vExtension->extension . "+" . $session["subdomain"]);
         if ($simultaneousDestinationEnabled[intval($currentCallProfile)] == "true") {
            $qCallBehavior->simultaneous = "1";
            $vExtension->parallel_ring = ",sofia/gateway/{$gateway_uuid}/{$destinationNumber}";
         } else {
            $qCallBehavior->simultaneous = "0";
            $vExtension->parallel_ring = null;
         }
         if ($simultaneousDestinationEnabled2[intval($currentCallProfile)] == "true") {
            $qCallBehavior->simultaneous2 = "1";
            $vExtension->parallel_ring2 = ",sofia/gateway/{$gateway_uuid}/{$destinationNumber}";
         } else {
            $qCallBehavior->simultaneous2 = "0";
            $vExtension->parallel_ring2 = null;
         }
    }

    private function applyDeskPhones($parameters, $vExtension, $session) {
				 $prevRouterTunnels = $this->savedRouterTunnels($parameters["extension"] ."@". $session["subdomain"]. "-macAddresses");
				 $this->srapsSyncLater($parameters["extension"] ."@". $session["subdomain"]. "-macAddresses", $session, $parameters ?? null); // [sraps]
				 $this->redis->del($parameters["extension"] ."@". $session["subdomain"]. "-macAddresses");
				 if (!empty($parameters["mac_address"])) {
				 	$macBrands = explode(",", $parameters["mac_brand"]);
				 	$macModels = explode(",", $parameters["mac_model"]);
				 	$macStuns = explode(",", $parameters["mac_stun"]);
				 	$macTimezones = explode(",", $parameters["mac_timezone"]);
				 	$macAddresses = explode(",", $parameters["mac_address"]);
                    $macTemplateIds  = isset($parameters["mac_template_id"]) ? explode(",", $parameters["mac_template_id"]) : [];
                    $macHostUrls     = isset($parameters["mac_host_url"]) ? explode(",", $parameters["mac_host_url"]) : [];
                    $macRouterTunnels = (isset($parameters["mac_router_tunnel"]) && $parameters["mac_router_tunnel"] !== null) ? explode(",", (string) $parameters["mac_router_tunnel"]) : null;
				 	for($x = 0; $x < count($macAddresses); $x++) { 
                        try { 
                            $macHostUrl = $this->resolveProvisionHostUrl($macHostUrls[$x] ?? "", $session["subdomain"]);
                            $routerTunnelId = $this->resolveRouterTunnel($macRouterTunnels, $x, $macAddresses[$x], $prevRouterTunnels);
                            $this->redis->lpush($parameters["extension"] ."@". $session["subdomain"]. "-macAddresses", $macBrands[$x] ."@". $macModels[$x] ."@". $macAddresses[$x] . "@". $macStuns[$x] ."@". $macTimezones[$x] . "@". $macHostUrl . "@". $routerTunnelId);

                            $hashKey = 'provision:'. str_replace(' ', '',$macBrands[$x]) .':'. str_replace(' ', '',$macModels[$x]);
                            $data = $this->redis->hGetAll($hashKey);
                            $contentTemplate = $this->redis->hGet($hashKey, "value");
                            $phoneBrand = $this->redis->hGet($hashKey, "phoneBrand");
                            $cleanMac = strtolower(str_replace([':', '-'], '', $macAddresses[$x]));
							$subdomain  = $session["subdomain"];
							$registrarHost = ($macHostUrl ?? "") !== "" ? $macHostUrl : $subdomain;
							$provisionBase = $this->provisionBaseUrl($macHostUrl ?? "", $subdomain);

                            if ($macBrands[$x] == 'yealink') {
                                $cfgUpdates = [
									"account.1.enable"                  => "1",
									"account.1.label"                   => $parameters["extension"] . " | " . ($parameters["firstname"] . ' ' . $parameters["lastname"]),
									"account.1.display_name"            => $parameters["firstname"] . ' ' . $parameters["lastname"],
									"account.1.user_name"               => $parameters["username"],
									"account.1.auth_name"               => $parameters["username"],
									"account.1.password"                => $vExtension->password,
									"account.1.stun_server"             => $macStuns[$x],
									"network.stun_server"               => $macStuns[$x],
									"static.sip.nat_stun.server"        => $macStuns[$x],
									"account.1.sip_server.1.address"    => $registrarHost,
									"account.1.sip_server_host.legacy"  => $registrarHost,
									"account.1.voice_mail.number"       => "*99",
									"local_time.time_zone"              => $macTimezones[$x],
									"local_time.time_zone_name"         => $macTimezones[$x],
									"static.auto_provision.server_url"  => "{$provisionBase}/{$cleanMac}.cfg",
								];

								foreach ($cfgUpdates as $key => $value) {
									$pattern = '/^(' . preg_quote($key, '/') . ')\s*=.*$/m';
									if (preg_match($pattern, $contentTemplate)) {
										$contentTemplate = preg_replace($pattern, "$1=$value", $contentTemplate);
									} else {
										$contentTemplate .= "\n{$key}={$value}";
									}
								}

								$provisionKey = "provision:yealink:{$cleanMac}:cfg:" . $parameters["username"];
								$this->redis->set($provisionKey, $contentTemplate);
                            }
                            elseif ($macBrands[$x] == 'fanvil') {
                                libxml_use_internal_errors(true);
                                $xmlObject = simplexml_load_string($contentTemplate);
                                if ($xmlObject === false) {
                                    return $this->response->setJsonContent([
                                        "result" => "error",
                                        "message" => "Invalid XML format in textConfig",
                                        "debug" => libxml_get_errors()
                                    ]);
                                }

                                $xmlUpdates = [
                                    'TimeZone'        => $macTimezones[$x],
                                    'TimeZoneName'    => 'UTC'. $this->timeZoneName($phoneBrand, $macTimezones[$x]),
                                    'STUNServerAddr'  => $macStuns[$x],
                                    'STUNServer'      => $macStuns[$x],
                                    'PhoneNumber'     => $parameters["username"],
                                    'DisplayName'     => $parameters["extension"] . " | " . ($parameters["firstname"] . ' ' . $parameters["lastname"] ?? "User"),
                                    'SipName'         => $registrarHost,
                                    'RegisterAddr'    => $registrarHost,
                                    'RegisterUser'    => $parameters["username"],
                                    'RegisterPswd'    => $vExtension->password,
                                    'DHCPHostname'    => $macModels[$x],
                                ];

                                $this->updateXmlValues($xmlObject, $xmlUpdates);
                                $finalXml = $xmlObject->asXML();
                                $provisionKey = "provision:fanvil:{$cleanMac}:xml:" . $parameters["username"];
                                $this->redis->set($provisionKey, $finalXml);
                            }
                            elseif ($macBrands[$x] == 'snom') {
                                libxml_use_internal_errors(true);
                                $xmlObject = simplexml_load_string($contentTemplate);
                                if ($xmlObject === false) {
                                    return $this->response->setJsonContent([
                                        "result" => "error",
                                        "message" => "Invalid XML format in textConfig",
                                        "debug" => libxml_get_errors()
                                    ]);
                                }

                                $xmlUpdates = [
                                    'setting_server'    => "{$provisionBase}",
                                    'user_realname'     => $parameters["extension"] . " | " . ($parameters["firstname"] . ' ' . $parameters["lastname"] ?? "User"),
                                    'user_name'         => $parameters["username"],
                                    'user_host'         => $registrarHost . ':5060',
                                    'user_pass'         => $vExtension->password,
									'timezone'			=> $macTimezones[$x],
									'stun_server'		=> $macStuns[$x]
                                ];

                                $this->updateXmlValues($xmlObject, $xmlUpdates);
                                $this->applyRouterPhoneXml($xmlObject, $routerTunnelId, $provisionBase, $cleanMac);
                                $finalXml = $xmlObject->asXML();
                                $provisionKey = "provision:snom:{$cleanMac}:xml:" . $parameters["username"];
                                $this->redis->set($provisionKey, $finalXml); 
                            }
							elseif ($macBrands[$x] == 'grandstream') {
								// Ensure we have a valid template before proceeding
								if (empty($contentTemplate)) {
									// Try fetching with exact model name (case-insensitive fallback)
									$modelVariants = [
										$macModels[$x],
										strtoupper($macModels[$x]),
										strtolower($macModels[$x]),
									];
									foreach ($modelVariants as $variant) {
										$fallbackKey = 'provision:grandstream:' . str_replace(' ', '', $variant);
										$contentTemplate = $this->redis->hGet($fallbackKey, "value");
										if (!empty($contentTemplate)) {
											break;
										}
									}
								}

								$cfgUpdates = [
									"P47"     => $registrarHost,
									"P35"     => $parameters["username"],
									"P36"     => $parameters["username"],
									"P34"     => $vExtension->password,
									"P3"      => $parameters["extension"]
								];

								if (!empty($contentTemplate)) {
									foreach ($cfgUpdates as $key => $value) {
										$pattern = '/^(' . preg_quote($key, '/') . ')\s*=.*$/m';
										if (preg_match($pattern, $contentTemplate)) {
											$contentTemplate = preg_replace($pattern, "$1=$value", $contentTemplate);
										} else {
											$contentTemplate .= "\n{$key}={$value}";
										}
									}
								} else {
									// No template found — build minimal config as last resort
									$contentTemplate = "";
									foreach ($cfgUpdates as $key => $value) {
										$contentTemplate .= "{$key}={$value}\n";
									}
									$contentTemplate = trim($contentTemplate);
								}

								$provisionKey = "provision:grandstream:{$cleanMac}:xml:" . $parameters["username"]; 
								$this->redis->set($provisionKey, $contentTemplate);
							}
							elseif ($macBrands[$x] == 'custom') {
                                $phoneTemplate = PhoneTemplates::findFirstById($macTemplateIds[$x]);

                                $contentTemplate = $phoneTemplate->template;

                                if ($phoneTemplate->brand == 'yealink') { 
                                    $cfgUpdates = [
                                        "account.1.enable"                  => "1",
                                        "account.1.label"                   => $parameters["extension"] . " | " . ($parameters["firstname"] . ' ' . $parameters["lastname"]),
                                        "account.1.display_name"            => $parameters["firstname"] . ' ' . $parameters["lastname"],
                                        "account.1.user_name"               => $parameters["username"],
                                        "account.1.auth_name"               => $parameters["username"],
                                        "account.1.password"                => $vExtension->password,
                                        "account.1.stun_server"             => $macStuns[$x],
                                        "network.stun_server"               => $macStuns[$x],
                                        "static.sip.nat_stun.server"        => $macStuns[$x],
                                        "account.1.sip_server.1.address"    => $registrarHost,
                                        "account.1.sip_server_host.legacy"  => $registrarHost,
                                        "account.1.voice_mail.number"       => "*99",
                                        "local_time.time_zone"              => $macTimezones[$x],
                                        "local_time.time_zone_name"         => $macTimezones[$x],
                                        "static.auto_provision.server_url"  => "{$provisionBase}/{$cleanMac}.cfg",
                                    ];

                                    foreach ($cfgUpdates as $key => $value) {
                                        $pattern = '/^(' . preg_quote($key, '/') . ')\s*=.*$/m';
                                        if (preg_match($pattern, $contentTemplate)) {
                                            $contentTemplate = preg_replace($pattern, "$1=$value", $contentTemplate);
                                        } else {
                                            $contentTemplate .= "\n{$key}={$value}";
                                        }
                                    }

                                    $provisionKey = "provision:custom:{$cleanMac}:cfg:" . $parameters["username"];
                                    $this->redis->set($provisionKey, $contentTemplate);
                                }
                                elseif ($phoneTemplate->brand == 'fanvil') {
                                    libxml_use_internal_errors(true);
                                    $xmlObject = simplexml_load_string($contentTemplate);
                                    if ($xmlObject === false) {
                                        return $this->response->setJsonContent([
                                            "result" => "error",
                                            "message" => "Invalid XML format in textConfig",
                                            "debug" => libxml_get_errors()
                                        ]);
                                    }

                                    $xmlUpdates = [
                                        'TimeZone'        => $macTimezones[$x],
                                        'TimeZoneName'    => 'UTC'. $this->timeZoneName($phoneBrand, $macTimezones[$x]),
                                        'STUNServerAddr'  => $macStuns[$x],
                                        'STUNServer'      => $macStuns[$x],
                                        'PhoneNumber'     => $parameters["username"],
                                        'DisplayName'     => $parameters["extension"] . " | " . ($parameters["firstname"] . ' ' . $parameters["lastname"] ?? "User"),
                                        'SipName'         => $registrarHost,
                                        'RegisterAddr'    => $registrarHost,
                                        'RegisterUser'    => $parameters["username"],
                                        'RegisterPswd'    => $vExtension->password,
                                        'DHCPHostname'    => $macModels[$x],
                                    ];

                                    $this->updateXmlValues($xmlObject, $xmlUpdates);
                                    $finalXml = $xmlObject->asXML();
                                    $provisionKey = "provision:custom:{$cleanMac}:xml:" . $parameters["username"];
                                    $this->redis->set($provisionKey, $finalXml);
                                }
                                elseif ($phoneTemplate->brand == 'snom') {
                                    libxml_use_internal_errors(true);
                                    $xmlObject = simplexml_load_string($contentTemplate);
                                    if ($xmlObject === false) {
                                        return $this->response->setJsonContent([
                                            "result" => "error",
                                            "message" => "Invalid XML format in textConfig",
                                            "debug" => libxml_get_errors()
                                        ]);
                                    }

                                    $xmlUpdates = [
                                        'setting_server'    => "{$provisionBase}",
                                        'user_realname'     => $parameters["extension"] . " | " . ($parameters["firstname"] . ' ' . $parameters["lastname"] ?? "User"),
                                        'user_name'         => $parameters["username"],
                                        'user_host'         => $registrarHost . ':5060',
                                        'user_pass'         => $vExtension->password,
                                        'timezone'			=> $macTimezones[$x],
                                        'stun_server'		=> $macStuns[$x]
                                    ];

                                    $this->updateXmlValues($xmlObject, $xmlUpdates);
                                    $this->applyRouterPhoneXml($xmlObject, $routerTunnelId, $provisionBase, $cleanMac);
                                    $finalXml = $xmlObject->asXML();
                                    $provisionKey = "provision:custom:{$cleanMac}:xml:" . $parameters["username"];
                                    $this->redis->set($provisionKey, $finalXml); 
                                }
							}
                        } catch (\Throwable $e) {
                            error_log(json_encode([
                                "result" => "error",
                                "message" => "Something went wrong.",
                                "debug"   => [
                                    "error"   => ControllerBase::safeErrorMessage($e),
                                    "file"    => $e->getFile(),
                                    "line"    => $e->getLine(),
                                ],
                            ], JSON_PRETTY_PRINT));
                        }
				 	}
				 }
        return null;
    }

    private function saveDeskPhones($parameters, $session) {
        require_once __DIR__ . "/../library/McpCatalog.php";
        $fail = function ($message) {
            $this->response->setContent(json_encode([
                "result" => "error",
                "message" => $message,
            ]));
            return $this->response;
        };
        $extension = (string) ($parameters["extension"] ?? "");
        if (!preg_match('/^[0-9]{2,10}$/D', $extension)) {
            return $fail("Give the extension number. (Code AE1040)");
        }
        $op = (string) ($parameters["op"] ?? "");
        if (!in_array($op, ["add", "update", "remove"], true)) {
            return $fail("op must be add, update or remove. (Code AE1041)");
        }
        $mac = McpCatalog::deskPhoneMac($parameters["mac_address"] ?? "");
        if ($mac === null) {
            return $fail("Give the phone's MAC address, 12 hex digits like 0c:38:3e:59:76:d1. (Code AE1042)");
        }
        $vExtension = VExtensions::findFirst([
            "conditions" => "domain_uuid = :domain_uuid: AND extension = :extension:",
            "bind" => [
                "domain_uuid" => $session["domain_uuid"],
                "extension" => intval($extension),
            ],
            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_INT],
        ]);
        if (!$vExtension || !$vExtension->vExtensionUsers) {
            return $fail("Sorry, extension does not exists. (Code AE1043)");
        }
        $vUser = VUsers::findFirst([
            "conditions" => "domain_uuid = :domain_uuid: AND user_uuid = :user_uuid:",
            "bind" => [
                "domain_uuid" => $session["domain_uuid"],
                "user_uuid" => $vExtension->vExtensionUsers->user_uuid,
            ],
            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
        ]);
        if (!$vUser) {
            return $fail("This extension has no user record, so its desk phones cannot be saved here. (Code AE1044)");
        }
        $listKey = $vExtension->extension . "@" . $session["subdomain"] . "-macAddresses";
        $phones = McpCatalog::deskPhoneEntries((array) $this->redis->lrange($listKey, 0, -1));
        $index = null;
        foreach ($phones as $i => $phone) {
            if ($phone["mac"] === $mac) {
                $index = $i;
                break;
            }
        }
        if ($op === "add" && $index !== null) {
            return $fail("A phone with MAC " . $mac . " is already on extension " . $extension . ". Use update to change it. (Code AE1045)");
        }
        if ($op !== "add" && $index === null) {
            return $fail("No phone with MAC " . $mac . " is on extension " . $extension . ". (Code AE1046)");
        }
        if ($op !== "remove") {
            if ($op === "update" && $phones[$index]["brand"] === "custom") {
                return $fail("This phone uses a custom template; change it in the RingQ app. (Code AE1047)");
            }
            $phone = $op === "update" ? $phones[$index] : ["mac" => $mac, "brand" => "", "model" => "", "stun" => "", "timezone" => "", "hostUrl" => "", "routerTunnel" => ""];
            foreach (["brand" => "brand", "model" => "model", "timezone" => "timezone", "stun" => "stun", "host_url" => "hostUrl"] as $field => $key) {
                if (array_key_exists($field, $parameters) && $parameters[$field] !== null) {
                    $phone[$key] = trim((string) $parameters[$field]);
                }
            }
            $phone["brand"] = strtolower($phone["brand"]);
            $choices = [];
            foreach (McpCatalog::deskPhoneChoices((string) $this->redis->get("api_cache:licensecheckuser:" . $session["domain_uuid"])) as $brand) {
                $choices[$brand["name"]] = $brand;
            }
            if ($choices === []) {
                return $fail("The phone models are not loaded on this server yet. Open RingQ in the browser once, then try again. (Code AE1048)");
            }
            if (!isset($choices[$phone["brand"]])) {
                return $fail("brand must be one of: " . implode(", ", array_keys($choices)) . ". (Code AE1049)");
            }
            if (!in_array($phone["model"], $choices[$phone["brand"]]["models"], true)) {
                return $fail("model must be one of the " . $phone["brand"] . " models: " . implode(", ", $choices[$phone["brand"]]["models"]) . ". (Code AE1050)");
            }
            if (!in_array($phone["timezone"], array_column($choices[$phone["brand"]]["timezones"], "value"), true)) {
                return $fail("timezone must be one of the " . $phone["brand"] . " timezone values (see desk_phones.list). (Code AE1051)");
            }
            if (!preg_match('/^[A-Za-z0-9.-]{1,100}(:[0-9]{1,5})?$/D', $phone["stun"])) {
                return $fail("stun must be a STUN server host name, for example stun.ringq.com. (Code AE1052)");
            }
            if ($phone["hostUrl"] === $session["subdomain"]) {
                $phone["hostUrl"] = "";
            }
            if ($phone["hostUrl"] !== "" && $this->resolveProvisionHostUrl($phone["hostUrl"], $session["subdomain"]) === "") {
                return $fail("host_url must be empty (the server address), or a LAN IP of this server or of a tunnel (see desk_phones.list). (Code AE1053)");
            }
            $clean = str_replace(":", "", $mac);
            $other = VUsers::findFirst([
                "conditions" => "domain_uuid = :domain_uuid: AND user_uuid <> :user_uuid: AND (add_user LIKE :plain: OR add_date LIKE :plain: OR add_date LIKE :colon:)",
                "bind" => [
                    "domain_uuid" => $session["domain_uuid"],
                    "user_uuid" => $vUser->user_uuid,
                    "plain" => "%" . $clean . "%",
                    "colon" => "%" . $mac . "%",
                ],
                "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR, Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
            ]);
            if ($other) {
                return $fail("MAC " . $mac . " is already used by another extension. (Code AE1054)");
            }
            if ($op === "add") {
                $phones[] = $phone;
            } else {
                $phones[$index] = $phone;
            }
        } else {
            array_splice($phones, $index, 1);
        }
        $templates = [];
        foreach (PhoneTemplates::find([
            "conditions" => "domain_uuid = :domain_uuid:",
            "bind" => ["domain_uuid" => $session["domain_uuid"]],
        ]) as $template) {
            foreach (array_unique([trim((string) $template->model), trim((string) $template->custom_name)]) as $name) {
                if ($name !== "") {
                    $templates[$name][] = (string) $template->id;
                }
            }
        }
        $ordered = array_reverse($phones);
        $templateIds = [];
        foreach ($ordered as $phone) {
            $ids = $phone["brand"] === "custom" ? ($templates[$phone["model"]] ?? []) : [];
            $templateIds[] = count($ids) === 1 ? $ids[0] : "";
        }
        $macList = implode(",", array_column($ordered, "mac"));
        $deskPhones = [
            "extension" => $vExtension->extension,
            "username" => $vExtension->number_alias,
            "firstname" => (string) $vUser->first_name,
            "lastname" => (string) $vUser->last_name,
            "mac_brand" => implode(",", array_column($ordered, "brand")),
            "mac_model" => implode(",", array_column($ordered, "model")),
            "mac_address" => $macList,
            "mac_stun" => implode(",", array_column($ordered, "stun")),
            "mac_timezone" => implode(",", array_column($ordered, "timezone")),
            "mac_template_id" => implode(",", $templateIds),
            "mac_host_url" => implode(",", array_column($ordered, "hostUrl")),
            "mac_router_tunnel" => null,
        ];
        $this->db->begin();
        $vUser->add_user = $macList !== "" ? str_replace(":", "", $macList) : null;
        $vUser->add_date = $macList !== "" ? $macList : null;
        $deskPhoneError = $this->applyDeskPhones($deskPhones, $vExtension, $session);
        if ($deskPhoneError !== null) {
            $this->db->rollback();
            return $deskPhoneError;
        }
        if (!$vUser->save()) {
            $this->db->rollback();
            return $fail("The desk phones could not be saved. (Code AE1055)");
        }
        $this->db->commit();
        $this->redis->del($session["domain_uuid"] . "-extensions-cache");
        $this->response->setContent(json_encode([
            "result" => "success",
            "message" => ["add" => "Desk phone added.", "update" => "Desk phone updated.", "remove" => "Desk phone removed."][$op],
            "content" => McpCatalog::deskPhoneEntries((array) $this->redis->lrange($listKey, 0, -1)),
        ]));
        return $this->response;
    }

    /**
     * Extensions that may never be deleted (accounts/extension type 5): the
     * signed-in user's own extension, the system owner 1000, and the last
     * extension left in the Owner role. null = deletable.
     */
    private function extensionDeleteBlocker($extension, $session): ?string
    {
        $extension = trim((string) $extension);
        if ($extension === "" || $extension === "0") {
            return null;
        }
        if ($extension === trim((string) ($session["extension"] ?? ""))) {
            return "Sorry, you cannot delete your own extension. (Code AE1030)";
        }
        if ($extension === "1000") {
            return "Sorry, the system owner extension cannot be deleted. (Code AE1031)";
        }
        $modes = QCompanyModes::findFirst([
            "conditions" => "domain_uuid = :domain_uuid:",
            "bind" => ["domain_uuid" => (string) ($session["domain_uuid"] ?? "")],
            "bindTypes" => [Column::BIND_PARAM_STR],
        ]);
        if ($modes) {
            $owners = array_values(array_filter(array_map("trim", explode(",", (string) $modes->permission1)), "strlen"));
            if (in_array($extension, $owners, true) && count(array_diff($owners, [$extension])) === 0) {
                return "Sorry, this is the only Owner extension, so it cannot be deleted. (Code AE1032)";
            }
        }
        return null;
    }

    private function saveCallForwarding($parameters, $session) {
        $fail = function ($message) {
            $this->response->setContent(json_encode([
                "result" => "error",
                "message" => $message,
            ]));
            return $this->response;
        };
        $extension = (string) ($parameters["extension"] ?? "");
        if (!preg_match('/^[0-9]{2,10}$/D', $extension)) {
            return $fail("Give the extension number. (Code AE1030)");
        }
        $destination = '(?:|hangup|\*99[0-9]{2,10}|[0-9]{2,20})';
        $flag = '(?:true|false)';
        $seconds = '[0-9]{1,3}';
        $shapes = [];
        foreach (["", "2"] as $side) {
            $shapes["forward_all_enabled" . $side] = $flag;
            $shapes["forward_all_destination" . $side] = $destination;
            $shapes["forward_busy_enabled" . $side] = $flag;
            $shapes["forward_busy_destination" . $side] = $destination;
            $shapes["forward_no_answer_enabled" . $side] = $flag;
            $shapes["forward_no_answer_destination" . $side] = $destination;
            $shapes["forward_no_answer_timeout" . $side] = $seconds;
            $shapes["call_screening" . $side] = $flag;
            $shapes["simultaneous_destination_enabled" . $side] = $flag;
        }
        $forwarding = ["extension" => intval($extension)];
        foreach ($shapes as $field => $slot) {
            $value = $parameters[$field] ?? null;
            if (!is_string($value) || !preg_match('/^' . $slot . '(?:,' . $slot . '){4}$/D', $value)) {
                return $fail("Send every forwarding field for all five statuses; " . $field . " is missing or not in the expected format. (Code AE1031)");
            }
            $forwarding[$field] = $value;
        }
        $vExtension = VExtensions::findFirst([
            "conditions" => "domain_uuid = :domain_uuid: AND extension = :extension:",
            "bind" => [
                "domain_uuid" => $session["domain_uuid"],
                "extension" => intval($extension),
            ],
            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_INT],
        ]);
        if (!$vExtension) {
            return $fail("Sorry, extension does not exists. (Code AE1032)");
        }
        $qCallBehavior = QCallBehaviors::findFirst([
            "conditions" => "domain_uuid = :domain_uuid: AND extension = :extension: ",
            "bind" => [
                "domain_uuid" => $session["domain_uuid"],
                "extension" => $vExtension->extension,
            ],
            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_INT],
        ]);
        if (!$qCallBehavior) {
            return $fail("This extension has no call settings yet. Open and save it once in the RingQ app first. (Code AE1033)");
        }
        $parallel = strpos($forwarding["simultaneous_destination_enabled"] . "," . $forwarding["simultaneous_destination_enabled2"], "true") !== false;
        if ($parallel && trim((string) $qCallBehavior->mobile_number) === "") {
            return $fail("Parallel ring calls the extension's mobile number, and this extension has none. Set a mobile number first or leave parallel ring off. (Code AE1034)");
        }
        $this->db->begin();
        $this->applyCallForwarding($forwarding, $qCallBehavior, $vExtension, $session);
        $qCallBehavior->update_user = $session["user_uuid"];
        $qCallBehavior->update_date = date("Y-m-d H:i:s");
        if (!$qCallBehavior->save() || !$vExtension->update()) {
            $this->db->rollback();
            return $fail("Call forwarding could not be saved. (Code AE1035)");
        }
        $this->db->commit();
        foreach ([
            "/var/cache/fusionpbx/dialplan." . $session["subdomain"],
            "/var/cache/fusionpbx/directory." . $vExtension->extension . "@" . $session["subdomain"],
            "/var/cache/ringq/dialplan." . $session["subdomain"],
            "/var/cache/ringq/directory." . $vExtension->extension . "@" . $session["subdomain"],
            "/var/cache/ringq/directory." . $vExtension->number_alias . "@" . $session["subdomain"],
        ] as $cache) {
            if (file_exists($cache)) {
                unlink($cache);
            }
        }
        $this->redis->del($session["domain_uuid"] . "-extensions-cache");
        $this->redis->del("vExtensions-" . $session["subdomain"]);
        $this->response->setContent(json_encode([
            "result" => "success",
            "message" => "Call forwarding updated.",
        ]));
        return $this->response;
    }

    private function followMeSlots($value, $extension) {
        $slots = explode(",", (string) $value);
        foreach ($slots as $i => $slot) {
            $parts = [];
            foreach (explode("|", $slot) as $part) {
                $part = trim($part);
                if ($part === "" || $part === "*99" || $part === "*99" . $extension || $part === "hangup") {
                    continue;
                }
                $parts[] = $part;
            }
            $slots[$i] = implode("|", $parts);
        }
        return implode(",", $slots);
    }

    private function followMeTargets($value, $index) {
        $slots = explode(",", (string) $value);
        if (count($slots) > 5) {
            $candidates = array_slice($slots, 0, 3);
        } else {
            $candidates = explode("|", $slots[$index] ?? "");
        }
        $targets = [];
        foreach ($candidates as $candidate) {
            $candidate = trim($candidate);
            if ($candidate === "" || $candidate === "hangup" || str_starts_with($candidate, "*99") || !preg_match('/^\+?[0-9]+$/', $candidate)) {
                continue;
            }
            $targets[] = $candidate;
            if (count($targets) === 3) {
                break;
            }
        }
        return $targets;
    }

    private function applyFollowMe($vExtension, $qCallBehavior, $qOutboundRules, $index, $session) {
        foreach (["" => "follow_internal", "2" => "follow_external"] as $suffix => $column) {
            $vExtension->{$column} = null;
            $vExtension->{$column . "2"} = null;
            $vExtension->{$column . "3"} = null;
            $enabled = explode(",", (string) $qCallBehavior->{"follow_me_enabled" . $suffix});
            if (($enabled[$index] ?? "false") !== "true") {
                continue;
            }
            $position = 0;
            foreach ($this->followMeTargets($qCallBehavior->{"follow_me_destinations" . $suffix}, $index) as $value) {
                if (strlen($value) > 4) {
                    $output = $this->outboundGateway($qOutboundRules, $value, $session);
                    if (!is_array($output) || empty($output[0])) {
                        continue;
                    }
                    $target = "sofia/gateway/{$output[0]}/{$output[1]}";
                } else {
                    $target = "user/" . $value . "@" . $session["subdomain"];
                }
                $vExtension->{$column . ($position === 0 ? "" : strval($position + 1))} = $target;
                $position++;
            }
        }
    }

    private function dialPlanEntry($value = "", $extension = "") {
        $result = array();
        $values = explode(",", $value);
        foreach ($values as $value) {
            if ($value == "Voicemail" || $value == "Own Voicemail" || $value == "") {
                array_push($result, "*99". $extension);
            } else {
                if ($value == "End Call") {
                    array_push($result, "hangup");
                } else {
                    $value2 = explode(" - ", $value);
                    if (str_contains($value, "✉")) {
                        array_push($result, "*99" . $value2[0]);
                    } else {
                        array_push($result, $value2[0]);
                    }
                }
            }
        }
        return implode(",", $result);
    }

    private function dialPlanEntry2($value = "", $extension = "") {
        $result = array();
        $values = explode(",", $value);
        foreach ($values as $value) {
            if ($value == "Voicemail" || $value == "Own Voicemail" || $value == "") {
                array_push($result, "*99". $extension);
            } else {
                if ($value == "End Call") {
                    array_push($result, "hangup");
                } else {
                    $value2 = explode(" - ", $value);
                    if (str_contains($value, "✉")) {
                        array_push($result, "*99" . $value2[0]);
                    } else {
                        array_push($result, $value2[0]);
                    }
                }
            }
        }
        return $result;
    }

    private function sipIdChecker($domainUuid, $extension, $extensionId) {
    	if ($extensionId == "1" || $extensionId == "2" || $extensionId == "3" || $extensionId == "4" || $extensionId == "5" || $extensionId == "6" || $extensionId == "7" || $extensionId == "8" || $extensionId == "9" || $extensionId == "0" || $extensionId == "5555" || $extensionId == "7777" || $extensionId == "3000" || $extensionId == "3001" || $extensionId == "3002" || $extensionId == "3003" || $extensionId == "3004" || $extensionId == "3005") {
    		return false;
    	}
		$emergencyChecker = QOutboundRules::findFirst([
		    "conditions" => "domain_uuid = :domain_uuid: AND prefix_pattern = :prefix_pattern: AND priority < :priority:",
		    "bind" => [
		       "domain_uuid" => $domainUuid,
		       "prefix_pattern" => $extensionId,
		       "priority" => 0
		    ],
	        "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_INT, Column::BIND_PARAM_INT],
		]);
    	if ($emergencyChecker) {
    		return false;
    	}
    	$groupChecker = VRingGroups::findFirst(
    		[
	            "conditions" => "domain_uuid = :domain_uuid: AND ring_group_extension = :ring_group_extension:",
	            "bind" =>
	                [
	                    "domain_uuid" => $domainUuid,
	                    "ring_group_extension" => $extensionId,
	                ],
	            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
    		]
    	);
    	if ($groupChecker) {
    		return false;
    	}
    	$queueChecker = VCallCenterQueues::findFirst(
    		[
	            "conditions" => "domain_uuid = :domain_uuid: AND queue_extension = :queue_extension:",
	            "bind" =>
	                [
	                    "domain_uuid" => $domainUuid,
	                    "queue_extension" => $extensionId,
	                ],
	            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
    		]
    	);
    	if ($queueChecker) {
    		return false;
    	}
    	$ivrChecker = VIvrMenus::findFirst(
    		[
	            "conditions" => "domain_uuid = :domain_uuid: AND ivr_menu_extension = :ivr_menu_extension:",
	            "bind" =>
	                [
	                    "domain_uuid" => $domainUuid,
	                    "ivr_menu_extension" => $extensionId,
	                ],
	            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
    		]
    	);
    	if ($ivrChecker) {
    		return false;
    	}
		$extensionChecker = VExtensions::findFirst(
    		[
	            "conditions" => "domain_uuid = :domain_uuid: AND extension = :extension:",
	            "bind" =>
	                [
	                    "domain_uuid" => $domainUuid,
	                    "extension" => $extensionId,
	                ],
	            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
    		]
    	);
    	if ($extensionChecker) {
	    	return false;
    	}
		$conferenceChecker = VConferenceCenters::findFirst(
    		[
	            "conditions" => "domain_uuid = :domain_uuid: AND conference_center_extension = :conference_center_extension:",
	            "bind" =>
	                [
	                    "domain_uuid" => $domainUuid,
	                    "conference_center_extension" => $extensionId,
	                ],
	            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
    		]
    	);
    	if ($conferenceChecker) {
    		return false;
    	}
		$sipIpChecker = QCallBehaviors::findFirst(
    		[
	            "conditions" => "domain_uuid = :domain_uuid: AND force_ping = :force_ping: AND extension != :extension:",
	            "bind" =>
	                [
	                    "domain_uuid" => $domainUuid,
	                    "force_ping" => $extensionId,
	                    "extension" => $extension
	                ],
	            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
    		]
    	);
    	if ($sipIpChecker) {
	    	return false;
    	}
    	return true;
    }

    private function extensionNumberOwner($domainUuid, $extension)
    {
        $extension = (string) $extension;
        $checks = [
            ["an extension",     VExtensions::class,        "extension"],
            ["a team",           VRingGroups::class,        "ring_group_extension"],
            ["a team voicemail", VVoicemails::class,        "voicemail_id"],
            ["a call queue",     VCallCenterQueues::class,  "queue_extension"],
            ["an IVR",           VIvrMenus::class,          "ivr_menu_extension"],
            ["a conference",     VConferenceCenters::class, "conference_center_extension"],
            ["a conference",     VConferences::class,       "conference_extension"],
            ["an eFax",          VFax::class,               "fax_extension"],
            ["a dialplan entry", VDialplans::class,         "dialplan_number"],
        ];
        foreach ($checks as $check) {
            list($label, $model, $column) = $check;
            $found = $model::findFirst(
                [
                    "conditions" => "domain_uuid = :domain_uuid: AND " . $column . " = :value:",
                    "bind" =>
                        [
                            "domain_uuid" => $domainUuid,
                            "value" => $extension,
                        ],
                    "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                ]
            );
            if ($found) {
                return $label;
            }
        }
        return null;
    }



public function livetranscriptdataAction()
{
    $this->view->disable();
    $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
    $this->response->setHeader("Content-Type", "application/json");

    $rawBody = $this->request->getRawBody();
    $data = json_decode($rawBody, true);

    if (!$data) {
        return $this->response->setJsonContent([
            "result" => "error",
            "message" => "Invalid JSON payload."
        ]);
    }

    if (empty($data['sip_call_id'])) {
        return $this->response->setJsonContent([
            "result" => "error",
            "message" => "sip_call_id is required."
        ]);
    }

    $sipCallId = trim($data['sip_call_id']);

    $cdr = null;
    $maxAttempts = 5;

    for ($attempt = 1; $attempt <= $maxAttempts; $attempt++) {

        $cdr = QRingqCdr::findFirst([
            "conditions" => "(xml_cdr_uuid = :uuid: OR originating_leg_uuid = :uuid:)",
            "bind" => [
                "uuid" => $sipCallId
            ]
        ]);

        if ($cdr) {
            break;
        }

        // Wait 2 seconds before trying again
        if ($attempt < $maxAttempts) {
            sleep(2);
        }
    }

    if (!$cdr) {
        return $this->response->setJsonContent([
            "result" => "error",
            "message" => "Call not found after {$maxAttempts} attempts."
        ]);
    }

    $transcribedText = '';

    if (!empty($data['transcripts']) && is_array($data['transcripts'])) {

        foreach ($data['transcripts'] as $row) {

            $speaker = $row['speaker'] ?? '';
            $text    = $row['text'] ?? '';

            if ($text == '') {
                continue;
            }

            $transcribedText .= $speaker . ': ' . $text . PHP_EOL;
        }
    }

    $payload = [
        "summary" => "No Summary Available",
        "sentiment" => "neutral",
        "transcribedText" => trim($transcribedText),
        "liveTranscript" => $data['transcripts'] ?? [],
        "caller" => $data['caller'] ?? '',
        "agent_extension" => $data['agent_extension'] ?? '',
        "uuid" => $data['uuid'] ?? '',
        "sip_call_id" => $sipCallId
    ];

    $cdr->json = json_encode($payload, JSON_UNESCAPED_UNICODE);

    if (!$cdr->update()) {

        $errors = [];
        foreach ($cdr->getMessages() as $message) {
            $errors[] = (string)$message;
        }

        return $this->response->setJsonContent([
            "result" => "error",
            "message" => implode(", ", $errors)
        ]);
    }

    return $this->response->setJsonContent([
        "result" => "success",
        "message" => "Live transcript saved successfully."
    ]);
}


    function outboundGateway($qOutboundRules = [], $destinationNumber, $session) {
		foreach($qOutboundRules as $qOutboundRule) {
		    if (str_starts_with($destinationNumber, $qOutboundRule->prefix_pattern)) {
				if (str_contains($qOutboundRule->calls_number_length, "-")) {
					$callsNumberLength = explode("-", $qOutboundRule->calls_number_length);
					if (strlen($destinationNumber) >= current($callsNumberLength) && strlen($destinationNumber) <= next($callsNumberLength)) {
				        if ($qOutboundRule->strip) {
				            $destinationNumber = substr_replace($destinationNumber, "", 0, $qOutboundRule->strip);
				        }
				        if ($qOutboundRule->prepend) {
				            $destinationNumber = $qOutboundRule->prepend . $destinationNumber;
				        }
				        $action = strtolower($qOutboundRule->action);
				        $qGateway2 = VGateways::findFirst(
				            [
				                "conditions" => "domain_uuid = :domain_uuid: AND gateway = :gateway:",
				                "bind" => [
				                   "domain_uuid" => $session["domain_uuid"],
				                   "gateway" => $action
				                ],
				                "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR]
				            ]
				        );
				        $gateway_uuid = $qGateway2->gateway_uuid;
				        return [$gateway_uuid, $destinationNumber];
				        break;
					}
		    	} else if ((strlen($destinationNumber) == $qOutboundRule->calls_number_length || $qOutboundRule->calls_number_length == 0)) {
			        if ($qOutboundRule->strip) {
			            $destinationNumber = substr_replace($destinationNumber, "", 0, $qOutboundRule->strip);
			        }
			        if ($qOutboundRule->prepend) {
			            $destinationNumber = $qOutboundRule->prepend . $destinationNumber;
			        }
			        $action = strtolower($qOutboundRule->action);
			        $qGateway2 = VGateways::findFirst(
			            [
			                "conditions" => "domain_uuid = :domain_uuid: AND gateway = :gateway:",
			                "bind" => [
			                   "domain_uuid" => $session["domain_uuid"],
			                   "gateway" => $action
			                ],
			                "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR]
			            ]
			        );
			        $gateway_uuid = $qGateway2->gateway_uuid;
				    return [$gateway_uuid, $destinationNumber];
			        break;
		    	}
		    }
		}
    }

	function arrayToXml($data, $xmlData) {
	    foreach ($data as $key => $value) {
	        if (is_numeric($key)) {
	            $key = 'item' . $key; // handle numeric keys
	        }
	        if (is_array($value)) {
	            if (isset($value['@attributes'])) {
	                // If there are attributes
	                $subnode = $xmlData->addChild($key);
	                foreach ($value['@attributes'] as $attrKey => $attrVal) {
	                    $subnode->addAttribute($attrKey, $attrVal);
	                }

	                // Remove attributes before recursion
	                $childData = $value;
	                unset($childData['@attributes']);
	                $this->arrayToXml($childData, $subnode);
	            } else {
	                // No attributes
	                $subnode = $xmlData->addChild($key);
	                $this->arrayToXml($value, $subnode);
	            }
	        } else {
	            $xmlData->addChild($key, htmlspecialchars($value));
	        }
	    }
	}

	function toLanguageCodes($languagesString) {
	    $map = [
	        'english'   => 'en',
	        'filipino'  => 'tl',
	        'tagalog'   => 'tl',
	        'japanese'  => 'ja',
	        'korean'    => 'ko',
	        'chinese'   => 'zh',
	        'chinese simplified' => 'zh-CN',
	        'chinese traditional' => 'zh-TW',
	        'spanish'   => 'es',
	        'french'    => 'fr',
	        'german'    => 'de',
	        'italian'   => 'it',
	        'portuguese'=> 'pt',
	        'russian'   => 'ru',
	        'vietnamese'=> 'vi',
	        'thai'      => 'th',
	        'arabic'    => 'ar',
	        'hindi'     => 'hi',
	    ];

	    $languages = explode(',', $languagesString);
	    $codes = [];

	    foreach ($languages as $lang) {
	        $key = strtolower(trim($lang));
	        if (isset($map[$key])) {
	            $codes[] = $map[$key];
	        }
	    }
	    return $codes;
	}

    /** [sraps] after this request, re-sync the extension's ticked Snom phones with SRAPS and drop removed ones (old list read now). */
    private function srapsSyncLater($listKey, $session, $parameters = null)
    {
        try {
            if (!class_exists('Sraps') || !\Sraps::enabled()) return;
            // The add-phone form's "RingQ Remote Provisioning (RPS)" checkbox, one "1"/"0" per MAC.
            $rpsFlags = (is_array($parameters) && isset($parameters["mac_rps"]) && $parameters["mac_rps"] !== null)
                ? [explode(",", (string) ($parameters["mac_address"] ?? "")), explode(",", (string) $parameters["mac_rps"])] : null;
            $old = \Sraps::snomMacs((array) $this->redis->lrange($listKey, 0, -1));
            $redis = $this->redis;
            $tenant = (string) ($session["subdomain"] ?? "");
            $parts = explode("-", (string) ($session["domain_uuid"] ?? ""));
            $provKey = (string) end($parts);
            register_shutdown_function(function () use ($redis, $listKey, $old, $tenant, $provKey, $rpsFlags) {
                try {
                    if (function_exists('fastcgi_finish_request')) fastcgi_finish_request();
                    $new = \Sraps::snomMacs((array) $redis->lrange($listKey, 0, -1));
                    $wasOn = \Sraps::wanted($redis, $tenant, array_values(array_unique(array_merge($old, $new))));
                    if ($rpsFlags) {
                        foreach ($rpsFlags[0] as $i => $raw) {
                            $mac = strtolower(preg_replace('/[^0-9a-fA-F]/', '', (string) $raw));
                            if (strlen($mac) !== 12) continue;
                            if (($rpsFlags[1][$i] ?? "0") === "1") $redis->hset("rps-on:$tenant", $mac, "1");
                            else $redis->hdel("rps-on:$tenant", $mac);
                        }
                    }
                    $gone = array_values(array_diff($old, $new));
                    $unticked = array_values(array_diff(array_intersect($wasOn, $new), \Sraps::wanted($redis, $tenant, $new)));
                    \Sraps::sync($tenant, $provKey, \Sraps::wanted($redis, $tenant, $new), array_merge(\Sraps::wanted($redis, $tenant, $gone), $unticked), $redis);
                    foreach ($unticked as $mac) $redis->hdel("sraps:status:$tenant", $mac);
                    foreach ($gone as $mac) $redis->hdel("rps-on:$tenant", $mac);
                } catch (\Throwable $e) {
                    error_log("[sraps] " . $e->getMessage());
                    try { $redis->hset("rps:$tenant", "last_error", date("c") . " " . substr($e->getMessage(), 0, 300)); } catch (\Throwable $e2) {}
                }
            });
        } catch (\Throwable $e) {
            error_log("srapsSyncLater: " . $e->getMessage());
        }
    }

    /** [sraps] the extension is being deleted: after this request, take its RPS phones out of SRAPS. */
    private function srapsDropLater($listKey, $session)
    {
        try {
            if (!class_exists('Sraps') || !\Sraps::enabled()) return;
            $redis = $this->redis;
            $tenant = (string) ($session["subdomain"] ?? "");
            $parts = explode("-", (string) ($session["domain_uuid"] ?? ""));
            $provKey = (string) end($parts);
            $macs = \Sraps::wanted($redis, $tenant, \Sraps::snomMacs((array) $redis->lrange($listKey, 0, -1)));
            if (!$macs) return;
            register_shutdown_function(function () use ($redis, $tenant, $provKey, $macs) {
                try {
                    if (function_exists('fastcgi_finish_request')) fastcgi_finish_request();
                    \Sraps::sync($tenant, $provKey, [], $macs, $redis);
                    foreach ($macs as $mac) { $redis->hdel("rps-on:$tenant", $mac); $redis->hdel("sraps:status:$tenant", $mac); }
                } catch (\Throwable $e) {
                    error_log("[sraps] " . $e->getMessage());
                    try { $redis->hset("rps:$tenant", "last_error", date("c") . " " . substr($e->getMessage(), 0, 300)); } catch (\Throwable $e2) {}
                }
            });
        } catch (\Throwable $e) {
            error_log("srapsDropLater: " . $e->getMessage());
        }
    }

    /**
     * [sraps] RingQ Remote Provisioning (RPS), per phone, admins only:
     *  - op "rpsget": whether RPS is set up on this server, and each Snom phone's Redirect state and SRAPS result.
     *  - op "rpsphone" {mac_address, enabled}: one phone's Redirect checkbox (extension Auto Provisioning row).
     * Returns null for other autoprov requests.
     */
    private function rpsAction($session)
    {
        $body = json_decode((string) $this->request->getRawBody(), true);
        $op = is_array($body) ? (string) ($body["op"] ?? "") : "";
        if ($op !== "rpsget" && $op !== "rpsphone") {
            return null;
        }
        if (method_exists($this, "isPlainUser") && $this->isPlainUser($session)) {
            return $this->forbiddenForUser();
        }
        $tenant = (string) $session["subdomain"];
        $parts = explode("-", (string) $session["domain_uuid"]);
        $provKey = (string) end($parts);
        $results = [];
        $error = "";
        if ($op === "rpsphone") {
            $mac = strtolower(preg_replace('/[^0-9a-fA-F]/', '', (string) ($body["mac_address"] ?? "")));
            if (strlen($mac) !== 12 || !in_array($mac, \Sraps::tenantSnomMacs($this->redis, $tenant), true)) {
                return $this->response->setJsonContent(["result" => "error", "message" => "Save this Snom phone on the extension first."]);
            }
            try {
                $results = \Sraps::setPhone($this->redis, $tenant, $provKey, $mac, !empty($body["enabled"]));
            } catch (\Throwable $e) {
                $error = $e->getMessage();
            }
        }
        $state = \Sraps::tenantState($this->redis, $tenant);
        $phones = [];
        try {
            foreach (\Sraps::tenantSnomMacs($this->redis, $tenant) as $mac) {
                $r = json_decode((string) $this->redis->hget("sraps:status:$tenant", $mac), true);
                $phones[] = ["mac" => implode(":", str_split($mac, 2)), "redirect" => \Sraps::phoneOn($this->redis, $tenant, $mac), "ok" => $r["ok"] ?? null, "action" => $r["action"] ?? "", "message" => $r["msg"] ?? "", "at" => $r["at"] ?? ""];
            }
        } catch (\Throwable $e) {
            error_log("rpsAction: " . $e->getMessage());
        }
        $rpsOn = \Sraps::enabled($tenant); // [rps-proxy] key on this server, or the RPS service acts for this tenant
        return $this->response->setJsonContent([
            "result" => $error === "" ? "success" : "error",
            "message" => $error,
            "data" => [
                "available" => $rpsOn,
                "provisioning_url" => "https://$tenant:8443/provision/$provKey",
                "services" => [["brand" => "Snom", "name" => "SRAPS", "connected" => $rpsOn]],
                "phones" => $phones,
                "last_error" => (string) ($state["last_error"] ?? ""),
            ],
        ]);
    }
}
